# ==================================================================
# -*- coding: utf-8 -*-
"""x32sim/state — 调音台状态 + 唯一写入口 set_value + WriteSink + 电平/推送"""

import math
import struct
import threading
import time



# ---------------------------------------------------------------- 调音台状态

class MixerState:
    def __init__(self):
        self.lock = threading.Lock()
        # 行字典由 params.blank_row 生成: 推子/静音 + 输入通道的 12 个参数
        # (增益/反相/延时/低切/插入/门) 一次带出出厂值。新增参数只改 params.py
        # 一行 —— 曾经这类默认值散落在各处的 __init__ 里, 漏一处就让新参数在
        # snapshot/render 里 KeyError (表现为界面卡旧状态)。
        self.ch = {i: blank_row("ch") for i in range(1, 33)}
        self.bus = {i: blank_row("bus") for i in range(1, 17)}   # 输出通道 Mix Bus 1-16
        self.dca = {i: blank_row("dca") for i in range(1, 9)}
        self.auxin = {i: blank_row("auxin") for i in range(1, 7)}  # 辅助输入 Aux In 1-6
        self.usb = {i: blank_row("usb") for i in range(1, 3)}    # USB 播放返回 1-2
        self.fxret = {i: blank_row("fxret") for i in range(1, 9)}  # 效果返回 FX Return 1-8
        self.mtx = {i: blank_row("mtx") for i in range(1, 7)}    # 矩阵输出 Matrix 1-6
        self.main = blank_row("main")
        # 话放 (模拟增益): 与通道一一对应, 但地址是 /headamp/000..031 —— 独立一组,
        # 因为一台台子的 XLR 口数、AES50 接口箱映射跟"通道号"不是同一个概念。
        self.headamp = {i: blank_row("headamp") for i in range(1, 33)}
        # 发送 (通道 → Bus): 二维目标, 键 = params.send_pack(ch, bus)。
        # ⚠️ 故意**不进** snapshot_state —— 512 行 × 3 字段会把 /api/state 撑爆,
        #    那笔 4G 流量账刚结清。界面按需取 /api/sends?ch=N。
        # 键 = send_pack(源, 目标, 组)。五组共用这一张表, 用基址分段区分
        # (ch 1..512 原样保留, auxin/fxret/bus/main 各自从 1000/2000/3000/4000 起)。
        self.send = {}
        for _g, _src, _nb, _base in SEND_GROUPS:
            for _s in range(1, _src + 1):
                for _b in range(1, _nb + 1):
                    self.send[send_pack(_s, _b, _g)] = blank_row("send")
        self.scene = 1
        # FX 机架 1-8: 混响器. par 存**原生单位**参数值 (时间=秒 / 预延迟=毫秒 / 阻尼=0..1),
        # 参数索引随算法变化, 映射表见 X32_FX_ALGOS / M32_FX_ALGOS (默认值需真机标定)
        self.fx = {i: {"type": "", "name": "", "on": 1, "mix": 0.25, "par": {}}
                   for i in range(1, FX_COUNT + 1)}
        for i, algo in enumerate(("HALL", "PLAT", "ROOM", "CHAM")):
            if i + 1 <= FX_COUNT:
                self.fx[i + 1]["type"] = algo
                self.fx[i + 1]["par"] = dict(REVERB_DEFAULTS[algo])
        self.fx[1]["name"] = "主厅堂"
        self.fx[2]["name"] = "人声板"
        # DCA 成员表: {dca_idx: [ch_idx, ...]}; 手动推 DCA 时成员推子按 dB 差量级联
        # (与真台一致: /ch/XX/mix/dca 位掩码设置归属, 默认每 8 路一组)
        self.dca_members = {i: [] for i in range(1, 9)}
        for i in range(1, 33):
            self.dca_members[(i - 1) // 8 + 1].append(i)
        # 通道/输出名称: {(group, idx): str}, 卡片·推子行·控制键统一显示
        self.names = dict(DEFAULT_NAMES)

    def fader_to_db(self, f: float) -> float:
        # 曲线定义搬到 params.level_db: 协议 4 段伪对数 (0.75→0dB, 0.5→-10,
        # 0.25→-30, 0.0625→-60)。这里只做入口转发, 保证"界面 / 卡片 rel_db /
        # DCA 级联 / 电平模拟"四处的 dB 全部同源。
        return level_db(f)


def db_to_fader(db: float) -> float:
    """fader_to_db 的逆运算:-90..+10 dB → 0..1 推子行程 (同一 4 段曲线)。"""
    return level_from_db(db)

STATE = MixerState()
METER_SUBSCRIBERS = {}      # {(ip, port): 最后活跃时间}; /meters /subscribe /xremote 续期, 30 秒超时清理
METER_LOCK = threading.Lock()
START_TIME = time.time()


def _row_of(group, idx):
    """分组 → 行字典 (表驱动读写的公共出口)。

    main 只有一路且编号固定 0，"行"就是 STATE.main 本身 (它没有按路分包)。
    越界编号抛 KeyError —— 与旧行为一致，target_exists 正是靠它判断
    "本地台面没有这个目标"。
    """
    if group == "main":
        return STATE.main
    store = getattr(STATE, group, None)
    if store is None:
        raise KeyError(group)
    return store[idx]


def _table_pick(table, key):
    """表查询, 支持键里带 * 的通配 (订阅与桥接会发 /bus/*/dyn/* 这类模式)。

    直接命中优先 —— 绝大多数查询是精确地址, 不该为通配付代价; 只有带 * 时才扫表。
    """
    hit = table.get(key)
    if hit is not None:
        return hit
    if "*" not in key:
        return ()
    out = []
    for k, v in table.items():
        if len(k) != len(key):
            continue
        if all(kk == key[i] or key[i] == "*" or kk == "*" for i, kk in enumerate(k)):
            out.extend(v)
    return out


def _expand_spec(sp, segs):
    """一个 spec 在通配模式下展开成 [(kind, idx), ...]。

    地址模板的三种形态在这里统一处理:
      · 无占位符 (/main/st/mix/fader)      → 只有一路, idx=0
      · 一位占位符 (/bus/%02d/mix/pan)     → 该组每一路都试一次
      · 话放 (/headamp/%03d/gain)          → 三位补零, 且 000 = ch01
    """
    out = []
    if "%" not in sp.osc:
        if segs[1] == sp.osc.strip("/").split("/")[1]:
            out.append((sp.kind, 0))
        return out
    n = GROUP_SIZE.get(sp.group, 0)
    if sp.kind == "headamp_gain":
        for i in range(1, n + 1):
            if segs[1] in ("*", "%03d" % (i - 1)):
                out.append((sp.kind, i))
        return out
    for i in range(1, n + 1):
        if segs[1] in ("*", "%02d" % i):
            out.append((sp.kind, i))
    return out


def match_address(pattern: str):
    """按 X32 通配符匹配, 返回 (kind, index) 列表。

    地址索引**不再按组分分支**, 而是从 params 登记表反推的三张表:
      ADDR4       四段地址 (/bus/01/dyn/thr, /bus/01/mix/pan, /ch/01/preamp/trim)
      ADDR5_BAND  五段带段号 (/bus/01/eq/3/g) —— 段号写死在 spec 里, 通配只作用于路号
      ADDR5_DEEP  五段定值 (/bus/01/dyn/filter/f, /ch/01/gate/filter/on)
    发送 (二维) 与 FX 机架仍然是独立分支: 前者的目标数是"每组的 Bus 数"而不是路数,
    后者的参数号随算法变化, 都没有静态地址可索引。
    新增一组通道 / 一个参数 = 只改 params.py, 这里不用动。
    """
    segs = [x for x in pattern.strip("/").split("/") if x]
    results = []
    if not segs:
        return results
    g0 = segs[0]

    with STATE.lock:
        # ---- FX 机架: /fx/<槽>/type | on | mix | par/NN | config/name ----
        if g0 == "fx" and len(segs) >= 2 and segs[1].isdigit():
            slot = int(segs[1])
            if 1 <= slot <= FX_COUNT:
                if len(segs) == 3:
                    kind = {"type": "fx_type", "on": "fx_on",
                            "mix": "fx_mix"}.get(segs[2])
                    if kind:
                        results.append((kind, slot))
                elif len(segs) == 4 and segs[2] == "par" and segs[3].isdigit():
                    p = int(segs[3])
                    if 1 <= p <= 64:
                        results.append((fx_par_kind(p), slot))
                elif len(segs) == 4 and segs[2] == "config" and segs[3] == "name":
                    results.append(("fx_name", slot))
            return results

        # ---- 发送: /<组>/<源>/mix/<目标>/{level|on|type} ----
        g_osc = "fxrtn" if g0 == "fxret" else g0
        if len(segs) == 5 and segs[2] == "mix" and g_osc in SEND_BY_SEG \
                and segs[4] in SEND_BY_SEG[g_osc]:
            sp = SEND_BY_SEG[g_osc][segs[4]]
            # 内部组名与地址前缀不同 (fxret ↔ fxrtn), 表都按内部名索引
            g_int = "fxret" if g_osc == "fxrtn" else g_osc
            src_tpl = sp.osc.strip("/").split("/")[1]
            # 取点只存在于奇数 Bus: 通配时展开奇数, 但允许用**偶数**地址查
            # (真台上 Bus02 与 Bus01 是同一个取点, 用户按 02 查是合理的)。
            odd_only = sp.kind.endswith("_tap")
            step = 2 if odd_only else 1
            nb = SEND_BUSES[g_int]
            for src in range(1, SEND_SRC_MAX[g_int] + 1):
                if src_tpl == "%02d":
                    if not (segs[1] == "*" or segs[1] == "%02d" % src):
                        continue
                elif segs[1] != src_tpl:      # /main/st/mix/... 的 "st"
                    continue
                for bus in range(1, nb + 1, step):
                    hit = segs[3] in ("*", "%02d" % bus)
                    if not hit and odd_only and bus + 1 <= nb:
                        hit = segs[3] == "%02d" % (bus + 1)
                    if hit:
                        results.append((sp.kind, send_pack(src, bus, g_int)))
            return results

        # ---- 三段地址: /dca/01/fader、/headamp/000/gain ----
        if len(segs) == 3:
            for sp in _table_pick(ADDR3, (g_osc, segs[2])):
                results.extend(_expand_spec(sp, segs))
        # ---- 四段地址 ----
        elif len(segs) == 4:
            for sp in _table_pick(ADDR4, (g_osc, segs[2], segs[3])):
                results.extend(_expand_spec(sp, segs))
        # ---- 五段: EQ 段号 ----
        elif len(segs) == 5:
            for sp in _table_pick(ADDR5_BAND, (g_osc, segs[2], segs[4])):
                band = sp.osc.strip("/").split("/")[3]
                if segs[3] in ("*", band):
                    results.extend(_expand_spec(sp, segs))
            for sp in _table_pick(ADDR5_DEEP, (g_osc, segs[2], segs[3], segs[4])):
                results.extend(_expand_spec(sp, segs))
        if results:
            return results

        # ---- 通道的 DCA 归属位掩码 (不是存储值, 是成员表的投影) ----
        if len(segs) == 4 and g0 == "ch" and segs[2] == "mix" and segs[3] == "dca":
            for i in sorted(STATE.ch):
                if segs[1] in ("*", "%02d" % i):
                    results.append(("ch_dca", i))
    return results


def _send_norm(kind, idx):
    """取点按成对 Bus 共享 → 读写都归一到奇数 Bus (与真台同一份真相)。"""
    if kind.endswith("_tap"):
        g, src, bus = send_unpack(idx)
        if bus % 2 == 0:
            return send_pack(src, bus - 1, g)
    return idx


def get_value(kind, idx):
    idx = _send_norm(kind, idx)
    with STATE.lock:
        # 表驱动: 推子/静音/12 个通道参数全部走登记表 (params.PARAM_SPECS)
        sp = PARAM_SPECS.get(kind)
        if sp is not None:
            return _row_of(sp.group, idx).get(sp.field)
        if kind == "ch_dca":    # 通道归属的 DCA 位掩码
            return sum(1 << (d - 1) for d in range(1, 9)
                       if idx in STATE.dca_members.get(d, []))
        if 1 <= idx <= FX_COUNT:
            fx = STATE.fx[idx]
            if kind == "fx_type": return fx["type"]
            if kind == "fx_name": return fx["name"]
            if kind == "fx_on":   return int(fx["on"])
            if kind == "fx_mix":  return float(fx["mix"])
            p = fx_par_num(kind)
            if p is not None:     return float(fx["par"].get(p, 0.0))
    return None


def target_exists(kind, idx):
    """本地台面是否存在这个目标。

    换控台后规模可能大于本地（例如 Wing 48 路 vs 本地 32 路），
    目标超出范围时要**明确跳过并记日志**，不能让 KeyError 冒出去。
    """
    try:
        return get_value(kind, idx) is not None
    except (KeyError, IndexError, TypeError):
        return False


def set_value(kind, idx, value, source="manual"):
    idx = _send_norm(kind, idx)
    # 延迟导入: fx→state 是顶层依赖, state→fx 只在本函数用 —— 放这里打破环
    # (合成单文件形态下该行被剥离, 同一命名空间直接解析)。
    # source="manual" (网页/控制键/外部 OSC 默认) 会触发冲突检测;
    # source="action"/"dca"/"fade" 是卡片/回归/DCA 级联/渐变插值自己的写入, 不检测
    if source == "manual":
        _check_manual_takeover(kind, idx)
    cascade_from = None
    if kind == "dca_fader" and source == "manual":
        cascade_from = get_value(kind, idx)   # DCA 手动移动 → 成员级联基准
    with STATE.lock:
        sp = PARAM_SPECS.get(kind)
        if sp is not None:
            # 表驱动: 钳制 + 档位量化 + 落库 (params.param_coerce)。
            # 推子/静音/12 个通道参数共用这一条, 与旧的分支写法逐字等价
            # (fader=_clamp01 / on=_truthy, 通道参数多一层量程与档位)。
            # 传 profile 是为了**按控台吸附档位**: WING 的 ch 压缩比没有 7.0
            # 这一档, 提前吸附, 界面就不会先显示 7.0 再自己跳成 5.0。
            _row_of(sp.group, idx)[sp.field] = param_coerce(kind, value, profile())
        elif kind == "ch_dca":   # 位掩码: 通道归属哪些 DCA (bit0=DCA1 ...)
            mask = int(value) & 0xFF
            for d in range(1, 9):
                members = STATE.dca_members[d]
                has = idx in members
                want = bool(mask & (1 << (d - 1)))
                if want and not has:
                    members.append(idx)
                    members.sort()
                elif has and not want:
                    members.remove(idx)
        elif 1 <= idx <= FX_COUNT:
            fx = STATE.fx[idx]
            if kind == "fx_type":
                fx["type"] = str(value).upper()[:8]
                # 换算法要重新铺一套该算法的默认参数, 否则参数索引会串味。
                # 只有标定过出厂值的算法才播种 (混响十种 + 图示均衡四种),
                # 其余保持未设置 —— 不猜数值, 见 consts.FX_SWITCH_DEFAULTS。
                if fx["type"] in fx_algos():
                    fx["par"] = dict(FX_SWITCH_DEFAULTS.get(fx["type"], {}))
                else:
                    fx["par"] = {}
            elif kind == "fx_name": fx["name"] = str(value)[:12]
            elif kind == "fx_on":   fx["on"] = _truthy(value)
            elif kind == "fx_mix":  fx["mix"] = _clamp01(value)
            else:
                p = fx_par_num(kind)
                if p is not None:
                    fx["par"][p] = fx_par_clamp(idx, p, value)
        else:
            # 走到这里说明 kind 完全不认识 —— 必须留痕。
            # 曾经的写法是"什么都不做"，于是一个拼错的 kind 表现成
            # "接口返回 ok 但台子没反应"，最难查的那类。
            log("SET 未识别的写入: kind=%r idx=%r value=%r (已忽略)"
                % (kind, idx, value))
    if source == "manual":
        _push_manual_now(kind, idx)
    # 写出口 (WriteSink): 落库后的值交给各 sink。sink 只能拿到 after 值,
    # 物理上不可能再转发原始入参 (B0-2 的根因); 桥接/推送/冲突检测互不干扰。
    for _sink in SINKS:
        _sink.on_write(kind, idx, get_value(kind, idx), source)
    if cascade_from is not None:
        _dca_cascade(idx, cascade_from, _finite(value, 0.0))
    # 混响时间改动 → 按同步模式广播到联动组。
    # 三个入口(软件改 / Tap 换算 / 真台回读)最终都汇聚到 set_value, 所以只在这里挂一次;
    # 广播出去的写入用 source="action", 不会再触发本分支 —— 天然断开回环。
    p = fx_par_num(kind)
    if p is not None and source in ("manual", "sync"):
        algo = fx_algo(idx)
        # ⚠️ "time" in algo: 61 种算法里只有 10 种混响有 time 别名。
        #    旧库只有 5 种混响, 这个判断看着多余; 全量标定后往 GEQ/P1A 之类
        #    写参数会在这里 KeyError —— 异常被上层吞掉, 表现成"接口返 ok
        #    但台子没反应", 只能靠回归组抓。
        if algo and "time" in algo and p == algo["time"]:
            _fx_time_fanout(idx, get_value(kind, idx), source)


def _push_manual_now(kind, idx):
    """手动写入立即广播给订阅者 (真台行为: 面板动推子马上推送, 让桥接端及时察觉干预)。"""
    sock = MAIN_SOCK[0]
    if sock is None:
        return
    key = (kind, idx)
    v = get_value(kind, idx)
    if v is None:
        return
    # 节流: 只有"值没变且来得太快"才合并; 值一变就必须推 —— 否则桥接场景下真台的
    # 面板干预会被渐变转发的时间戳挤掉 (见 NOTIFY_LAST 注释)。
    now = time.time()
    with NOTIFY_LOCK:
        last = NOTIFY_LAST.get(key)
        if last is not None and last[0] == v and now - last[1] < 0.08:
            return
        NOTIFY_LAST[key] = [v, now]
    PUSH_CACHE[key] = v           # 立即推送后, 周期推送不再重发
    with METER_LOCK:
        subs = list(METER_SUBSCRIBERS)
    if not subs:
        return
    try:
        reply = value_reply(kind, idx)
        if reply is None:      # 当前控台没有该目标的地址
            return
        pkt = encode_message(reply)
    except Exception:
        return
    for s in subs:
        try:
            sock.sendto(pkt, s)
        except OSError:
            pass


def _dca_cascade(dca_idx, old_fader, new_fader):
    """手动推 DCA: 成员通道推子按 dB 差量级联 (真台手感)。
    卡片/回归写 DCA 走 source="action", 不级联。"""
    try:
        delta = STATE.fader_to_db(min(max(new_fader, 0.0), 1.0)) - \
            STATE.fader_to_db(min(max(old_fader, 0.0), 1.0))
    except Exception:
        return
    if abs(delta) < 0.01:
        return
    with STATE.lock:
        members = list(STATE.dca_members.get(dca_idx, []))
    for c in members:
        cur = get_value("ch_fader", c)
        if cur is None:
            continue
        tgt = db_to_fader(min(max(STATE.fader_to_db(cur) + delta, -90.0), 10.0))
        set_value("ch_fader", c, tgt, source="dca")


def get_name(group, idx):
    with STATE.lock:
        return STATE.names.get((group, idx), "")


def set_name(group, idx, name):
    name = str(name).strip()[:12]
    # 延迟导入: state→persist 与 persist→state/bridge 会成环, 只在函数体内打破
    # (合成单文件形态下该行被剥离, 同一命名空间直接解析)。
    with STATE.lock:
        if name:
            STATE.names[(group, idx)] = name
        else:
            STATE.names.pop((group, idx), None)
    log("NAME %s %s = %s" % (group, idx, name or "(已清除)"))
    save_user_config()          # 网页或 OSC 改名都持久化, 重启不丢
    return name


def target_label(group, idx):
    """日志用目标描述: 有名字显示 名字(编号), 没有显示 组 编号。"""
    n = get_name(group, idx)
    if n:
        return "%s(%s%02d)" % (n, KIND_LABEL.get(group, group), idx)
    return "%s %02d" % (KIND_LABEL.get(group, group), idx)


def value_reply(kind, idx):
    """(kind, idx) → 状态回包的 OSC 消息。

    返回 None 表示**当前控台不支持该目标**（调用方须过滤掉，不能塞进 bundle）。
    """
    idx = _send_norm(kind, idx)
    v = get_value(kind, idx)
    a = addr_for_write(kind, idx)
    if a is None or v is None:
        return None
    # 表驱动定参数类型: float 参数 (推子/增益/延时/频率/门限) 发浮点,
    # 开关发 0/1, 枚举发线上的那个值 —— 由 params.param_wire 统一换算。
    # ⚠️ dyn/ratio 这类 **index 型枚举** 本地存 4.0(4:1)、线上要发 6,
    #    曾经这里直接 int(v) → 4, 真台解析成 5:1 (第 5 档), 静默改值。
    sp = PARAM_SPECS.get(kind)
    p = profile()
    if sp is not None:
        return OscMsg(a, [param_wire(sp, v, p)])
    if kind == "ch_dca":
        return OscMsg(a, [int(v)])
    if kind == "fx_type":
        # WING 的算法枚举名与 X32 不同（`/fx/N/mdl`）。回包必须给**线格式**，
        # 否则客户端按 X32 名去比对，会把"已经装上"看成"没换上"。
        name = p.fx_wire_name(v)
        return OscMsg(a, [str(name)]) if name is not None else None
    if kind == "fx_name":
        return OscMsg(a, [str(v)])
    if kind == "fx_mix":                        # FX 机架混合比: WING 是 0..100 整数
        if (p.fx_mix_scale or 1) != 1:
            return OscMsg(a, [int(round(float(v) * p.fx_mix_scale))])
        return OscMsg(a, [float(v)])
    if fx_par_num(kind) is not None:             # FX 参数: 浮点 (WING 是命名参数，P2)
        return OscMsg(a, [float(v)])
    return OscMsg(a, [int(v)])


PUSH_CACHE = {}      # (kind, idx) -> 上次推送的值; 状态变化推给订阅者 (真台 /xremote 行为)
PUSH_KINDS = (list(FADER_ADDR.keys()) + list(ON_ADDR.keys()))

# 每个订阅者"已经推过哪些键"。
# 为什么不能只用 PUSH_CACHE（全局）: 它是"上次推给**任何**订阅者"的值。
# 第二个客户端连上来时缓存已经填满、值也没变 → 它一个包都收不到，界面全 0；
# 客户端 A 断开期间发生的变化，A 重连后同样补不回来。真台 /xremote 本来也
# 只推变化（不做初始全量），所以这不算协议不一致，但**作为模拟器**，
# 让新订阅者能自己对齐状态是刚需 —— 见 XREMOTE_SNAPSHOT 与 /subscribe。
SUB_SEEN = {}        # addr -> set((kind, idx))
XREMOTE_SNAPSHOT = [False]   # /xremote 首帧是否补一次全量（非真台行为，默认关）

# /subscribe 的按地址周期订阅: addr -> {pattern: {rate, due, expire}}
# 协议语义（Unofficial v4.06 / 官方 /subscribe）: 客户端说"我关心这个地址、
# 按这个倍数回报"，服务端在 10 秒内周期性回值；rate 的单位是 50ms 的倍数。
PATTERN_SUBS = {}
PATTERN_LOCK = threading.Lock()
SUB_TIMEOUT = 10.0


def subscribe_client(addr):
    """登记一个订阅者（/xremote、/subscribe、/meters 都走这里）。

    返回 True 表示这是**首次**出现的来源 —— 调用方可以据此决定要不要补快照。
    ⚠️ 以前三处各自 `METER_SUBSCRIBERS[addr] = time.time()`，SUB_SEEN 就没人建，
       新订阅者第一次遍历时拿不到 seen 集合（表现为"有时补、有时不补"）。
    """
    with METER_LOCK:
        first = addr not in METER_SUBSCRIBERS
        METER_SUBSCRIBERS[addr] = time.time()
        if first:
            SUB_SEEN[addr] = set()
        return first


def unsubscribe_client(addr):
    with METER_LOCK:
        METER_SUBSCRIBERS.pop(addr, None)
        SUB_SEEN.pop(addr, None)
    with PATTERN_LOCK:
        PATTERN_SUBS.pop(addr, None)


def subscribe_pattern(addr, pattern, rate=1):
    """按地址周期订阅（协议 /subscribe）。rate 单位 = 50ms 的倍数。"""
    try:
        rate = max(1, min(int(rate), 200))
    except (TypeError, ValueError):
        rate = 1
    now = time.time()
    with PATTERN_LOCK:
        d = PATTERN_SUBS.setdefault(addr, {})
        # due=now → 订阅后的第一轮立刻回一帧当前值，这正是"新客户端拿到初始值"
        # 的标准做法（真台也是这样：/subscribe 之后马上就能收到当前值）。
        d[pattern] = {"rate": rate * 0.05, "due": now, "expire": now + SUB_TIMEOUT}
    return rate


def unsubscribe_pattern(addr, pattern=None):
    with PATTERN_LOCK:
        if pattern is None:
            PATTERN_SUBS.pop(addr, None)
        else:
            PATTERN_SUBS.get(addr, {}).pop(pattern, None)


def _service_pattern_subs(sock):
    """按 due 时间把订阅地址的当前值回给订阅者（10 秒无续期自动过期）。"""
    now = time.time()
    with PATTERN_LOCK:
        due = []
        for a, d in list(PATTERN_SUBS.items()):
            for p, st in list(d.items()):
                if now > st["expire"]:
                    d.pop(p, None)
                    continue
                if now >= st["due"]:
                    st["due"] = now + st["rate"]
                    due.append((a, p))
            if not d:
                PATTERN_SUBS.pop(a, None)
    for a, p in due:
        matches = match_address(p)
        replies = [r for r in (value_reply(k, i) for k, i in matches) if r is not None]
        if not replies:
            continue
        try:
            pkt = encode_message(replies[0]) if len(replies) == 1 \
                else encode_bundle(replies)
            sock.sendto(pkt, a)
        except OSError:
            pass


def _push_state_diffs(sock, subscribers):
    """每次 tick 对比缓存, 把发生变化的推子/静音推给订阅者 (模拟真台变更推送)。

    ⚠️ 两个易错点（都踩过）:
      1. `PUSH_CACHE` 必须在**所有**订阅者都发完之后再更新。写在循环里的话，
         第一个订阅者发完就把缓存改了，后面的订阅者算出来"没变化"→ 漏发。
      2. 新订阅者（SUB_SEEN 里没有这个键）在 XREMOTE_SNAPSHOT 开启时要补一帧，
         否则它只能等下一次真实变化 —— 界面在很长一段时间里是空的。
    """
    sent = 0
    counts = profile().counts
    snapshot = XREMOTE_SNAPSHOT[0]
    for kind in PUSH_KINDS:
        ids = [0] if kind.startswith("main_") else \
            range(1, counts.get(kind_group(kind), 0) + 1)
        for i in ids:
            v = get_value(kind, i)
            if v is None:
                continue
            key = (kind, i)
            old = PUSH_CACHE.get(key)
            changed = old is None or abs(old - v) >= 1e-4
            pkt = None
            for s in subscribers:
                seen = SUB_SEEN.get(s)
                if seen is None:
                    seen = SUB_SEEN[s] = set()
                if not changed and not (snapshot and key not in seen):
                    continue
                if pkt is None:
                    reply = value_reply(kind, i)
                    if reply is None:      # 当前控台没有这个目标的地址 → 不推送
                        break
                    pkt = encode_message(reply)
                try:
                    sock.sendto(pkt, s)
                    sent += 1
                except OSError:
                    pass
                seen.add(key)
            if changed:
                PUSH_CACHE[key] = v
    return sent


def meter_streamer(sock):
    """50ms 基准循环: 电平与变更推送仍按 150ms (3 tick), /subscribe 按各自 rate。

    为什么拆成 50ms 基准: /subscribe 的 rate 单位就是 50ms 的倍数, 用 150ms 的
    循环去服务它, rate=1 只能做到 6.7 Hz, 与协议的 20 Hz 差三倍。
    """
    tick = 0
    while True:
        time.sleep(0.05)
        tick += 1
        now = time.time()
        with METER_LOCK:
            stale = [s for s, ts in METER_SUBSCRIBERS.items() if now - ts > 30.0]
            for s in stale:
                METER_SUBSCRIBERS.pop(s, None)
                SUB_SEEN.pop(s, None)
            if stale:
                log("METER 清理失活订阅者: %d 个" % len(stale))
            subscribers = list(METER_SUBSCRIBERS)
        for s in stale:
            with PATTERN_LOCK:
                PATTERN_SUBS.pop(s, None)
        try:
            _service_pattern_subs(sock)
        except Exception as e:
            log("按地址订阅推送出错: %r" % e)
        if tick % 3:            # 以下保持 150ms 一轮
            continue
        if not subscribers:
            continue
        floats = compute_levels()
        blob = struct.pack(">i", len(floats))
        for v in floats:
            blob += struct.pack(">f", v)
        pkt = encode_message(OscMsg("/meters/1", [blob]))
        for s in subscribers:
            try:
                sock.sendto(pkt, s)
            except OSError:
                pass
        try:
            _push_state_diffs(sock, subscribers)
        except Exception as e:
            log("推送台面变更出错: %r" % e)


def source_level_db(i, t=None):
    """**话筒信号本身**的电平 (dBFS, 增益与推子之前)。

    为什么要把"信号"和"推子位置"拆开: 自动增益/自动推子靠电平做判断,
    若电平表 = 推子位置 × 信号, 自动推子往下拉 → 表跟着掉 → 再往下拉,
    变成自激塌陷。有了独立的信号源, 电平表 = 信号 + 增益 + 推子, 才是
    真实调音台的叠加关系, 控制器才有稳定的被控对象。

    波形是"音乐化"的: 0.7 Hz 慢起伏 + 3.1 Hz 快起伏 + 0.15 Hz 段落起伏,
    每路相位错开, 幅度约 ±8 dB —— 足够让自动推子有活干, 又不会一帧跳变。
    """
    if t is None:
        t = time.time() - START_TIME
    base = -20.0 + 4.0 * math.sin(t * 0.7 + i * 1.3) + 1.5 * math.sin(t * 3.1 + i * 2.1)
    phrase = 3.0 * math.sin(t * 0.15 + i * 0.37)
    return base + phrase


def compute_levels():
    """返回当前电平 dB 列表:32 输入通道 + 16 输出 Bus (UDP 推送与 Web 界面共用)。

    通道电平 = 信号源 + 数字增益 + 推子 (真台的叠加关系), 静音为 -∞。
    Bus 仍沿用推子位置(虚拟混音无法逐路求和, 这里只求"看着像")。
    """
    t = time.time() - START_TIME
    floats = []
    with STATE.lock:
        for group, count in ((STATE.ch, 32), (STATE.bus, 16)):
            for i in range(1, count + 1):
                ch = group[i]
                if not ch["on"]:
                    floats.append(-32768.0)  # -∞
                    continue
                if group is STATE.ch:
                    db = (source_level_db(i, t) + float(ch.get("trim") or 0.0)
                          + STATE.fader_to_db(ch["fader"]))
                else:
                    # Bus: 沿用推子位置 + 轻微起伏 (无逐路求和, 不求精确)
                    db = STATE.fader_to_db(ch["fader"]) + 1.5 * math.sin(t * 0.9 + i)
                # 0.1 dB 足够画表 (屏幕上一个像素约 0.5 dB)。保留全精度会让
                # 每轮多传 350 B —— 4 Hz 下就是 5 MB/h, 换来的是看不见的精度。
                floats.append(round(max(-60.0, min(0.0, db)), 1))
    return floats
NOTIFY_LAST = {}     # 手动变更推送节流: (kind, idx) -> [上次推送的值, 时间]
                     # ⚠️ 必须**连同值一起**判断"是否重复": 只看时间会把真台的面板干预挤掉。
                     # 桥接时本地渐变每 tick 都转发一次, 真台把转发也当手动变更 → 时间戳被
                     # 持续刷新; 等真正的干预到达, "距上次 < 80ms" 恒成立, 立即推送被丢,
                     # 只剩 150ms 周期推送, 而那时干预值已被下一 tick 的渐变值覆盖,
                     # 推出去的值 equals 渐变值 → 被回声抑制吸收 → 冲突永远检测不到。

# ---- 冲突策略: 手动干预只停该通道, 其余动作继续 ----
# 卡片执行期间, 正在被渐变驱动的 (kind, idx) 登记在 FADE_ZONE;
# 此时有手动写入 (网页推子 / 控制键 / 外部 OSC) 命中同一通道,
# 只把该通道标记为手动接管 (停在手动位置), 卡片其余通道与后续动作照常执行, 并推送网页通知。
FADE_LOCK = threading.Lock()
FADE_ZONE = {}        # (kind, idx) -> 卡片名 (正在被卡片渐变驱动)
INTERRUPTS = set()    # 本轮渐变中被手动接管的 (kind, idx)


def _register_fade(targets, card_name):
    """渐变开始: 登记驱动通道, 并清掉这些通道上一轮的接管标记 (后续动作重新获得控制权)。"""
    with FADE_LOCK:
        for k, i, _a, _b in targets:
            INTERRUPTS.discard((k, i))
            FADE_ZONE[(k, i)] = card_name


def _unregister_fade(targets):
    with FADE_LOCK:
        for k, i, _a, _b in targets:
            FADE_ZONE.pop((k, i), None)


def _check_manual_takeover(kind, idx):
    """手动写入前检查: 该通道正被卡片渐变驱动 → 标记接管 + 记通知事件。"""
    key = (kind, idx)
    with FADE_LOCK:
        zone = FADE_ZONE.get(key)
        if not zone or key in INTERRUPTS:
            return
        INTERRUPTS.add(key)
    text = "⚠️ %s 手动接管 — 卡片「%s」停止驱动该通道, 其余动作继续" % (
        target_label(kind_group(kind), idx), zone)
    EVT_SEQ[0] += 1
    EVENTS.append({"id": EVT_SEQ[0], "time": time.strftime("%H:%M:%S"), "text": text})
    log("CONFLICT %s" % text)


def _interrupted(kind, idx):
    return (kind, idx) in INTERRUPTS


NOTIFY_LOCK = threading.Lock()   # 只护 NOTIFY_LAST (原来借用 BRIDGE_LOCK,
                                #  那会让 state 依赖 bridge —— 模块化要切断)


class WriteSink:
    """写出口协议: set_value 落库后, 把**落库后的值**交给注册的 sink。

    为什么需要: 曾经的写法是 set_value 尾部直接调 _bridge_forward ——
    state 因此 import bridge, 层级关系倒挂; 而且转发的是调用入参,
    本地钳到 1.0 真台却收到 1.7 (B0-2)。SINKS 注册制把这两件事一起解决:
    state 不知道谁在听, sink 也拿不到原始值。
    """

    def on_write(self, kind, idx, value, source):
        raise NotImplementedError


SINKS = []        # 由 app.py 注册 (桥接 sink); 状态层不 import 任何业务模块


# ==================================================================
# ==== x32sim/bridge.py
# ==================================================================
# -*- coding: utf-8 -*-
"""x32sim/bridge — 桥接真台: 转发合并 / 回读 / 回声抑制"""

import math
import os
import socket
import threading
import time



def _wire_arg(kind, value, p=None):
    """(kind, 本地值) → 线上值。返回 None = 当前控台不支持 / 值非法（调用方跳过）。

    抽成纯函数是为了可单测：这里每一条换算错了都是"写成功但声音错"，
    而它在真实链路里只在 20ms 合并器刷新时才跑到，靠抓包很难覆盖全。
    """
    if p is None:
        p = profile()
    sp = PARAM_SPECS.get(kind)
    if kind == "ch_dca":
        return int(value) & 0xFF
    if kind == "fx_type":
        # 内部算法 key → 线上枚举名。WING 是 `/fx/N/mdl` 且枚举名与 X32 不同；
        # 映射不到 = 这台控台没有这个算法 → 拒发并把名字说出来，
        # 否则槽位在界面上"装着"、真台其实没换。
        name = p.fx_wire_name(value)
        if name is None:
            log("BRIDGE 跳过 fx_type: 算法「%s」不在「%s」效果库中" % (value, p.label))
            return None
        return str(name)[:12]
    if kind == "fx_name":
        return str(value)[:12]
    if sp is not None:
        # 表驱动定线上类型 (与 state.value_reply 同一套规则, 都走 param_wire):
        #   float → 浮点 (推子/增益/延时/频率/门限); int → 整数 (低切斜率);
        #   bool  → 0/1 (静音/延时/低切/插入/门开关)
        #   index 型枚举 (dyn/ratio) → 0..11 的**索引**, 不是比值
        #   WING: 组级推子发 dB、组级静音发 1=muted (见 param_wire 的平台分支)
        # ⚠️ 曾经这里是 `endswith("_fader") → float, 其余 _truthy` —— 新增的
        #    通道参数全是非 _fader 结尾, 会被 _truthy 压成 0/1 发给真台
        #    (trim 3.5 dB 变成 1), 于是"桥接转发"这一层整个失真。
        arg = param_wire(sp, value, p)
        # 第二道闸: 万一将来哪条路径漏了 _finite, 宁可拒发也不把 NaN 发给真台
        if isinstance(arg, float) and not math.isfinite(arg):
            log("BRIDGE 拒发非有限值: %s = %r" % (kind, value))
            return None
        return arg
    if kind == "fx_mix" or fx_par_num(kind) is not None:
        arg = float(value)
        if kind == "fx_mix" and (p.fx_mix_scale or 1) != 1:
            # WING 的干湿比是 0..100 整数，不是 0..1
            arg = int(round(arg * p.fx_mix_scale))
        if not math.isfinite(arg):
            log("BRIDGE 拒发非有限值: %s = %r" % (kind, value))
            return None
        return arg
    return _truthy(value)


def _bridge_forward(kind, idx, value, source="manual", force=False):
    """桥接模式下把写入转成 OSC 发往真台, 并登记回声抑制记录。

    入参 value 必须是**已经过本地钳制/消毒的值**（调用方传 get_value 的结果）——
    真台收到什么, 就应该和本地台面看到的一致, 不能再出现"本地 1.0 / 真台 1.7"。
    source 决定合并限速档位 (手动灵敏 / 渐变放宽), 见 BRIDGE_FWD_MIN_GAP。
    force=True 用于"停止时同步冻结值": 绕过限速下一拍必出 (gap=0),
    保证卡片/回归中途停止后真台与本地台面一致, 不停在中间值上。
    """
    try:
        if value is None:
            return          # 本地没有这个目标（换控台后规模不匹配等）
        p = profile()
        arg = _wire_arg(kind, value, p)
        if arg is None:
            return
        addr = addr_for_write(kind, idx)      # ⚠️ Main 无 %02d, 必须走统一映射 (见该函数注释)
        if addr is None:
            # 当前控台不支持这个目标 → 明说, 不要静默吞掉 (静默是这类 bug 的老家)
            log("BRIDGE 跳过 %s %s: 当前控台「%s」未提供该地址%s"
                % (kind, idx, p.label, "（驱动待标定）" if not p.ready else ""))
            return
        sock = BRIDGE_SOCK[0]
        if sock is None:
            return
        # 渐变插值遇"已手动接管": 这条值是接管前算出来的, 发出去会把真台拽回
        # 旧位置, 回读回声还会把本地也覆盖回旧值 (用户白接管了)。入口就拦掉。
        # 显式动作 (set/mute/回归...) 不走这支 —— 它们的语义是"其余动作继续"。
        from_fade = (source == "fade")
        if from_fade and (kind, idx) in INTERRUPTS:
            return
        # 进合并队列 (同地址只保留最新值), 由 _bridge_fwd_flusher 按 Bundle 发出;
        # FWD_RECENT 也在实际发出时登记 —— 回声抑制要对得上真台真正收到的值。
        gap = 0.0 if force else BRIDGE_FWD_MIN_GAP.get(source, BRIDGE_FWD_GAP_DEFAULT)
        with BRIDGE_FWD["lock"]:
            BRIDGE_FWD["pending"][(kind, idx)] = (addr, arg, gap, from_fade)
    except Exception as e:
        log("BRIDGE 转发失败 %s: %r" % (kind, e))


def _bridge_force_sync(keys, skip_interrupted=False):
    """把一批 (kind, idx) 的**当前本地值**立即转发给真台 (绕过合并限速)。

    用于渐变被中途停止的场景: 本地冻结在当前值, 而最后一次插值可能还没
    转发 (或被合并器限速挡着) —— 不同步的话真台停在中间值, 与台面不一致。
    keys 是可迭代的 (kind, idx); 内部取快照, 调用方无需加锁。
    skip_interrupted: 跳过已被手动接管的通道 (卡片停止时用 —— 那些通道
    归手动管, 停止同步不该把它们拽回本地值)。
    """
    if BRIDGE["addr"] is None:
        return
    n = 0
    for kind, idx in list(keys):
        if skip_interrupted and (kind, idx) in INTERRUPTS:
            continue
        v = get_value(kind, idx)
        if v is None:
            continue
        _bridge_forward(kind, idx, v, source="action", force=True)
        n += 1
    if n:
        log("BRIDGE 停止同步: %d 个目标当前值已强制转发" % n)


def _bridge_fwd_flusher():
    """常驻合并器外壳: 任何异常写日志重启, 不静默死亡 (死亡=转发永远停)。"""
    while True:
        try:
            _bridge_fwd_flush_once()
        except Exception as e:
            log("BRIDGE 合并器异常 (已自动重启): %r" % e)
            time.sleep(0.5)


def _node_path(addr):
    """`/ch/1/fdr` → `/ch.1.fdr`（WING 节点批量写的路径写法：点分隔、无空段）。"""
    return "/" + ".".join([p for p in str(addr).split("/") if p])


def _node_value(v):
    """线上值 → 节点批量写里的文本。整数不带小数点，字符串原样。"""
    if isinstance(v, str):
        return v
    if isinstance(v, bool):
        return "1" if v else "0"
    try:
        f = float(v)
    except (TypeError, ValueError):
        return str(v)
    if f == int(f) and abs(f) < 1e15:
        return "%d" % int(f)
    return ("%.4f" % f).rstrip("0").rstrip(".")


def _send_node_batch(sock, batch, addr):
    """一条 OSC 写多路：`/ ,s "/ch.1.fdr=0,/ch.2.fdr=-10"`（WING 官方语法）。

    为什么默认不用：整包里只要有一条路径不被接受，WING 会整包回 `NODE NOT FOUND`，
    这一批写入就全丢了 —— 逐条发虽然包多，但一条失败不影响其余。所以这是
    **可选项**（环境变量 X32_WING_NODE_WRITE=1 / 配置项），且被拒一次就自动关掉，
    退回逐条发（见 recv 循环里的 /*,s 处理）。
    """
    parts = ["%s=%s" % (_node_path(_a), _node_value(v)) for _a, v, _g, _f in batch]
    payload = ",".join(parts)
    if len(payload) > 900:
        # 保守留余量：UDP 单包 32KB，但节点串越长越容易踩到台子的解析上限
        for _a, v, _g, _f in batch:
            sock.sendto(encode_message(OscMsg(_a, [v])), addr)
        return
    sock.sendto(encode_message(OscMsg("/", [payload])), addr)


def _send_msgs(sock, msgs, addr):
    """按控台能力发包。

    X32 吃 Bundle（一次发一批）；**WING 不吃**——官方文档写明其 OSC 包内容
    永远是单条 Message，Bundle 会被整包丢弃。发错的表现是最难查的一种：
    网页/卡片照常动、日志干净、真台纹丝不动。所以这里按 profile 分路。
    """
    if getattr(profile(), "osc_bundle", True):
        sock.sendto(encode_bundle(msgs), addr)
        return
    for m in msgs:
        sock.sendto(encode_message(m), addr)


def bridge_scene(n):
    """把场景召回转发给真台。未桥接返回 False（调用方只改本地状态）。

    ⚠️ 这条路径以前**不存在**：`actions` 里切场景只写 `STATE.scene`，注释说
    "真台发 /scene/N/load" 但从来没有代码真的发过 —— 症状是桥接模式下点切场景，
    网页的场景号变了、台面纹丝不动，而日志里一个字都没有。现在补上，
    并且地址由 profile 给（WING 是两段式，见 ConsoleProfile.scene_msgs）。

    返回 True = 已发出；False = 未桥接/发送失败（调用方据此决定是否提示）。
    """
    addr = BRIDGE["addr"]
    sock = BRIDGE_SOCK[0]
    if addr is None or sock is None:
        return False
    try:
        msgs = [OscMsg(a, args) for a, args in profile().scene_msgs(n)]
    except (TypeError, ValueError) as e:
        log("BRIDGE 场景号非法: %r (%r)" % (n, e))
        return False
    try:
        # ⚠️ 场景召回**逐条发，不打包 Bundle**：它是 trigger 不是参数批写，
        #    而 WING 里 `$actionidx` 与 `$action` 还必须**严格按序**到达
        #    （先选号再 GO）。Bundle 在 X32 上或许也能工作，但顺序语义更脆，
        #    且这条路径一次只发 1~2 条，省不下什么。
        for m in msgs:
            sock.sendto(encode_message(m), addr)
    except OSError as e:
        log("BRIDGE 场景召回转发失败: %r" % e)
        return False
    return True


def _bridge_fwd_flush_once():
    """一轮合并发送: 把到期的转发条目打包成一个 Bundle 发给真台。"""
    time.sleep(BRIDGE_FWD_TICK)
    sock = BRIDGE_SOCK[0]
    addr = BRIDGE["addr"]
    if sock is None or addr is None:
        with BRIDGE_FWD["lock"]:
            if BRIDGE_FWD["pending"]:
                BRIDGE_FWD["pending"].clear()
        return
    now = time.time()
    batch = []
    with BRIDGE_FWD["lock"]:
        pend = BRIDGE_FWD["pending"]
        overflow = len(pend) > BRIDGE_FWD_MAX_BATCH
        for key in list(pend.keys()):
            _a, _v, gap, from_fade = pend[key]
            if from_fade and key in INTERRUPTS:
                # 接管发生后积压的渐变插值: 过期, 直接丢弃 (真台不能收到它,
                # 否则会把用户刚抢回的手动值拽回旧位置, 回读回声还会覆盖本地)
                pend.pop(key)
                continue
            if overflow or now - BRIDGE_FWD["last"].get(key, 0.0) >= gap:
                batch.append((key, pend.pop(key)))
        for key, _av in batch:
            BRIDGE_FWD["last"][key] = now
    if not batch:
        return
    msgs = [OscMsg(a, [v]) for _k, (a, v, _g, _f) in batch]
    try:
        pairs = [av for _k, av in batch]
        use_nodes = (WING_NODE_WRITE[0] and not getattr(profile(), "osc_bundle", True)
                     and len(pairs) > 1
                     and all(not isinstance(av[1], str) for av in pairs))
        if use_nodes:
            _send_node_batch(sock, pairs, addr)
        else:
            _send_msgs(sock, msgs, addr)
    except OSError as e:
        log("BRIDGE 合并转发失败 (%d 条): %r" % (len(msgs), e))
        return
    with BRIDGE_LOCK:
        t = time.time()
        for key, (_a, v, _g, _f) in batch:
            FWD_RECENT[key] = [v, t]


def _ensure_fwd_flusher():
    """幂等启动合并器线程 (bridge_start 每次都会调, 不能起重复)。"""
    with BRIDGE_FWD["lock"]:
        t = BRIDGE_FWD_THREAD[0]
        if t is not None and t.is_alive():
            return
        t = threading.Thread(target=_bridge_fwd_flusher, daemon=True)
        t.start()
        BRIDGE_FWD_THREAD[0] = t


def _fwd_is_echo(key, value):
    """判断一条回读是不是自己刚转发造成的回声 (值相同 + 2 秒内)。"""
    with BRIDGE_LOCK:
        rec = FWD_RECENT.get(key)
    if not rec:
        return False
    if time.time() - rec[1] >= 2.0:
        return False
    a, b = rec[0], value
    if isinstance(a, str) or isinstance(b, str):
        return str(a) == str(b)
    try:
        fa, fb = float(a), float(b)
    except (TypeError, ValueError):
        return False
    # 时间/预延迟这类原生单位参数跨度大, 绝对容差 0.02 不够用, 补一个 0.5% 相对容差
    return abs(fa - fb) <= max(0.02, abs(fb) * 0.005)


def _bridge_apply_readback(kind, idx, value):
    """真台回读: 回声(自己刚转发过的值)静默吸收; 台面上的手动变化按冲突策略处理。

    ⚠️ value 是**线上值**: dyn/ratio 这类 index 型枚举要换算成本地存的值再落库,
    否则真台第 6 档 (4:1) 会被存成 "6:1"。回声比对仍用线上值 (FWD_RECENT 记的
    也是线上值), 换算只在落库前一步做 —— 顺序别调, 调了回声就认不出来了。
    """
    key = (kind, idx)
    sp = PARAM_SPECS.get(kind)
    if kind == "fx_type" and profile().id == "wing":
        # WING 回读的是 mdl 枚举（大写，如 CHORUS），本库内部 key 是 CRS。
        # 反查不到 = 真台装的是 WING 独有算法（VSS3 / CONCERT / 吉他箱体…），
        # 本库没有对应项 —— 记一条日志保留不动，绝不猜成别的算法。
        _k = algorithm_for_wing_mdl(value)
        if _k is None:
            log("BRIDGE 真台 FX%s 装的是 WING 专有算法「%s」，本效果库无对应项" % (idx, value))
            return
        value = _k
    local = param_from_wire(sp, value, profile()) if sp is not None else value
    if _fwd_is_echo(key, value):
        set_value(kind, idx, local, source="sync")     # 自己写入的回声, 只对齐本地
        return
    # 真台端的变化: 渐变驱动中的通道 → 手动接管冲突; 其余静默同步
    with FADE_LOCK:
        zone = FADE_ZONE.get(key)
        if zone and key not in INTERRUPTS:
            INTERRUPTS.add(key)
            text = "⚠️ 真台上 %s 被手动干预 — 卡片「%s」停止驱动该通道, 其余动作继续" % (
                target_label(kind_group(kind), idx), zone)
            EVT_SEQ[0] += 1
            EVENTS.append({"id": EVT_SEQ[0], "time": time.strftime("%H:%M:%S"), "text": text})
            log("CONFLICT %s" % text)
    set_value(kind, idx, local, source="sync")


def _bridge_full_sync(sock):
    """全量状态回读: 向真台发一轮 GET (Bundle), 用回包填本地台面。

    地址一律经 addr_for_write 取, 当前控台不支持的目标直接跳过 —— 这样换控台后
    不会往真台发一堆它不认识的地址。
    """
    p = profile()
    counts = p.counts
    gets = []

    def _get(kind, idx):
        a = addr_for_write(kind, idx)
        if a:
            gets.append(OscMsg(a, []))

    for tmap in (FADER_ADDR, ON_ADDR):
        for k in tmap:
            grp = kind_group(k)
            ids = [0] if k.startswith("main_") else range(1, counts.get(grp, 0) + 1)
            for i in ids:
                _get(k, i)
    for i in range(1, counts.get("ch", 0) + 1):
        _get("ch_dca", i)
    # FX 机架: 类型 / 开关 / 混合比 / 名称, 以及**当前控台效果库**里用到的全部参数号。
    # ⚠️ 参数号不再写死 1/2/4 —— 不同控台的算法参数索引可能不同, 写死等于去查错位置。
    fx_pns = set()
    for a in p.fx_algos.values():
        for key in ("time", "predelay", "damp"):
            if isinstance(a.get(key), int):
                fx_pns.add(a[key])
    for s in range(1, counts.get("fx", 0) + 1):
        for k in ("fx_type", "fx_on", "fx_mix", "fx_name"):
            _get(k, s)
        for pn in sorted(fx_pns):
            _get(fx_par_kind(pn), s)
    for chunk in (gets[x:x + 64] for x in range(0, len(gets), 64)):
        try:
            _send_msgs(sock, chunk, BRIDGE["addr"])
        except OSError as e:
            log("BRIDGE 全量同步发送失败: %r" % e)
    log("BRIDGE 全量状态同步已请求 (%d 项, 控台 %s)" % (len(gets), p.label))


def fx_pull_from_console():
    """「从真台同步效果」：主动向桥接的真台重发一轮 FX 查询，把真台的效果槽拉回本地。

    与 _bridge_full_sync 的分工：那个是桥接建立时的**全量一次**，这个是**按需**
    只刷 FX —— 现场真正常用的场景是"我在台面上换了个效果器，让控制台跟着走"。

    返回 (ok, 描述 / 错误串)。
    """
    sock = BRIDGE_SOCK[0]
    if sock is None or BRIDGE.get("addr") is None:
        return False, "未桥接真台 —— 浏览器发不了 UDP，没有桥接就没有可同步的对象"
    p = profile()
    if not p.ready or "fx" not in p.caps:
        return False, "控台「%s」的效果槽未标定，无从同步" % p.label
    pns = set()
    for a in p.fx_algos.values():
        for key in ("time", "predelay", "damp"):
            if isinstance(a.get(key), int):
                pns.add(a[key])
    sent, failed = 0, 0
    for s in range(1, int(p.counts.get("fx", 0)) + 1):
        kinds = ["fx_type", "fx_on", "fx_mix", "fx_name"] + \
                [fx_par_kind(pn) for pn in sorted(pns)]
        for kind in kinds:
            addr = p.addr(kind, s)
            if addr is None:
                continue
            try:
                sock.sendto(encode_message(OscMsg(addr, [])), BRIDGE["addr"])
                sent += 1
            except OSError as e:
                failed += 1
                log("FX 同步查询发送失败 %s: %r" % (addr, e))
    log("FX 从真台同步: 已发出 %d 条查询 (%s · %d 个效果槽)%s" % (
        sent, p.label, p.counts.get("fx", 0),
        ("，失败 %d 条" % failed) if failed else ""))
    if not sent:
        return False, "没有可用的效果查询地址（控台「%s」地址表为空）" % p.label
    return True, "已向真台查询 %d 项效果状态，回包会自动同步到混响页" % sent


def bridge_client(ip, port):
    """桥接后台线程外壳: 任何异常写日志退出, 不静默死亡。"""
    try:
        _bridge_client_run(ip, port)
    except Exception as e:
        log("BRIDGE 桥接线程异常退出: %r" % e)
        BRIDGE_SOCK[0] = None
        if BRIDGE.get("addr") == (ip, port):
            BRIDGE["addr"] = None
            BRIDGE["synced"] = False


def _bridge_client_run(ip, port):
    """桥接后台线程: 按控台保活（X32 /xremote 5s；WING 订阅 9s），持续回读。"""
    _ensure_fwd_flusher()            # 转发合并器 (幂等; --bridge 启动参数也走这里)
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.settimeout(0.5)
    BRIDGE_SOCK[0] = sock
    BRIDGE["addr"] = (ip, port)
    BRIDGE["ip"], BRIDGE["port"], BRIDGE["synced"] = ip, port, False
    BRIDGE["started"] = time.time()
    BRIDGE["last_warn"] = 0.0
    p0 = profile()
    # 保活命令：X32 是 /xremote；WING 是订阅（/%<本地端口>/*S，10 秒不续即死）
    keep_cmd = str(getattr(p0, "keepalive_cmd", "/xremote") or "/xremote")
    if "{port}" in keep_cmd:
        # WING 要一个明确的回包端口。必须先 bind 再取端口 —— Windows 上对
        # 未 bind 的 UDP socket 调 getsockname() 会抛 OSError 10022(WSAEINVAL)，
        # 而这个异常发生在桥接线程最开头，表现就是"桥接启动成功、一个包都不发"。
        try:
            sock.bind(("0.0.0.0", 0))
        except OSError as e:
            log("BRIDGE 绑定本地回包端口失败: %r" % e)
        try:
            keep_cmd = keep_cmd.replace("{port}", str(sock.getsockname()[1]))
        except OSError:
            keep_cmd = keep_cmd.replace("{port}", "2223")
    keep_iv = float(getattr(p0, "keepalive_interval", 5.0) or 5.0)
    log("BRIDGE 桥接启动: 真台 %s:%d (写入转发 + %s 保活/订阅 + 状态回读)" % (
        ip, port, keep_cmd))
    if getattr(p0, "keepalive_note", ""):
        log("BRIDGE 注意: %s" % p0.keepalive_note)
    _bridge_full_sync(sock)
    BRIDGE["last_keep"] = 0.0        # 立即发首次保活完成订阅
    while BRIDGE["addr"] is not None:
        # 保活: X32 每 5 秒 /xremote；WING 每 9 秒续订阅（真台 10 秒无保活就断）
        if time.time() - BRIDGE["last_keep"] >= keep_iv:
            try:
                sock.sendto(encode_message(OscMsg(keep_cmd, [])), (ip, port))
                BRIDGE["last_keep"] = time.time()
            except OSError:
                pass
        # 真台长期无回包 → 每 30 秒提示一次 (排查 IP / 网线 / 是否同网段)
        ref = max(BRIDGE["last_recv"], BRIDGE.get("started", 0.0))
        if time.time() - ref > 20.0 and time.time() - BRIDGE["last_warn"] > 30.0:
            BRIDGE["last_warn"] = time.time()
            log("BRIDGE 真台无回包 (%s:%d) — 请检查地址、网线与是否在同一网段" % (ip, port))
        # 收真台回包/推送
        end = time.time() + 0.5
        while time.time() < end and BRIDGE["addr"] is not None:
            try:
                data, addr = sock.recvfrom(4096)
            except socket.timeout:
                break
            except OSError:
                break
            BRIDGE["last_recv"] = time.time()
            if addr[0] != ip:
                continue
            try:
                msgs = decode_packet(data)
            except Exception:
                continue
            for msg in msgs:
                a = msg.address
                if a.startswith("/meters") or a == "/xinfo" or a.startswith("/xremote"):
                    continue
                if a == "/*":
                    # 节点批量写的回执：WING 只回 OK 或错误串（NODE NOT FOUND /
                    # VALUE ERROR / BUFFER OVERFLOW / NODE IS NOT PAR / INCOMPLETE DATA）
                    txt = str(msg.args[0]) if msg.args else ""
                    if txt and txt.upper() != "OK":
                        log("BRIDGE 批量写被拒: %s" % txt)
                        if WING_NODE_WRITE[0]:
                            WING_NODE_WRITE[0] = False
                            log("BRIDGE 已自动关闭 WING 节点批量写，退回逐条发送")
                    continue
                # WING 的地址空间与 X32 不通用，先让驱动自己认领；
                # 认不出再回落到 X32 的模板反查（M32 等仍走那条）。
                own = profile().parse_addr(a)
                matches = [own] if own else match_address(a)
                if not matches or not msg.args:
                    continue
                k, i = matches[0]
                raw = msg.args[0]
                if isinstance(raw, str) and raw:
                    try:
                        raw = float(raw)
                    except ValueError:
                        # 算法名（WING 的 mdl / X32 的 type）本来就是字符串，不能丢
                        if k not in ("fx_type", "fx_name"):
                            continue
                try:
                    _bridge_apply_readback(k, i, raw)
                except Exception as e:
                    log("BRIDGE 回读处理出错 %s: %r" % (a, e))
    BRIDGE_SOCK[0] = None
    BRIDGE["synced"] = False
    log("BRIDGE 桥接已断开 (%s:%d)" % (ip, port))


def bridge_start(addr_str):
    """启动桥接 (网页设置或 --bridge 参数): addr_str = 'IP:PORT'。"""
    try:
        ip, p = str(addr_str).strip().rsplit(":", 1)
        port = int(p)
    except (ValueError, AttributeError):
        return False, "地址格式应为 IP:端口"
    if not ip:
        return False, "地址格式应为 IP:端口"
    # 端口校验与 /api/ports 用同一个 valid_port，别处严、这里松
    if not (1 <= port <= 65535):
        return False, "端口必须是 1–65535"
    # 已有桥接先停
    bridge_stop()
    BRIDGE["addr"] = (ip, port)      # 先占位, 让线程启动前 set_value 也能拿到
    BRIDGE["ip"], BRIDGE["port"] = ip, port
    _ensure_fwd_flusher()            # 转发合并器 (常驻幂等)
    threading.Thread(target=bridge_client, args=(ip, port), daemon=True).start()
    return True, "桥接已启动 → %s:%d" % (ip, port)


def bridge_stop():
    if BRIDGE["addr"] is not None:
        ip, port = BRIDGE["addr"]
        BRIDGE["addr"] = None
        with BRIDGE_FWD["lock"]:
            BRIDGE_FWD["pending"].clear()   # 断开后不再有真台可发, 别留着旧值
        log("BRIDGE 停止桥接 (%s:%d)" % (ip, port))

# ---- 桥接模式: 网页/卡片写入转发到真台 (OSC), 真台状态回读同步到本地 ----
# 离线验证: 再开一个模拟器实例当"假真台", 本实例 --bridge 127.0.0.1:假台端口
BRIDGE = {"addr": None, "ip": "", "port": 0, "synced": False,
          "last_keep": 0.0, "last_recv": 0.0, "started": 0.0, "last_warn": 0.0}
BRIDGE_SOCK = [None]
BRIDGE_LOCK = threading.Lock()
# ⚠️ 可变容器: 网页断开/连接与配置加载都会改写它, main() 启动时要读最新值。
BRIDGE_TARGET = [""]   # 记住上次连过的真台地址, 下次启动自动重连 (B3 零配置的关键)
FWD_RECENT = {}      # (kind, idx) -> [value, time] 最近转发记录, 用于抑制回读回声

# ---- 桥接转发合并器 (治"写风暴") ----
# ⚠️ 曾经每条写入都单独 sendto: fade_all 时 80 个地址 × 20Hz ≈ 1000+ 个 UDP 包/秒,
#    真台 OSC 栈被刷满 (本机也忙)。现在高频写入先进合并队列 (同地址只留最新值),
#    由常驻线程每 20ms 按 **一个 Bundle** 发出:
#      - 同一地址按来源限速: 手动(用户拖推子) 50ms 保灵敏, 卡片/回归渐变 250ms
#       (真台 4Hz 跟随电动推子无感知, 而 fade_all 的包量直接降一个量级);
#      - 包数降一个量级 (真台每包只 recvfrom + 解析一次);
#      - **最后一个值一定送达**: pending 始终只留最新值, 渐变到点/被停止后,
#        一拍 (≤20ms + 间隔) 内一定发出, 不会卡在中间值上。
BRIDGE_FWD_MIN_GAP = {"manual": 0.05, "fade": 0.25, "action": 0.25, "dca": 0.1, "auto": 0.1}
BRIDGE_FWD_GAP_DEFAULT = 0.1
BRIDGE_FWD_TICK = 0.02       # 合并器轮询间隔
BRIDGE_FWD_MAX_BATCH = 256   # 单拍最多发出条数 (防极端堆积把 UDP 包撑爆)
BRIDGE_FWD = {"pending": {}, "last": {}, "lock": threading.Lock()}
BRIDGE_FWD_THREAD = [None]
# WING 节点批量写（`/ ,s "/ch.1.fdr=0,/ch.2.fdr=-10"`）—— **默认关**。
# WING 对整包做原子校验：一条路径不被接受就整批回 `NODE NOT FOUND`，这一拍
# 所有写入全丢；逐条发虽然包多，但一条失败不影响其余。需要时用环境变量
# X32_WING_NODE_WRITE=1 打开，且被台子拒一次会自动关回去（见 recv 里的 /*,s）。
WING_NODE_WRITE = [os.environ.get("X32_WING_NODE_WRITE", "").strip().lower()
                   not in ("", "0", "false", "off", "no")]


class _BridgeSink(WriteSink):
    """桥接写入转发 (作为写出口注册进 state.SINKS)。

    门槛条件 (原 set_value 尾部的 if) 收在这里: 桥接未连接或来源不在
    转发范围时直接返回。一律使用调用方传来的 after 值。
    """

    def on_write(self, kind, idx, value, source):
        if BRIDGE["addr"] is None or source not in ("manual", "action", "dca", "fade", "auto"):
            return
        _bridge_forward(kind, idx, value, source)


BRIDGE_SINK = _BridgeSink()


# ==================================================================
# ==== x32sim/fx.py
# ==================================================================
# -*- coding: utf-8 -*-
"""x32sim/fx — FX 机架: 混响同步 / Tap 定拍 / 效果库元信息"""

import threading
import time

# ⚠️ make_single.py 只认单行相对导入 (多行括注会被判"不支持"直接拒生成)


def fx_algos():
    """当前控台的效果库（算法名 → 定义）。未标定控台返回空表。

    这是"效果槽与调音台同步"的唯一取数口：混响页的算法下拉、算法参数索引、
    写入校验、Tap 钳制范围、桥接查询参数号，全部经这里 —— 切控台即整体换库。
    """
    return profile().fx_algos


def fx_lib_meta():
    """给 UI 的效果库元信息（含分类与槽位约束，供算法下拉分组渲染）。"""
    p = profile()
    lib = p.fx_algos
    cats = {}
    for k, v in lib.items():
        cats.setdefault(v.get("cat", "misc"), []).append(k)
    return {"id": p.id, "label": p.label, "vendor": p.vendor,
            "ready": p.ready, "verified": p.verified,
            "slots": int(p.counts.get("fx", 0)), "libCount": len(lib),
            "locked": (not p.ready) or ("fx" not in p.caps),
            "catLabel": FX_CAT_LABEL,
            "cats": cats,
            "heavySlots": list(FX_SLOTS_HEAVY),
            # label = 中文（辅助），en = 真台显示名（主）。前端一律先显示 en。
            # mdl = 该控台的线上枚举名（WING 用；X32 没有这个概念，为 None）。
            "algos": {k: {"label": v["label"], "en": v.get("en") or k,
                          "mdl": v.get("wing_mdl"),
                          "cat": v.get("cat", "misc"),
                          "heavy": bool(v.get("heavy")), "n": v.get("n", 0)}
                      for k, v in lib.items()}}


def fx_algo(slot):
    """取某个槽的算法定义（按**当前控台的效果库**查）; 未装载或算法不在本库则返回 None。"""
    t = STATE.fx.get(slot, {}).get("type", "")
    return fx_algos().get(t)


def fx_par_spec(slot, pnum):
    """(slot, par 号) → 参数规格 dict；未装载算法或号越界 → None。"""
    algo = fx_algo(slot)
    if not algo:
        return None
    try:
        pnum = int(pnum)
    except (TypeError, ValueError):
        return None
    for p in algo["params"]:
        if p["p"] == pnum:
            return p
    return None


def fx_field_par(slot, field):
    """field 名 → par 号。支持三类：
      1. 算法参数 field（如 'decay'）—— 按当前槽算法的参数表查；
      2. 'parNN' 直接寻址（如 'par07'）；
      3. 语义别名 time/predelay/damp —— 按算法里的别名映射。
    槽级字段 type/on/mix/name 不适用（返回 None，由调用方处理）。
    """
    field = str(field)
    algo = fx_algo(slot)
    if not algo:
        return None
    if field.startswith("par") and field[3:].isdigit():
        n = int(field[3:])
        return n if any(p["p"] == n for p in algo["params"]) else None
    for p in algo["params"]:
        if p["field"] == field:
            return p["p"]
    alias = {"time": "time", "predelay": "predelay", "damp": "damp"}.get(field)
    if alias and alias in algo:
        return algo[alias]
    return None


def fx_par_clamp(slot, pnum, value):
    """按**该算法该参数**的量程钳制（表驱动，取代旧的 time/predelay/damp 特判）。"""
    v = _finite(value, 0.0)
    spec = fx_par_spec(slot, pnum)
    if spec is None:
        return min(max(v, 0.0), 1.0)
    if spec["kind"] == "i":
        return int(round(min(max(v, spec["lo"]), spec["hi"])))
    return min(max(v, spec["lo"]), spec["hi"])


# ---------------------------------------------------------------- 混响同步 / Tap 定拍
# 目标: 一次 Tap 或一次改动, 把「混响时间」按同步模式铺到联动组内所有混响槽;
# 而且**双向**成立 —— 真台上改了混响, 也同步回本地并铺给组内其他槽。
#
# 三种同步模式 (谁说了算):
#   software 软件主导: 软件改动 → 铺组内 + 下发真台; 真台回读只镜像自己, 不再外扩
#   console  台面主导: 真台改动 → 铺组内 + 镜像到软件; 软件改动只改该槽, 不外扩
#   both     双向互同步: 谁改都铺给组内
#
# 防回环的关键: 铺给其他槽的写入一律用 source="action", 它**不会再触发铺散**
# (见 set_value 末尾的钩子), 而且每次转发都记进 FWD_RECENT, 真台回读到的回声
# 由 _fwd_is_echo 吸收 —— 所以 software→真台→回读 与 真台→本地→真台 两条链
# 都在两跳内收敛, 不会无限震荡。
FX_SYNC = {"mode": "software", "group": [1, 2], "followTap": True,
           "bpm": 120.0, "note": "1/4", "dotted": False}
TAP_STATE = {"times": [], "count": 0, "bpm": 0.0}
FX_SYNC_LOCK = threading.Lock()
FX_MODE_LABEL = {"software": "软件主导", "console": "台面主导", "both": "双向互同步"}


def note_seconds(bpm, note="1/4", dotted=False):
    """BPM + 时值 → 秒数。四分音符 = 1 拍 = 60/BPM 秒; 附点 = ×1.5。"""
    beats = NOTE_BEATS.get(str(note), 1.0)
    if dotted:
        beats *= 1.5
    bpm = min(max(_finite(bpm, 120.0), TAP_BPM_MIN), TAP_BPM_MAX)
    return beats * 60.0 / bpm


def tap_reset():
    with FX_SYNC_LOCK:
        TAP_STATE["times"] = []
        TAP_STATE["count"] = 0
        TAP_STATE["bpm"] = 0.0


def tap_register(now=None):
    """记一次 Tap, 返回 (bpm, 点击次数, 是否已成拍)。
    · 两次点击间隔 < TAP_INTERVAL_MIN → 判为抖动, 忽略
    · 距上次点击 > TAP_RESET_GAP → 视为新的一组, 清空重来
    · 取最近 TAP_MAX_INTERVALS 个间隔的**均值** → BPM (比只用最后一次稳得多)
    """
    now = time.time() if now is None else float(now)
    with FX_SYNC_LOCK:
        t = TAP_STATE
        if t["times"] and now - t["times"][-1] > TAP_RESET_GAP:
            t["times"] = []
            t["count"] = 0
        if t["times"] and now - t["times"][-1] < TAP_INTERVAL_MIN:
            return t["bpm"], t["count"], len(t["times"]) >= 2
        t["times"].append(now)
        t["count"] += 1
        if len(t["times"]) > TAP_MAX_INTERVALS + 1:
            t["times"] = t["times"][-(TAP_MAX_INTERVALS + 1):]
        if len(t["times"]) < 2:
            return 0.0, t["count"], False
        gaps = [t["times"][i + 1] - t["times"][i] for i in range(len(t["times"]) - 1)]
        t["bpm"] = min(max(60.0 / (sum(gaps) / len(gaps)), TAP_BPM_MIN), TAP_BPM_MAX)
        FX_SYNC["bpm"] = t["bpm"]
    return TAP_STATE["bpm"], TAP_STATE["count"], True


def _reverb_slots():
    """装了**混响类**算法（有 decay 参数）的槽 —— Tap/同步组只对这些槽有意义。"""
    out = []
    for s in range(1, FX_COUNT + 1):
        a = fx_algo(s)
        if a and a.get("cat") == "reverb" and "time" in a:
            out.append(s)
    return out


def fx_sync_targets():
    """联动组里的混响槽。组为空时退化为「所有装了混响算法的槽」, 免得 Tap 变成空动作。"""
    with FX_SYNC_LOCK:
        g = [int(s) for s in FX_SYNC.get("group", [])
             if isinstance(s, (int, float)) and 1 <= int(s) <= FX_COUNT]
    if g:
        return sorted(set(g) & set(_reverb_slots()))
    return _reverb_slots()


def _time_seconds_to_param(algo, seconds):
    """Tap 换算出的秒数 → 该算法 decay 参数的原生值（注意 GATE/RVRS 的 decay 是毫秒）。"""
    if algo.get("tunit") == "ms":
        return float(seconds) * 1000.0
    return float(seconds)


def _fx_time_fanout(src_slot, seconds, source):
    """把一个混响时间铺给联动组里的其他槽。
    source='manual' = 来自软件;  source='sync' = 来自真台回读。"""
    with FX_SYNC_LOCK:
        mode = FX_SYNC.get("mode", "software")
    if mode == "software" and source == "sync":
        return                      # 软件主导: 真台改哪个就只镜像哪个, 不外扩
    if mode == "console" and source == "manual":
        return                      # 台面主导: 软件改动不外扩
    algo = fx_algo(src_slot)
    if not algo or "time" not in algo:
        return
    target_val = _time_seconds_to_param(algo, seconds)
    spread = []
    for s in fx_sync_targets():
        if s == src_slot:
            continue
        a = fx_algo(s)
        if not a or "time" not in a:
            continue
        cur = get_value(fx_par_kind(a["time"]), s)
        if cur is not None and abs(float(cur) - target_val) < 1e-4:
            continue                # 已经一样了, 不写也不转发 (省一次 OSC)
        set_value(fx_par_kind(a["time"]), s, target_val, source="action")
        spread.append(s)
    if spread:
        log("REVERB 同步[%s] FX%d %.2fs → 组内 %s" % (
            FX_MODE_LABEL.get(mode, mode), src_slot, float(seconds),
            "/".join("FX%d" % s for s in spread)))


def fx_set_param(slot, field, value, source="manual"):
    """效果槽的统一写入口。

    field ∈ 槽级字段（type/on/mix/name）∪ 当前算法的任意参数 field
    （如 decay/predelay/damping/speed/…，见 fxlib 标定表）∪ 'parNN' 直接寻址。
    语义别名 time/predelay/damp 继续可用（按算法别名映射到正确 par 号）。
    返回 (写入后的值, 错误串)。

    ⚠️ 三道控台门禁（与 §4 控台驱动层同一条原则：不支持的写入要**拒绝并记日志**，
    而不是静默地写到一个"看起来像"的地方）：
      · 控台未标定 → 整个效果槽不可写
      · 控台没有 fx_par 能力 → 算法参数不可写（槽级 type/on/mix 仍可）
      · 算法参数号/field 不在该算法的标定表里 → 拒写（不猜地址）
      · heavy 算法（混响/延迟/组合/变调）只能进 FX 1–4（真台 DSP 限制）
    """
    try:
        slot = int(slot)
    except (TypeError, ValueError):
        return None, "bad slot"
    if not (1 <= slot <= FX_COUNT):
        return None, "bad slot"
    prof = profile()
    if not prof.ready or "fx" not in prof.caps:
        log("FX 拒绝写入 %s: 控台「%s」%s" % (
            field, prof.label, "驱动待标定" if not prof.ready else "不支持效果槽"))
        return None, "控台「%s」%s，效果槽写入已被拒绝" % (
            prof.label, "驱动待标定" if not prof.ready else "不支持效果槽")
    field = str(field)
    if field == "type":
        t = str(value).strip().upper()
        if t and t not in fx_algos():
            return None, "算法 %s 不在「%s」的效果库中" % (t, prof.label)
        if t and not slot_allows(slot, t):
            return None, ("算法 %s 只能装入 FX %s（真台 DSP 算力限制），"
                          "FX%d 装不了" % (t, "/".join(map(str, FX_SLOTS_HEAVY)), slot))
        set_value("fx_type", slot, t, source)
        return get_value("fx_type", slot), None
    if field == "name":
        set_value("fx_name", slot, str(value)[:12], source)
        return get_value("fx_name", slot), None
    if field == "on":
        set_value("fx_on", slot, _truthy(value), source)
        return get_value("fx_on", slot), None
    if field == "mix":
        set_value("fx_mix", slot, _clamp01(value), source)
        return get_value("fx_mix", slot), None
    if "fx_par" not in prof.caps:
        log("FX 拒绝写入 %s: 控台「%s」未标定效果参数地址" % (field, prof.label))
        return None, "控台「%s」未标定效果参数地址，无法写入 %s" % (prof.label, field)
    pnum = fx_field_par(slot, field)
    if pnum is None:
        algo = fx_algo(slot)
        if not algo:
            return None, "slot has no effect"
        return None, "算法 %s 没有参数 %s" % (algo["label"], field)
    spec = fx_par_spec(slot, pnum)
    v = fx_par_clamp(slot, pnum, value)
    if spec["kind"] == "i":
        v = int(round(v))
    set_value(fx_par_kind(pnum), slot, v, source)   # 若是时间参数, set_value 内部会触发铺散
    return v, None


def fx_tap_apply():
    """把 Tap 出的 BPM 按当前时值换算成混响时间, 写进联动组 (受 followTap 控制)。
    返回 (换算秒数 / None, 明细列表 或 错误串)。"""
    with FX_SYNC_LOCK:
        bpm = FX_SYNC.get("bpm") or TAP_STATE["bpm"]
        note = FX_SYNC.get("note", "1/4")
        dotted = bool(FX_SYNC.get("dotted"))
        follow = bool(FX_SYNC.get("followTap"))
    if not bpm or bpm <= 0:
        return None, "还没 Tap 出拍子"
    secs = note_seconds(bpm, note, dotted)
    if not follow:
        return secs, []             # followTap 关着: 只返回算好的时间, 不写槽
    written = []
    for s in fx_sync_targets():
        algo = fx_algo(s)
        if not algo or "time" not in algo:
            continue
        want = _time_seconds_to_param(algo, secs)
        clamped = min(max(want, algo["tmin"]), algo["tmax"])
        # source="action": 一次性写全部目标, 不再触发铺散 (铺散是给"单点改动"用的)
        set_value(fx_par_kind(algo["time"]), s, clamped, source="action")
        written.append({"slot": s, "time": clamped, "clamped": abs(clamped - want) > 1e-4})
    log("REVERB Tap %.1f BPM × %s%s = %.2fs → %d 个混响槽" % (
        bpm, note, "(附点)" if dotted else "", secs, len(written)))
    return secs, written


def fx_state():
    """给网页/API 的效果器快照。算法库一律来自**当前控台驱动**。

    每槽返回：槽级字段（type/label/name/on/mix/cat/heavy/loaded/known）+
    该算法**全部参数**的当前值（按 fxlib 标定表的 par 号顺序，含
    field/label/unit/kind/lo/hi/opts/value/unset），前端据此动态渲染控件，
    不需要为每种算法写死 UI。

    ⚠️ 未设置语义：换算法后 par 只播种标定过的默认值（REVERB_DEFAULTS），
    其余参数保持"未设置"—— value=None / unset=True。**不拿 0.0 冒充**：
    大量参数 lo>0（频率/时间），0 越界会把滑杆骗到一端，还让人以为台子
    真是那个值。OSC 线上对未设置参数仍回 0.0（get_value 的既有行为）。

    遗留键 time/predelay/damp/tmin/tmax/tunit: 旧版 UI 与三端过渡用，
    按 alias 从 params 推导；算法没有对应别名（非混响类）时为 None。
    """
    lib = fx_algos()
    slots = []
    with STATE.lock:
        for s in range(1, FX_COUNT + 1):
            fx = STATE.fx[s]
            t = fx.get("type") or ""
            algo = lib.get(t)
            item = {"slot": s, "type": t, "label": algo["label"] if algo else "",
                    "name": fx["name"], "on": int(fx["on"]), "mix": float(fx["mix"]),
                    "cat": algo.get("cat", "") if algo else "",
                    "heavy": bool(algo.get("heavy")) if algo else False,
                    # loaded = 槽里有东西；known = 这个算法属于**本控台**的效果库。
                    # 两者必须分开：真台上可能装着本库没有的算法，那叫"未知"，
                    # 不叫"空槽" —— 页面要能区分，否则用户看不到真台上发生了什么。
                    "loaded": bool(t), "known": bool(algo),
                    "params": [], "alias": {},
                    "time": None, "predelay": None, "damp": None,
                    "tmin": None, "tmax": None, "tunit": None}
            if algo:
                for p in algo["params"]:
                    raw = fx["par"].get(p["p"])
                    if raw is None:
                        v, unset = None, True
                    else:
                        v, unset = float(raw), False
                        if p["kind"] == "i":
                            v = int(round(v))
                    item["params"].append({
                        "p": p["p"], "field": p["field"], "label": p["label"],
                        "unit": p["unit"], "kind": p["kind"],
                        "lo": p["lo"], "hi": p["hi"], "opts": p["opts"],
                        # w = 当前控台**能写**这个参数（WING 是命名参数，只有标定过的
                        # 才有地址）。前端据 w 灰掉控件：宁可没有滑杆，也不要一个
                        # 拖了没反应的假滑杆 —— 那会让人以为台子坏了。
                        "w": addr_for_write(fx_par_kind(p["p"]), s) is not None,
                        "value": v, "unset": unset})
                for a in ("time", "predelay", "damp"):
                    if a in algo:
                        item["alias"][a] = algo[a]
                        # 遗留键: 未设置的参数同样给 None (旧 UI 靠它显示"空槽")
                        raw = fx["par"].get(algo[a])
                        if raw is not None:
                            item[a] = float(raw)
                if "time" in algo:
                    item["tmin"] = algo.get("tmin")
                    item["tmax"] = algo.get("tmax")
                    item["tunit"] = algo.get("tunit", "s")
            slots.append(item)
    with FX_SYNC_LOCK:
        sync = dict(FX_SYNC)
        sync["group"] = list(FX_SYNC.get("group", []))
        tap = {"count": TAP_STATE["count"], "bpm": TAP_STATE["bpm"]}
    meta = fx_lib_meta()
    # console/libId: 前端靠 libId 变化判断"效果库换了一套" => 重建算法下拉
    return {"slots": slots, "sync": sync, "tap": tap, "noteBeats": dict(NOTE_BEATS),
            "console": meta, "libId": meta["id"], "algos": meta["algos"]}


# ==================================================================
# ==== x32sim/oscsrv.py
# ==================================================================
# -*- coding: utf-8 -*-
"""x32sim/oscsrv — OSC 消息分发 (UDP 主循环的每个包)"""

import struct



def handle(msg: OscMsg, addr, sock):
    a = msg.address
    log("%-28s <- %s  args=%s" % (addr[0], a, msg.args))

    if a == "/xinfo":
        ip = sock.getsockname()[0]
        reply = OscMsg("/xinfo", [ip, SIM_NAME, SIM_MODEL, SIM_FIRMWARE])
        sock.sendto(encode_message(reply), addr)
        return

    if a in ("/subscribe", "/unsubscribe"):
        # 协议 /subscribe ,s<地址> [,i<倍数>]: "我关心这个地址, 每 N×50ms 回一次"
        # 无地址参数时退化成"台面变更推送订阅"(旧行为, 保留兼容)。
        pat = None
        for arg in msg.args:
            if isinstance(arg, str) and arg.startswith("/"):
                pat = arg
                break
        rate = 1
        for arg in msg.args[1:]:
            if isinstance(arg, (int, float)) and not isinstance(arg, bool):
                rate = int(arg)
                break
        if a == "/subscribe":
            first = subscribe_client(addr)
            if pat:
                subscribe_pattern(addr, pat, rate)
            log("    订阅: %s %s (rate=%d, %s, 共 %d 个来源)" % (
                addr, pat or "(台面变更)", rate,
                "首次" if first else "续期", len(METER_SUBSCRIBERS)))
        else:
            if pat:
                unsubscribe_pattern(addr, pat)
            else:
                unsubscribe_client(addr)
            log("    退订: %s %s (剩 %d 个来源)" % (
                addr, pat or "(全部)", len(METER_SUBSCRIBERS)))
        return

    if a in ("/xremote", "/xcontrol"):
        # 真台保活: 续期该来源的订阅 (30 秒无续期自动清理)
        # ⚠️ 真台 /xremote **只推变化**, 不推初始全量; 需要初始值时客户端应逐条
        #    GET 或 /subscribe。这里保留同语义, 首帧补全由 --xremote-snapshot 开启。
        subscribe_client(addr)
        return

    if a.startswith("/meters"):
        if msg.args and msg.args[0] == 0:
            unsubscribe_client(addr)
            log("    电平表退订: %s" % (addr,))
        else:
            subscribe_client(addr)
            log("    电平表订阅: %s (共 %d 个订阅者)" % (addr, len(METER_SUBSCRIBERS)))
            # 对齐真机: 每次请求立即回一帧
            floats = compute_levels()
            blob = struct.pack(">i", len(floats))
            for v in floats:
                blob += struct.pack(">f", v)
            sock.sendto(encode_message(OscMsg("/meters/1", [blob])), addr)
        return

    if a.startswith("/scene/") and a.endswith("/load"):
        try:
            n = int(a.split("/")[2])
        except (ValueError, IndexError):
            return
        with STATE.lock:
            STATE.scene = n
        # 桥接时同步给真台 —— 客户端直连模拟器发 /scene/N/load 也要落到台面上,
        # 否则"网页切了、真台没切"，且这条路径连日志都看不出问题。
        _fwd = bridge_scene(n)
        log("    场景切换 -> %d%s" % (n, "（已转发真台）" if _fwd else ""))
        return

    if a == "/reboot" or a == "/quit":
        log("    收到重启指令,忽略")

    # 通道/输出名称读写: /ch/01/config/name (字符串参数, 真台同款地址)
    segs = a.strip("/").split("/")
    # ⚠️ /fx/<槽>/config/name (FX 机架槽名) 故意排除在外: NAME_COUNTS 没有
    #    "fx", 早年它在这里被静默 return, 导致 state 里的 fx_name kind 虽然
    #    齐全却永远收不到查询 (iOS 从 v1.3 起就在问这个地址, 一直是哑的)。
    #    放它走下面 match_address 的 fx_name 分支, 回包地址由 profiles 给。
    # ⚠️ fxrtn 是真台拼写 (Maillot: /fxrtn/[01..08]/config/name), 与 fxret
    #    同一个命名空间, 这里归一并收。
    if len(segs) == 4 and segs[2] == "config" and segs[3] == "name" and segs[0] != "fx":
        g = "fxret" if segs[0] == "fxrtn" else segs[0]
        if g == "main" and segs[1] == "st":
            idx = 0
        else:
            try:
                idx = int(segs[1].rstrip("LR"))
            except ValueError:
                log("    (名称地址未识别: %s)" % a)
                return
        cnt = NAME_COUNTS.get(g)
        if g == "main":
            pass
        elif not cnt or not 1 <= idx <= cnt:
            log("    (名称地址未识别: %s)" % a)
            return
        if msg.args and isinstance(msg.args[0], str):
            set_name(g, idx, msg.args[0])
        else:
            sock.sendto(encode_message(OscMsg(a, [get_name(g, idx)])), addr)
        return

    matches = match_address(a)
    if not matches:
        log("    (未识别,忽略)")
        return

    # set: 带参数; get: 无参数
    if msg.args:
        kind, idx = matches[0]
        raw = msg.args[0]
        if isinstance(raw, str):
            try:
                raw = float(raw)      # X32 有时用字符串传小数
            except ValueError:
                pass                  # FX 类型/名称本来就是字符串("/fx/1/type HALL"), 原样往下传
        sp0 = PARAM_SPECS.get(kind)
        if sp0 is not None:
            # 入线换算 (与回包/转发用的 param_wire 成对): dyn/ratio 线上是
            # 0..11 的索引, 直接落库会把"第 6 档(4:1)"存成"6:1"。只在入线处做一次。
            # WING: 推子是 dB、静音 1=muted —— 同一份换算表按控台走 (param_from_wire)。
            raw = param_from_wire(sp0, raw, profile())
        set_value(kind, idx, raw)
        label = KIND_LABEL.get(kind_group(kind), kind)
        sp = PARAM_SPECS.get(kind)
        if sp is not None and not sp.push:
            # 新增通道参数 (增益/反相/延时/低切/插入/门/动态/EQ): 标签与单位取自登记表。
            # 打的是**落库后**的值 (钳制/量化之后) 而不是原始入参 —— 曾经的
            # 通用分支会把 trim 打成 "fader=3.5 (11.1 dB)", 把 hpf_on 打成
            # "mute=开", 日志整个失去排查价值。
            where = ("%02d→Bus%02d" % send_unpack(idx)) if sp.group == "send" \
                else ("%02d" % idx)
            log("    SET %s %s %s=%s" % (label, where, sp.label,
                                         param_fmt(sp, get_value(kind, idx))))
        elif kind == "ch_dca":
            log("    SET %s %02d DCA掩码=%d" % (label, idx, int(raw) & 0xFF))
        elif kind == "fx_on":
            log("    SET FX%d 开关=%s" % (idx, "开" if raw else "旁通"))
        elif kind == "fx_type":
            log("    SET FX%d 算法=%s" % (idx, raw))
        elif kind == "fx_name":
            log("    SET FX%d 名称=%s" % (idx, raw))
        elif kind == "fx_mix":
            log("    SET FX%d 混合比=%.3f" % (idx, float(raw)))
        elif fx_par_num(kind) is not None:
            log("    SET FX%d 参数%02d = %.3f" % (idx, fx_par_num(kind), float(raw)))
        elif kind.endswith("_on"):
            log("    SET %s %02d mute=%s" % (label, idx if idx else 1, "开" if raw else "静音"))
        else:
            log("    SET %s %02d fader=%.3f (%.1f dB)" % (label, idx if idx else 1, float(raw), STATE.fader_to_db(float(raw))))
        return

    # get: 单条 -> 单消息回包; 多条 -> Bundle 回包
    replies = [r for r in (value_reply(k, i) for k, i in matches) if r is not None]
    if not replies:
        log("    (当前控台不支持 %d 个匹配目标, 无回包)" % len(matches))
        return
    if len(replies) == 1:
        sock.sendto(encode_message(replies[0]), addr)
    else:
        sock.sendto(encode_bundle(replies), addr)


# ==================================================================
# ==== x32sim/presets.py
# ==================================================================
# -*- coding: utf-8 -*-
"""x32sim/presets — 台面预设: scope 模型 / 抓取 / 回归"""

import collections
import threading
import time



# ---------------------------------------------------------------- 推子快照
# 灵感来自"电动推子自动化":保存当前所有推子位置,一键让全部推子自动滑回

SNAPSHOTS = []                       # [{id, name, time, scope, data, count}]
SNAP_ID = [0]
AUTO_SNAPS = collections.deque(maxlen=5)   # 自动撤销点: 每次卡片执行前自动保存, 最多留 5 个
RECALL_STATE = {"running": None, "name": "", "progress": 0.0}
RECALL_STOP = threading.Event()
# 回归打断机制: 曾经只靠一个全局 Event —— 新回归的 worker 开头 clear() 会把
# "停止旧回归" 刚 set 的信号吃掉 (与卡片 SHOW_STOP 同族的坑), 旧回归的渐变
# 会继续跑, 和新回归抢同一批通道。现在每次启动/停止都发一个新"代"(gen),
# worker 只认自己那代; 旧 worker 下次检查 (≤0.1s) 发现代号过期即退场。
RECALL_GEN = [0]
RECALL_LOCK = threading.Lock()
RECALL_ZONE = {"gen": None, "keys": set()}   # 正在被回归渐变驱动的目标, 停止时同步用


def _recall_zone_register(starts, gen):
    with RECALL_LOCK:
        RECALL_ZONE["gen"] = gen
        RECALL_ZONE["keys"] = set((k, i) for k, i, _a, _b in starts)


def _recall_zone_clear(gen):
    """只有当代 worker 才能清 zone —— 旧代退场时不能把新代的登记擦掉。"""
    with RECALL_LOCK:
        if RECALL_ZONE["gen"] == gen:
            RECALL_ZONE["keys"] = set()


def _recall_stop_current():
    """停止当前回归 (幂等) + 把渐变冻结值同步给真台。"""
    with RECALL_LOCK:
        RECALL_GEN[0] += 1
        keys = list(RECALL_ZONE["keys"])
        RECALL_ZONE["keys"] = set()
    RECALL_STOP.set()
    RECALL_STATE["running"] = None
    if keys:
        _bridge_force_sync(keys)
    log("SNAPSHOT 手动停止回归")


def preset_group_cap(g):
    """该组有多少路（main 只有一路且编号固定 0）。"""
    if g in ("main", "scene"):
        return 1
    if g == "fx":
        return FX_COUNT
    if g == "send":
        return 32            # 发送按**通道**计数, 抓取时每通道展开 16 个 Bus
    return NAME_COUNTS.get(g, 0)


def clean_preset_scope(scope):
    """规范化预设范围。返回 (cleaned, ok, why)。

    只认白名单 —— 配置文件可手改，脏范围不能让回归变成"乱写"。
    ⚠️ ok=False 的两种情况, 调用方必须**拒绝**, 绝不能静默回落全量:
       - 传入的 scope 结构不对 (不是 dict / groups 不是 list ...);
       - 清完 groups 或 params 为空 (一个组都不合法 / 一个参数都不合法),
         或某组的编号全部越界。
       "局部预设"被脏数据变成全局, 回归时误改全台, 比报错严重得多 ——
       这就是本函数返回 ok 而不是自己挑默认值的原因。
    scope=None → 默认全量范围, ok=True (旧格式预设没有 scope 字段)。
    """
    default = {"groups": list(PRESET_DEFAULT_SCOPE["groups"]),
               "params": list(PRESET_DEFAULT_SCOPE["params"]), "indices": {}}
    if scope is None:
        return default, True, ""
    if not isinstance(scope, dict):
        return default, False, "预设范围格式不对（应为 {groups, params, indices}）"
    raw_groups = scope.get("groups")
    if not isinstance(raw_groups, list):
        return default, False, "预设范围缺少 groups 列表"
    groups = []
    for g in raw_groups:
        if g in PRESET_GROUP_PARAMS and g not in groups:
            groups.append(g)
    if not groups:
        return default, False, "范围里没有合法的组（至少选择一组）"
    raw_params = scope.get("params")
    if not isinstance(raw_params, list):
        return default, False, "预设范围缺少 params 列表"
    params = []
    for p in raw_params:
        if p not in PRESET_PARAM_LABEL:
            continue
        if any(p in PRESET_GROUP_PARAMS[g] for g in groups) and p not in params:
            params.append(p)
    if not params:
        return default, False, "范围里没有合法的参数（当前所选组不支持任何已选参数）"
    indices = {}
    raw = scope.get("indices")
    if isinstance(raw, dict):
        for g, arr in raw.items():
            if g not in groups or (g not in NAME_COUNTS and g != "send"):
                continue
            cap = preset_group_cap(g)
            picked = []
            for v in (arr if isinstance(arr, list) else []):
                try:
                    n = int(float(v))
                except (TypeError, ValueError):
                    continue
                # 越界编号**丢弃**而不是钳到边界: 手写 999 更可能是笔误,
                # 钳成 32 等于偷偷改了一个用户没选的路
                if 1 <= n <= cap and n not in picked:
                    picked.append(n)
            if picked:
                indices[g] = sorted(picked)
            elif isinstance(arr, list) and arr:
                # 原始列表非空但清完为空 = 编号全越界 → 这个组的限制会凭空消失,
                # 必须算非法, 不能让"局部"悄悄变"整组"
                return default, False, "%s 的编号全部越界（1–%d）" % (
                    PRESET_GROUP_LABEL.get(g, g), cap)
    return {"groups": groups, "params": params, "indices": indices}, True, ""


def preset_scope_text(scope):
    """人话摘要（列表与日志共用）。"""
    gs = [PRESET_GROUP_LABEL.get(g, g) for g in scope.get("groups", [])]
    ps = [PRESET_PARAM_LABEL.get(p, p) for p in scope.get("params", [])
          if p not in ("slot", "scene")]
    txt = "、".join(gs)
    if ps:
        txt += " · " + "+".join(ps)
    idx = scope.get("indices") or {}
    if idx:
        parts = []
        for g, arr in idx.items():
            shown = ",".join(str(x) for x in arr[:6]) + ("…" if len(arr) > 6 else "")
            parts.append("%s %s" % (PRESET_GROUP_LABEL.get(g, g), shown))
        txt += " · 仅 " + ";".join(parts)
    return txt


def _snap_group_items_locked(g, params, idxs):
    """持锁调用：抓一个组的参数。返回 {str(idx): {...}}，main 用 "0"。"""
    bag = {}
    if g == "main":
        item = {}
        if "fader" in params:
            item["fader"] = STATE.main.get("fader", 0.75)
        if "on" in params:
            item["on"] = STATE.main.get("on", 1)
        if "name" in params:
            item["name"] = STATE.names.get(("main", 0), "")
        if item:
            bag["0"] = item
        return bag
    if g == "send":
        # 发送: idxs 是**通道号**, 每个通道展开 16 个 Bus。
        # 键用打包后的 send idx (与 STATE.send 一致), 项里用带前缀的参数名
        # (send_level/send_on/send_tap) —— 短名 "on" 会与通道静音串味。
        for ch in idxs:
            for bus in range(1, SEND_BUS + 1):
                idx = send_pack(ch, bus)
                row = STATE.send.get(idx)
                if row is None:
                    continue
                item = {}
                for sp in SEND_PARAM_SPECS:
                    if sp.kind in params:
                        item[sp.kind] = row.get(sp.field, sp.default)
                if item:
                    bag[str(idx)] = item
        return bag
    store = getattr(STATE, g, {}) or {}
    for i in idxs:
        row = store.get(i)
        if row is None:
            continue
        item = {}
        if "fader" in params:
            item["fader"] = row.get("fader", 0.75)
        if "on" in params:
            item["on"] = row.get("on", 1)
        if "name" in params:
            item["name"] = STATE.names.get((g, i), "")
        if "dca" in params and g == "ch":
            item["dca"] = sum(1 << (d - 1) for d in range(1, 9)
                              if i in STATE.dca_members.get(d, []))
        # 通道参数 (表驱动): 参数名与 spec.field 同名, 只抓范围内勾了的那些。
        # 预设是老格式 (只有 fader/on) 时这里一个都不抓 —— 向后兼容。
        for sp in CH_PARAM_SPECS:
            if sp.field in params:
                item[sp.field] = row.get(sp.field, sp.default)
        bag[str(i)] = item
    return bag


def _grab_state_scoped_locked(scope):
    """持锁调用：按范围抓取。返回 (data, 值数量)。"""
    data, count = {}, 0
    for g in scope["groups"]:
        params = [p for p in scope["params"] if p in PRESET_GROUP_PARAMS.get(g, ())]
        if not params:
            continue
        if g == "scene":
            data["scene"] = int(STATE.scene)
            count += 1
            continue
        if g == "fx":
            slots = {}
            for i in range(1, FX_COUNT + 1):
                fx = STATE.fx[i]
                par = fx.get("par") or {}
                slots[str(i)] = {"type": fx.get("type", ""), "name": fx.get("name", ""),
                                 "on": fx.get("on", 1), "mix": fx.get("mix", 0.25),
                                 "par": {str(pp): v for pp, v in par.items()}}
                count += 4 + len(par)
            data["fx"] = slots
            continue
        if g == "main":
            idxs = [0]
        else:
            idxs = scope["indices"].get(g) or list(range(1, preset_group_cap(g) + 1))
        bag = _snap_group_items_locked(g, params, idxs)
        data[g] = bag
        count += sum(len(v) for v in bag.values())
    return data, count


def _grab_state_locked():
    """兼容旧调用：全量「推子+静音」抓取。"""
    data, _ = _grab_state_scoped_locked({"groups": list(PRESET_DEFAULT_SCOPE["groups"]),
                                         "params": ["fader", "on"], "indices": {}})
    return data


def save_snapshot(name=None, auto=False, scope=None):
    """保存预设。返回 (snap, saved_ok) —— saved_ok=False 表示只在内存里, 没落盘
    (写盘失败的"假成功"由 HTTP 层据此回报, 见 save_user_config)。
    scope 非法时抛 ValueError(原因) —— 由 HTTP 层转 400, 绝不静默存成全量。"""
    # 延迟导入: presets→persist→presets 会成环, 只在这一处打破
    # (合成单文件形态下该行被剥离, 同一命名空间直接解析)。
    if scope is None:
        sc = {"groups": list(PRESET_DEFAULT_SCOPE["groups"]),
              "params": list(PRESET_DEFAULT_SCOPE["params"]), "indices": {}}
    else:
        sc, ok, why = clean_preset_scope(scope)
        if not ok:
            raise ValueError(why)
    with STATE.lock:
        data, count = _grab_state_scoped_locked(sc)
        scene_now = int(STATE.scene)
    SNAP_ID[0] += 1
    snap = {"id": SNAP_ID[0],
            "name": (str(name).strip()[:20] if name else "") or "预设 %d" % SNAP_ID[0],
            "time": time.strftime("%H:%M:%S"),
            "scene": scene_now, "scope": sc, "data": data, "count": count}
    if auto:
        AUTO_SNAPS.append(snap)
        log("SNAPSHOT 自动撤销点: %s (%d 值)" % (snap["name"], count))
        return snap, True
    SNAPSHOTS.insert(0, snap)
    if len(SNAPSHOTS) > 8:
        SNAPSHOTS.pop()
    saved = save_user_config()     # 预设必须跨重启（以前只存在内存里，重启即丢）
    log("SNAPSHOT 保存: %s (%d 值 · %s)%s" % (
        snap["name"], count, preset_scope_text(sc), "" if saved else " ⚠️ 未落盘"))
    return snap, saved


def recall_snapshot(snap_id, seconds=3.0):
    snap = next((s for s in SNAPSHOTS if s["id"] == snap_id), None)
    if not snap:
        return None
    return start_recall(snap, seconds)


def _snap_items(snap):
    """统一新旧两种预设格式 → [(group, idx, item)]。

    旧格式（本次升级前）：顶层就是 ch/bus/... 的 {i: {fader, on}}；
    新格式：snap["data"][group][i] = {...}，可能只含部分参数。
    兼容旧数据是有意的：用户配置里可能还躺着升级前保存的快照。
    """
    out = []
    src = snap.get("data")
    if isinstance(src, dict):
        for g, bag in src.items():
            if g == "scene" or not isinstance(bag, dict):
                continue
            for k, item in bag.items():
                if not isinstance(item, dict):
                    continue
                try:
                    i = int(k)
                except (TypeError, ValueError):
                    continue
                out.append((g, i, item))
        return out
    for g in ("ch", "bus", "dca", "auxin", "usb", "fxret", "mtx", "main"):
        for k, item in (snap.get(g) or {}).items():
            if isinstance(item, dict):
                try:
                    out.append((g, int(k), item))
                except (TypeError, ValueError):
                    continue
    return out


def _recall_instant(snap):
    """立即应用：开关 / 名称 / DCA 归属 / FX 整槽 / 场景号。"""
    names_changed = False
    if isinstance(snap.get("data"), dict) and "scene" in snap["data"]:
        with STATE.lock:
            try:
                STATE.scene = min(max(int(snap["data"]["scene"]), 0), 99)
            except (TypeError, ValueError):
                pass
    for g, i, item in _snap_items(snap):
        if g == "fx":
            if 1 <= i <= FX_COUNT:
                if "type" in item:
                    set_value("fx_type", i, item.get("type", ""), source="action")
                if "name" in item:
                    set_value("fx_name", i, item.get("name", ""), source="action")
                if "on" in item:
                    set_value("fx_on", i, item.get("on", 1), source="action")
                if "mix" in item:
                    set_value("fx_mix", i, item.get("mix", 0.25), source="action")
                for p, v in (item.get("par") or {}).items():
                    set_value("fx_par_%s" % p, i, v, source="action")
            continue
        if g == "send":
            # 键就是打包后的 (通道,Bus); 参数名 = kind, 直接走 set_value
            for sp in SEND_PARAM_SPECS:
                if sp.kind in item and target_exists(sp.kind, i):
                    set_value(sp.kind, i, item[sp.kind], source="action")
            continue
        if "on" in item:
            set_value("main_on" if g == "main" else g + "_on", i,
                      item.get("on", 1), source="action")
        if "dca" in item and g == "ch":
            set_value("ch_dca", i, item.get("dca", 0), source="action")
        # 通道参数 (表驱动): 瞬时项, 立即应用。target_exists 挡掉越界编号
        # (配置文件可手改; KeyError 会把整个回归线程炸掉, 见 _recall_body 的 try)
        for sp in CH_PARAM_SPECS:
            if sp.field in item and target_exists(sp.kind, i):
                set_value(sp.kind, i, item[sp.field], source="action")
        if "name" in item:
            nm = str(item.get("name") or "").strip()[:12]
            with STATE.lock:
                if nm:
                    STATE.names[(g, i)] = nm
                else:
                    STATE.names.pop((g, i), None)
            names_changed = True
    if names_changed:
        # 延迟导入: 打破 presets↔persist 环 (另一处在 save_snapshot)
        save_user_config()


def _recall_fader_starts(snap):
    """[(kind, idx, 当前值, 目标值)] —— 只有范围里带 fader 的项才动。"""
    out = []
    for g, i, item in _snap_items(snap):
        if "fader" not in item:
            continue
        kind = "main_fader" if g == "main" else g + "_fader"
        try:
            target = _clamp01(item["fader"])
        except (TypeError, ValueError):
            continue
        out.append((kind, i, get_value(kind, i), target))
    return out


def _recall_body(snap, seconds, my_gen=None):
    """回归主体（阻塞）。调用方负责 RECALL_STATE 与线程。

    my_gen: 本次回归的代 (见 RECALL_GEN)。代号过期 (又有新回归启动/手动停止)
    立即退场 —— 曾经旧回归会和新回归抢同一批通道, 谁后跑完谁说话。
    """
    RECALL_STATE["running"] = snap.get("id")
    RECALL_STATE["name"] = snap.get("name", "")
    RECALL_STATE["progress"] = 0.0
    try:
        starts = _recall_fader_starts(snap)
        if my_gen is not None:
            _recall_zone_register(starts, my_gen)
        _recall_instant(snap)
        log("SNAPSHOT 回归开始: %s (%d 项 · %d 路推子 %.1f 秒归位)"
            % (snap.get("name", ""), snap.get("count", 0), len(starts), seconds))
        steps = max(1, int(seconds / 0.1))
        for s in range(1, steps + 1):
            if RECALL_STOP.is_set() or (my_gen is not None and my_gen != RECALL_GEN[0]):
                log("SNAPSHOT 回归被打断")
                return
            time.sleep(0.1)
            ratio = s / steps
            for kind, i, a, b in starts:
                set_value(kind, i, a + (b - a) * ratio, source="action")
            RECALL_STATE["progress"] = ratio
        log("SNAPSHOT 回归完成: %s" % snap.get("name", ""))
    except Exception as e:
        log("SNAPSHOT 回归出错: %r" % e)
    finally:
        stale = my_gen is not None and my_gen != RECALL_GEN[0]
        if not stale:
            if RECALL_STATE["running"] == snap.get("id"):
                RECALL_STATE["running"] = None
                RECALL_STATE["progress"] = 1.0
            if my_gen is not None:
                _recall_zone_clear(my_gen)


def start_recall(snap, seconds=3.0):
    """异步回归（网页按钮用）。"""
    with RECALL_LOCK:
        RECALL_GEN[0] += 1          # 旧代作废 (比 set 更可靠: worker 的 clear 吃不掉代号)
        my_gen = RECALL_GEN[0]
        RECALL_STOP.set()           # 打断进行中的回归
    seconds = min(max(_finite(seconds, 1.0), 0.5), 15.0)

    def worker():
        RECALL_STOP.clear()
        _recall_body(snap, seconds, my_gen)

    threading.Thread(target=worker, daemon=True).start()
    return snap


def recall_now(snap, seconds=1.0):
    """同步回归（测试/脚本用）：阻塞到推子滑完。

    ⚠️ 卡片动作**不要**用它 —— 时间轴是单线程非阻塞的，这里一阻塞，
    整张卡片的进度条与并行渐变都会被冻住。卡片里用「瞬时项 + 渐变分支」组合。
    """
    with RECALL_LOCK:
        RECALL_GEN[0] += 1
        my_gen = RECALL_GEN[0]
        RECALL_STOP.set()
        RECALL_STOP.clear()
    seconds = min(max(_finite(seconds, 1.0), 0.0), 15.0)
    if seconds <= 0:
        _recall_instant(snap)
        return snap
    _recall_body(snap, seconds, my_gen)
    return snap


def find_snapshot(pid):
    try:
        pid = int(pid or 0)
    except (TypeError, ValueError):
        return None
    return next((s for s in SNAPSHOTS if s["id"] == pid), None)


def snap_fade_targets(snap):
    """预设里带 fader 的项 → [(kind, idx, 目标值)]，交给时间轴渐变分支插值。"""
    out = []
    if not snap:
        return out
    for g, i, item in _snap_items(snap):
        if "fader" not in item:
            continue
        kind = "main_fader" if g == "main" else g + "_fader"
        try:
            out.append((kind, i, _clamp01(item["fader"])))
        except (TypeError, ValueError):
            continue
    return out


# ==================================================================
# ==== x32sim/actions.py
# ==================================================================
# -*- coding: utf-8 -*-
"""x32sim/actions — 动作内核: set/osc/瞬时/渐变 + 清洗白名单"""

import math



def set_target_id(target):
    """取出目标的编号。main 固定 0（只有一路）；scene 的编号即场景号。"""
    group = (target or {}).get("group")
    if group == "main":
        return 0
    try:
        return int(float((target or {}).get("id", 1)))
    except (TypeError, ValueError):
        return 1


def send_bus_of(target):
    """发送目标的 Bus 号 (1..16)。脏值一律回落到 1, 越界由执行期 target_exists 兜底。"""
    try:
        b = int(float((target or {}).get("bus", 1)))
    except (TypeError, ValueError):
        b = 1
    return min(max(b, 1), SEND_BUS)


def resolve_set_target(group, param, idx):
    """(group, param, idx) → 语义 kind; 组合不合法或不适用时返回 None。

    这里是通用动作与控台驱动层的接缝: 只产出 kind，不产出地址。
    """
    if group not in SET_GROUPS:
        return None
    if param is None:
        param = "load" if group == "scene" else "fader"
    if param not in SET_PARAMS.get(group, ()):
        return None
    if group == "scene":
        return "scene"                    # 场景是"动作"而非"值", 单独走
    if group == "send":
        # 发送的参数名**就是** kind (send_level/...), 不能再拼 "%s_%s"
        return SET_KINDMAP.get("send", {}).get(param)
    if group == "fx":
        if param in ("type", "name", "on", "mix"):
            return "fx_" + param
        algo = fx_algo(idx)               # 时间/预延迟/阻尼的参数号随算法变化
        if not algo:
            return None                   # 空槽没有这些参数
        return fx_par_kind(algo[param])
    return "%s_%s" % (group, param)


def _exec_set(act):
    """通用动作: 设置某个语义目标的值。"""
    tg = act.get("target") or {}
    group = tg.get("group")
    param = tg.get("param", "fader")
    idx = set_target_id(tg)

    if group == "scene":
        n = max(1, idx)
        with STATE.lock:
            STATE.scene = n
        log("SHOW 切场景 %d" % n)
        return
    if group == "send":
        # 发送是二维目标: id 是通道, bus 是 Bus。打包成 STATE.send 的一维键,
        # 之后的 addr/target_exists/set_value 都按一维走 (与 OSC 路径同一套)。
        idx = send_pack(idx, send_bus_of(tg))

    kind = resolve_set_target(group, param, idx)
    if kind is None:
        log("SHOW 跳过设置 %s.%s #%d: 参数组合不被支持" % (group, param, idx))
        return
    p = profile()
    if p.addr(kind, idx) is None:
        log("SHOW 跳过设置 %s.%s #%d: 控台「%s」不支持%s"
            % (group, param, idx, p.label, "（驱动待标定）" if not p.ready else ""))
        return
    if not target_exists(kind, idx):
        log("SHOW 跳过设置 %s.%s #%d: 本地台面没有这个目标" % (group, param, idx))
        return
    set_value(kind, idx, act.get("value", 0.0), source="action")
    log("SHOW 设置 %s" % _act_label(act))


def _exec_osc(act):
    """原始 OSC 动作: 直接发一条自定义消息。

    ⚠️ 这个动作**不是跨控台**的 —— 地址是控台专有的。换控台后同一条消息可能指向
    别的参数（甚至无效），所以 UI 上要明确标注。行为分两种：
      1. 地址能被本机解析（match_address 认得）→ 走 set_value：本地状态同步 + 桥接转发；
      2. 解析不出来 → 只发往桥接的真台；没有桥接则记日志忽略。
    两条路都会写日志，不会静默。
    """
    a = str(act.get("address", ""))
    args = list(act.get("args") or [])
    m = match_address(a)
    if m and args:
        kind, idx = m[0]
        # ⚠️ 推子/静音类 kind 要的是**数字**，但前端允许原始 OSC 带字符串参数
        #    （`/fx/1/config/name "MyHall"` 是合法的）。曾经的写法是直接把
        #    args[0] 递给 set_value，于是一个手滑的 "abc" 就 float() 抛
        #    ValueError 把卡片线程炸掉 —— 界面还显示"卡片已完成"。
        #    现在：转不成数字就降级成"只发真台"，本地状态不碰。
        v = args[0]
        if kind not in ("fx_name", "fx_type"):
            try:
                v = float(v)
            except (TypeError, ValueError):
                v = None
            if v is not None and not math.isfinite(v):
                v = None          # NaN/inf 也不写本地 —— 会污染 /api/state
        if v is None:
            log("SHOW 原始 OSC %s: 参数 %r 不是数字，已降级为只发真台（不动本地状态）"
                % (a, args[0]))
        else:
            set_value(kind, idx, v, source="action")
            log("SHOW 原始 OSC %s %s (已应用到本地)" % (a, args))
            return
    sock = BRIDGE_SOCK[0]
    if sock is None or BRIDGE["addr"] is None:
        log("SHOW 原始 OSC %s: 未桥接真台, 已忽略" % a)
        return
    try:
        sock.sendto(encode_message(OscMsg(a, args)), BRIDGE["addr"])
        log("SHOW 原始 OSC %s %s (已发往真台)" % (a, args))
    except Exception as e:
        log("SHOW 原始 OSC 发送失败: %r" % e)


def _act_duration(act):
    """动作占用时间轴的秒数; 瞬时动作(静音/场景)为 0。"""
    k = act.get("kind")
    if k == "set":
        # 通用设置默认**瞬时**（duration 缺省为 0）；给了 duration 才占时间轴走渐变
        try:
            d = float(act.get("duration", 0.0) or 0.0)
        except (TypeError, ValueError):
            d = 0.0
        return max(0.05, d) if d > 0 else 0.0
    if k == "preset":
        try:
            return max(0.5, float(act.get("duration", 2.0)))
        except (TypeError, ValueError):
            return 2.0
    if k == "scene":
        # 全局 recall 是瞬时的（模拟器/真台都一样，真台生效有延迟但那是台子的事）;
        # 局部调用要占时间轴，推子按 duration 滑回去
        if (act.get("mode") or "global") == "partial":
            try:
                return max(0.05, float(act.get("duration", 1.0)))
            except (TypeError, ValueError):
                return 1.0
        return 0.0
    if k == "wait" or k in FADE_ACT_KINDS:
        try:
            return max(0.05, float(act.get("duration", 3.0)))
        except (TypeError, ValueError):
            return 3.0
    return 0.0


def _act_label(act):
    """短标签: 卡片执行中显示「2/5 · 音乐 →90%」"""
    k = act.get("kind")
    try:
        if k == "mute":
            return "静音 " + "、".join(target_label("ch", int(c)) for c in
                                       (act.get("chs") or [act.get("ch", 1)]))
        if k == "mute_bus":
            return "静音 " + "、".join(target_label("bus", int(b)) for b in
                                       (act.get("buses") or [act.get("bus", 1)]))
        if k == "scene":
            if (act.get("mode") or "global") == "partial":
                snap = next((s for s in SNAPSHOTS
                             if s["id"] == act.get("presetId")), None)
                return "场景 %d · 局部（%s）" % (
                    int(act.get("scene", 1)),
                    ("预设「%s」" % snap.get("name")) if snap else "预设已删除")
            return "切场景 %d" % int(act.get("scene", 1))
        if k == "preset":
            snap = next((s for s in SNAPSHOTS if s["id"] == act.get("presetId")), None)
            return "调用预设「%s」" % (snap.get("name") if snap else "已删除")
        if k == "unmute_all":
            return "全部取消静音"
        if k == "wait":
            return "等待 %.0f 秒" % float(act.get("duration", 1.0))
        if k == "fade_all":
            return "全体推子→%.0f%%" % (float(act.get("to", 0)) * 100)
        if k == "fade_odd_even":
            return "奇偶过渡"
        if k == "fade_ch":
            ids_ = act.get("chs") or [act.get("ch", 1)]
            return "%s →%.0f%%" % ("、".join(target_label("ch", int(i)) for i in ids_),
                                   float(act.get("to", 0.8)) * 100)
        if k == "fade_bus":
            ids_ = act.get("buses") or [act.get("bus", 1)]
            return "%s →%.0f%%" % ("、".join(target_label("bus", int(i)) for i in ids_),
                                   float(act.get("to", 0.8)) * 100)
        if k == "fade_from":
            return "%s %.0f→%.0f%%" % (target_label("ch", int(act.get("ch", 1))),
                                       float(act.get("frm", 0)) * 100, float(act.get("to", 0.9)) * 100)
        if k == "fade_from_bus":
            return "%s %.0f→%.0f%%" % (target_label("bus", int(act.get("bus", 1))),
                                       float(act.get("frm", 0)) * 100, float(act.get("to", 0.9)) * 100)
        if k == "rel_db":
            grp = act.get("group", "ch")
            key = {"ch": "chs", "bus": "buses", "dca": "dcas"}.get(grp, "chs")
            ids_ = act.get(key) or [1]
            lbl = "、".join(target_label(grp, int(i)) for i in ids_)
            d = float(act.get("delta_db", 3.0))
            return "%s %s%.1f dB" % (lbl, "+" if d >= 0 else "−", abs(d))
        if k == "set":
            tg = act.get("target") or {}
            g = tg.get("group")
            p = tg.get("param", "fader")
            i = set_target_id(tg)
            if g == "scene":
                return "切场景 %d" % i
            if g == "fx":
                if p in ("type", "name"):
                    return "FX%d %s=%s" % (i, SET_PARAM_LABEL.get(p, p), act.get("value", ""))
                if p == "on":
                    return "FX%d %s" % (i, "开启" if act.get("value") else "旁通")
                if p == "mix":
                    return "FX%d 混合比→%.0f%%" % (i, float(act.get("value", 0)) * 100)
                return "FX%d %s→%.2f" % (i, SET_PARAM_LABEL.get(p, p),
                                         float(act.get("value", 0)))
            lbl = target_label(g, i)
            if g == "send":
                # 二维目标: 标签写成「通道→Bus5」, 否则日志里 512 个目标无法区分
                lbl = "%s→Bus%02d" % (lbl, send_bus_of(tg))
            if p == "on":
                return "%s %s" % (lbl, "开启" if act.get("value") else "静音")
            # 通道参数: 用登记表的标签/单位/档位显示 (曾经这里一律 "→%.0f%%",
            # 于是 trim 3.5 dB 在卡片进度条上显示成 "→4%")。
            # ⚠️ 只对**新增**参数生效: 推子/静音也在登记表里 (push=True),
            #    但它们有既有的百分比显示, 不能被这一支吃掉。
            kk = SET_KINDMAP.get(g, {}).get(p)
            sp = PARAM_SPECS.get(kk) if kk else None
            if sp is not None and not sp.push:
                # param_fmt 按 vtype 分型: 开关→开/关 (插入位置→PRE/POST),
                # 枚举→字面值, 浮点→带单位与符号
                return "%s %s=%s" % (lbl, sp.label, param_fmt(sp, act.get("value")))
            return "%s →%.0f%%" % (lbl, float(act.get("value", 0)) * 100)
        if k == "osc":
            return "原始 OSC %s" % act.get("address", "")
    except Exception:
        pass
    return str(k)


def _fade_targets_for(act):
    """渐变动作 → [(kind, idx, to_v)]; 非渐变返回 None。起点在触发瞬间取当前值。
    预设/局部场景也走这里：推子交给时间轴插值，避免阻塞主循环。"""
    k = act.get("kind")
    if k == "preset":
        return snap_fade_targets(find_snapshot(act.get("presetId"))) or []
    if k == "scene" and (act.get("mode") or "global") == "partial":
        return snap_fade_targets(find_snapshot(act.get("presetId"))) or []
    if k == "fade_all":
        to = float(act.get("to", 0.0))
        return ([("ch_fader", i, to) for i in range(1, 33)] +
                [("bus_fader", i, to) for i in range(1, 17)] +
                [("dca_fader", i, to) for i in range(1, 9)] +
                [(g + "_fader", i, to)
                 for g, n in (("auxin", 6), ("usb", 2), ("fxret", 8), ("mtx", 6))
                 for i in range(1, n + 1)] +
                [("main_fader", 0, to)])
    if k == "fade_odd_even":
        odd_to = float(act.get("odd_to", 0.8))
        even_to = float(act.get("even_to", 0.0))
        return ([("ch_fader", i, odd_to if i % 2 == 1 else even_to) for i in range(1, 33)])
    if k == "fade_ch":
        chs, _ = _filter_targets("ch_fader",
                                 [int(i) for i in (act.get("chs") or [act.get("ch", 1)])])
        return [("ch_fader", i, float(act.get("to", 0.8))) for i in chs]
    if k == "fade_bus":
        buses, _ = _filter_targets("bus_fader",
                                   [int(i) for i in (act.get("buses") or [act.get("bus", 1)])])
        return [("bus_fader", i, float(act.get("to", 0.8))) for i in buses]
    if k == "fade_from":
        ch, _ = _filter_targets("ch_fader", [int(act.get("ch", 1))])
        return [("ch_fader", ch[0], float(act.get("to", 0.9)))] if ch else []
    if k == "fade_from_bus":
        bus, _ = _filter_targets("bus_fader", [int(act.get("bus", 1))])
        return [("bus_fader", bus[0], float(act.get("to", 0.9)))] if bus else []
    if k == "rel_db":
        grp = act.get("group", "ch")
        # ⚠️ .get 而不是 []：group 若是白名单外的值（绕过了清洗的旧数据），
        #    [] 会 KeyError 把渐变线程炸掉；.get 返回 None 就走不了这条路。
        fk = {"ch": "ch_fader", "bus": "bus_fader", "dca": "dca_fader"}.get(grp)
        key = {"ch": "chs", "bus": "buses", "dca": "dcas"}.get(grp)
        if fk is None or key is None:
            return None
        delta = float(act.get("delta_db", 3.0))
        ids_, _ = _filter_targets(fk, [int(i) for i in (act.get(key) or [1])])
        out = []
        for i in ids_:
            cur_db = STATE.fader_to_db(get_value(fk, i))
            out.append((fk, i, db_to_fader(min(max(cur_db + delta, -90.0), 10.0))))
        return out
    if k == "set":
        tg = act.get("target") or {}
        g = tg.get("group")
        p = tg.get("param", "fader")
        if p != "fader":
            return None                  # 只有推子类能渐变, 其余落到瞬时路径
        i = set_target_id(tg)
        kind = resolve_set_target(g, p, i)
        if kind is None or not profile().addr(kind, i) or not target_exists(kind, i):
            return None                  # 组合不合法 / 控台不支持 / 本地无此目标 → 退化为瞬时
        try:
            to = float(act.get("value", 0.0) or 0.0)
        except (TypeError, ValueError):
            to = 0.0
        return [(kind, i, min(max(to, 0.0), 1.0))]
    return None


def _filter_targets(kind, ids_):
    """按当前控台/本地台面规模过滤目标, 返回 (放行的, 被跳过的)。

    保存期只做格式清洗（见 SAVE_MAX），所以这里可能收到超出当前台面范围的编号。
    处理原则与 §4 一致：**明确跳过并记日志**，而不是让 KeyError 把卡片线程炸掉。
    """
    done, skipped = [], []
    for i in ids_:
        if target_exists(kind, i):
            done.append(i)
        else:
            skipped.append(i)
    return done, skipped


def _skip_note(skipped, what):
    if not skipped:
        return ""
    return "（跳过 %s %s：当前控台没有这些路）" % (
        what, "/".join(str(x) for x in skipped))


def _gate_or_log(kind, idx, what):
    """控台门禁: 未标定控台 → 记一条日志并返回 True（调用方应跳过）。

    与 _exec_set 里那段是同一套原则（§4：让"不支持"变成**看得见的降级**）。
    曾经的遗漏：卡片里的 mute 动作在未标定控台下照样改本地 STATE、还打一句
    "SHOW 静音: 01、02" —— 与设置页承诺的"所有写入会被拒绝并记日志"不符。
    """
    p = profile()
    if p.ready and p.addr(kind, idx) is not None:
        return False
    log("SHOW 跳过%s %s #%d: 控台「%s」%s"
        % (what, kind, idx, p.label, "驱动待标定" if not p.ready else "不支持该目标"))
    return True


def _exec_instant(act):
    """瞬时动作: 静音 / 静音Bus / 切场景 / 全部取消静音 (卡片写入, 不做冲突检测)。"""
    k = act["kind"]
    if k == "mute":
        chs = [int(c) for c in (act.get("chs") or [act.get("ch", 1)])]
        ok, bad = _filter_targets("ch_on", chs)
        ok = [c for c in ok if not _gate_or_log("ch_on", c, "静音")]
        for c in ok:
            set_value("ch_on", c, 0, source="action")
        log("SHOW 静音: %s%s" % ("、".join(target_label("ch", c) for c in ok) or "(无可写目标)",
                                _skip_note(bad, "ch")))
    elif k == "mute_bus":
        buses = [int(b) for b in (act.get("buses") or [act.get("bus", 1)])]
        ok, bad = _filter_targets("bus_on", buses)
        ok = [b for b in ok if not _gate_or_log("bus_on", b, "静音")]
        for b in ok:
            set_value("bus_on", b, 0, source="action")
        log("SHOW 静音: %s%s" % ("、".join(target_label("bus", b) for b in ok) or "(无可写目标)",
                                _skip_note(bad, "bus")))
    elif k == "scene":
        # 全局 = 整场 recall（模拟器里就是切场景号，真台发 /scene/N/load）;
        # 局部 = **不发场景号**，只把预设范围内的参数应用上去 —— 真台 OSC
        # 没有"只 recall 一部分"的地址，选择性只能由客户端做。
        mode = act.get("mode") or "global"
        if mode == "partial":
            snap = find_snapshot(act.get("presetId"))
            if not snap:
                # 绝不能退化成全量 recall：那会让"局部"变成"整台被换掉"
                log("SHOW 场景 %d 局部调用失败: 找不到预设 #%s（已跳过，不做全量）"
                    % (int(act.get("scene", 1)), act.get("presetId")))
                return
            _recall_instant(snap)      # 推子由时间轴渐变分支负责
            log("SHOW 场景 %d 局部: 预设「%s」立即项已应用，推子 %.1f 秒归位（其余通道不动）"
                % (int(act.get("scene", 1)), snap.get("name", ""),
                   float(act.get("duration", 1.0) or 0.0)))
            return
        _n = int(act.get("scene", 1))
        with STATE.lock:
            STATE.scene = _n
        # 真台召回：地址由 profile 给（X32 一条 /scene/N/load；WING 两段式）。
        # 以前这里只改本地状态，"真台发 /scene/N/load" 只写在注释里 ——
        # 桥接模式下点切场景，网页变了、台面不动、日志干净。
        _fwd = bridge_scene(_n)
        log("SHOW 切换到场景 %d（全局 recall）%s"
            % (_n, "，已发往真台" if _fwd else "，未桥接（仅本地）"))
    elif k == "preset":
        snap = find_snapshot(act.get("presetId"))
        if not snap:
            log("SHOW 调用预设失败: 找不到 #%s（已跳过）" % act.get("presetId"))
            return
        _recall_instant(snap)
        log("SHOW 调用预设「%s」立即项已应用，推子 %.1f 秒归位"
            % (snap.get("name", ""), float(act.get("duration", 2.0) or 0.0)))
    elif k == "unmute_all":
        for i in range(1, 33):
            set_value("ch_on", i, 1, source="action")
        for i in range(1, 17):
            set_value("bus_on", i, 1, source="action")
        for i in range(1, 9):
            set_value("dca_on", i, 1, source="action")
        for g, n in (("auxin", 6), ("usb", 2), ("fxret", 8), ("mtx", 6)):
            for i in range(1, n + 1):
                set_value(g + "_on", i, 1, source="action")
        set_value("main_on", 0, 1, source="action")
        log("SHOW 全部取消静音")
    elif k == "set":
        _exec_set(act)
    elif k == "osc":
        _exec_osc(act)


def _apply_fade(fade, ratio):
    for k, i, a, b in fade["starts"]:
        if _interrupted(k, i):
            continue
        # source="fade": 渐变插值。与 action 分开是为了桥接侧的"接管拦截"——
        # 接管后积压的插值必须丢弃, 而显式动作 (set/mute/回归) 不受接管影响。
        set_value(k, i, a + (b - a) * ratio, source="fade")


def _clean_set_action(a, num, why=None):
    """校验通用动作。group/param 必须在白名单内，id 按当前控台规模钳制。"""
    tg = a.get("target")
    if not isinstance(tg, dict):
        if why is not None: why.append("通用设置缺 target")
        return None
    group = tg.get("group")
    if group not in SET_GROUPS:
        if why is not None: why.append("通用设置的组「%s」不在白名单" % group)
        return None
    # scene 的 param 是 "load"（切场景没有"值"的概念），其余默认 "fader"
    param = tg.get("param") or ("load" if group == "scene" else "fader")
    if param not in SET_PARAMS.get(group, ()):
        if why is not None:
            why.append("「%s」不支持参数「%s」" % (group, param))
        return None
    try:
        idx = int(float(tg.get("id", 1)))
    except (TypeError, ValueError):
        idx = 1
    if group == "main":
        idx = 0
    elif group == "scene":
        idx = min(max(idx, 1), 99)
    else:
        # 只按"格式上限"钳（见 SAVE_MAX 的说明）：范围对不对由执行期的
        # target_exists 判断，超了就跳过并记日志 —— 让降级看得见。
        cap = SAVE_MAX.get(group, 64)
        idx = min(max(idx, 1), max(1, cap))

    out = {"kind": "set", "target": {"group": group, "param": param, "id": idx}}
    if group == "send":
        # 发送: target 多带一个 bus(1..16)。存的时候不打包 —— 打包是执行期的事,
        # 卡片里留 (id=通道, bus=Bus) 才看得懂, 换控台也不会错位。
        out["target"]["bus"] = send_bus_of(tg)
    if group == "fx" and param == "type":
        out["value"] = str(a.get("value", ""))[:8].upper()
    elif group == "fx" and param == "name":
        out["value"] = str(a.get("value", ""))[:12]
    elif param == "on":
        out["value"] = 1 if num("value", 0.0, 0.0, 1.0) >= 0.5 else 0
    elif param == "fader":
        out["value"] = num("value", 0.0, 0.0, 1.0)
    elif group == "fx":
        # 混响时间/预延迟/阻尼吃**原生单位**（秒/毫秒），范围交给 fx_par_clamp 按算法钳制
        out["value"] = num("value", 0.0, -1000.0, 20000.0)
    else:
        # 通道参数 (增益/反相/延时/低切/插入/门/动态/EQ) 与发送参数:
        # 按登记表的量程与档位清洗。
        # ⚠️ 不能沿用上面 fader 的 [0,1] 钳制 —— trim 的量程是 -18..18 dB,
        #    硬钳成 0..1 会让"存 3.5 变成 1"（保存时静默改值，最难查的那类）。
        #    存进去的就是执行时将要应用的值（param_coerce 是幂等的）。
        # 用 SET_KINDMAP 解析 kind: 通道参数是 "<group>_<field>", 发送是同名,
        # 光靠字符串拼会在发送上得到 "send_send_level" 这种不存在的 kind。
        kind = SET_KINDMAP.get(group, {}).get(param)
        sp = PARAM_SPECS.get(kind) if kind else None
        if sp is not None:
            out["value"] = param_coerce(sp.kind, a.get("value", sp.default))
        else:
            out["value"] = num("value", 0.0, 0.0, 1.0)
    if a.get("duration") is not None:
        out["duration"] = num("duration", 0.0, 0.0, 60.0)
    if a.get("at") is not None:
        out["at"] = num("at", 0.0, 0.0, 600.0)
    return out


def _clean_osc_action(a, num, why=None):
    """校验原始 OSC 动作。

    ⚠️ 这个动作是**控台专有**的：地址写死，换控台后可能指向别的参数（甚至无效）。
    这里只做防呆（地址格式、参数个数与类型），**不做语义校验** —— 地址对不对只有
    用户自己知道。这正是它必须以独立动作类型出现、并带醒目提示的原因。
    """
    addr = str(a.get("address", "")).strip()
    if not addr.startswith("/") or len(addr) > 128 or " " in addr:
        if why is not None:
            why.append("osc 地址必须形如 /ch/01/mix/fader（不能有空格）")
        return None
    args = a.get("args")
    if not isinstance(args, list):
        args = [] if a.get("value") is None else [a.get("value")]
    clean = []
    for v in args[:8]:
        if isinstance(v, bool):
            clean.append(1 if v else 0)
        elif isinstance(v, (int, float)):
            clean.append(float(v))
        elif isinstance(v, str):
            clean.append(v[:64])
        else:
            if why is not None:
                why.append("osc 参数只能是数字或字符串")
            return None
    out = {"kind": "osc", "address": addr}
    if clean:
        out["args"] = clean
    if a.get("at") is not None:
        out["at"] = num("at", 0.0, 0.0, 600.0)
    return out


def _clean_action(a, why=None):
    """校验网页提交的动作, 只放行白名单类型与合法数值。

    why 是**可选的丢弃原因收集列表**：给了它，每条被拒的动作都会往里追加一句
    人话（如 "不存在的动作" / "osc 地址必须以 / 开头"）。调用方把它透给前端，
    用户才知道"保存成功但少了东西"—— 这正是 /api/cardedit 曾经的静默丢动作。
    """
    def _reject(msg):
        if why is not None:
            why.append(msg)
        return None

    if not isinstance(a, dict):
        return _reject("不是合法的动作对象")
    k = a.get("kind")
    if k not in ("mute", "mute_bus", "scene", "unmute_all", "wait",
                 "fade_all", "fade_odd_even", "fade_ch", "fade_bus",
                 "fade_from", "fade_from_bus", "rel_db", "set", "osc",
                 "preset"):
        return _reject("不支持的动作类型「%s」" % (k if isinstance(k, str) else k))

    def num(key, default, lo, hi):
        # ⚠️ 必须过 _finite：NaN 会穿透 min/max（见 _finite 的说明），
        #    顺着 snapshot 的 json.dumps 变成字面量 NaN → 前端 JSON.parse 崩
        v = _finite(a.get(key, default), float(default))
        return min(max(v, lo), hi)

    def ids(key_single, key_list, lo, hi):
        """目标列表: 接受单值(旧格式)或数组(多选), 去重排序, 钳制范围。"""
        raw = a.get(key_list)
        if not isinstance(raw, list):
            raw = [a.get(key_single)]
        out_ids = []
        for v in raw:
            try:
                n = int(float(v))
            except (TypeError, ValueError):
                continue
            n = min(max(n, lo), hi)
            if n not in out_ids:
                out_ids.append(n)
        return sorted(out_ids) or [lo]

    curve = a.get("curve") if a.get("curve") in CURVES else "linear"
    out = {"kind": k}
    if k == "set":
        return _clean_set_action(a, num, why)
    if k == "osc":
        return _clean_osc_action(a, num, why)
    if k == "mute":
        out["chs"] = ids("ch", "chs", 1, SAVE_MAX["ch"])
    elif k == "mute_bus":
        out["buses"] = ids("bus", "buses", 1, SAVE_MAX["bus"])
    elif k == "scene":
        out["scene"] = int(num("scene", 1, 1, 99))
        mode = a.get("mode") if a.get("mode") in ("global", "partial") else "global"
        out["mode"] = mode
        if mode == "partial":
            # 局部调用必须挂一条预设：范围从预设来，找不到就明确拒绝，
            # 不能"当作全局"静默执行（那种假成功最难查）
            pid = int(num("presetId", 0, 0, 9999))
            if pid <= 0:
                return _reject("「局部调用场景」需要先选一个预设")
            out["presetId"] = pid
            out["duration"] = num("duration", 1.0, 0.05, 30.0)
            out["curve"] = curve
    elif k == "preset":
        pid = int(num("presetId", 0, 0, 9999))
        if pid <= 0:
            return _reject("「调用预设」缺少预设编号")
        out["presetId"] = pid
        out["duration"] = num("duration", 2.0, 0.5, 15.0)
        out["curve"] = curve
    elif k == "wait":
        out["duration"] = num("duration", 1.0, 0.5, 60.0)
    elif k == "fade_all":
        out.update(to=num("to", 0.0, 0.0, 1.0),
                   duration=num("duration", 3.0, 0.5, 30.0), curve=curve)
    elif k == "fade_odd_even":
        out.update(odd_to=num("odd_to", 0.8, 0.0, 1.0),
                   even_to=num("even_to", 0.0, 0.0, 1.0),
                   duration=num("duration", 4.0, 0.5, 30.0), curve=curve)
    elif k == "fade_ch":
        out.update(chs=ids("ch", "chs", 1, SAVE_MAX["ch"]),
                   to=num("to", 0.8, 0.0, 1.0),
                   duration=num("duration", 3.0, 0.5, 30.0), curve=curve)
    elif k == "fade_bus":
        out.update(buses=ids("bus", "buses", 1, SAVE_MAX["bus"]),
                   to=num("to", 0.8, 0.0, 1.0),
                   duration=num("duration", 3.0, 0.5, 30.0), curve=curve)
    elif k in ("fade_from", "fade_from_bus"):
        out.update(ch=int(num("ch", 1, 1, SAVE_MAX["ch"])) if k == "fade_from"
                   else int(num("bus", 1, 1, SAVE_MAX["bus"])),
                   frm=num("frm", 0.0, 0.0, 1.0),
                   to=num("to", 0.9, 0.0, 1.0),
                   duration=num("duration", 5.0, 0.5, 30.0), curve=curve)
    elif k == "rel_db":
        # 相对增减 dB: 执行瞬间从当前推子位置换算 (+3dB 在高低端手感一致)
        grp = a.get("group") if a.get("group") in ("ch", "bus", "dca") else "ch"
        cap = SAVE_MAX[grp]
        key = {"ch": "chs", "bus": "buses", "dca": "dcas"}[grp]
        out_ids = ids(grp, key, 1, cap)
        out.update(group=grp, **{key: out_ids},
                   delta_db=num("delta_db", 3.0, -30.0, 30.0),
                   duration=num("duration", 2.0, 0.5, 30.0), curve=curve)
    if a.get("at") is not None:
        # 时间轴偏移(秒): 给了 at 的动作并行执行, 缺省仍按顺序排布
        out["at"] = num("at", 0.0, 0.0, 600.0)
    return out


def _clean_actions(items, limit=64):
    """批量清洗动作, 返回 (放行的动作, 被丢的原因列表)。

    ⚠️ 为什么要把"丢的原因"返回去：/api/cardedit 曾经的写法是
        `if isinstance(actions, list) and actions:` + `if actions:` 两道闸 ——
        用户提交 2 个动作（1 合法 1 非法）会拿到 {"ok":true}，实际只存 1 个；
        提交空数组想清空，同样 {"ok":true} 而一个没少。**假成功比报错更难查**。
        现在丢弃明细一路透到前端 toast，用户立刻知道少了什么、为什么。
    """
    if not isinstance(items, list):
        return None, ["actions 不是数组"]
    if len(items) > limit:
        return None, ["动作超过 %d 条上限" % limit]
    why, out = [], []
    for i, a in enumerate(items):
        c = _clean_action(a, why)
        if c:
            out.append(c)
        else:
            why[-1] = "第 %d 个动作: %s" % (i + 1, why[-1]) if why else "第 %d 个动作被丢弃" % (i + 1)
    return out, why


