# ==== x32sim/quickkeys.py
# ==================================================================
# -*- coding: utf-8 -*-
"""x32sim/quickkeys — 自定义控制键 (步进 + 电动推子渐变)"""

import threading
import time



# ------------------------------------------------------------ 自定义控制键
# 歌手实时微调场景: 「耳返增大/减小」等大按钮,按步长(1.5/3/6 dB)调整,可带渐变
KEY_CFG = {"step_db": 3.0, "ramp": 0.4}   # ramp 秒:渐变速度,0=瞬间
QUICK_KEYS = [
    {"id": "iem_up",  "name": "耳返 增大", "icon": "🎧➕", "kind": "bus_fader", "idx": 15, "sign": +1},
    {"id": "iem_dn",  "name": "耳返 减小", "icon": "🎧➖", "kind": "bus_fader", "idx": 15, "sign": -1},
    {"id": "main_up", "name": "主输出 增大", "icon": "🔊➕", "kind": "main_fader", "idx": 0, "sign": +1},
    {"id": "main_dn", "name": "主输出 减小", "icon": "🔉➖", "kind": "main_fader", "idx": 0, "sign": -1},
    {"id": "dca1_up", "name": "乐器组 增大", "icon": "🎸➕", "kind": "dca_fader", "idx": 1, "sign": +1},
    {"id": "dca1_dn", "name": "乐器组 减小", "icon": "🎸➖", "kind": "dca_fader", "idx": 1, "sign": -1},
]
RAMP_STOP = threading.Event()   # 新的推子运动打断上一次


def ramp_to(kind, idx, target, seconds, curve="smooth"):
    """推子平滑运动到目标位置(电动推子),可被下一次运动打断。"""
    RAMP_STOP.set()

    def worker():
        RAMP_STOP.clear()
        start = get_value(kind, idx)
        steps = max(1, int(seconds / 0.05))
        try:
            for s in range(1, steps + 1):
                if RAMP_STOP.is_set():
                    return
                time.sleep(seconds / steps)
                ratio = curve_ratio(s / steps, curve)
                set_value(kind, idx, start + (target - start) * ratio)
        finally:
            if not RAMP_STOP.is_set():
                set_value(kind, idx, target)
    threading.Thread(target=worker, daemon=True).start()


# 控制键允许的 kind（与 /api/keyadd、/api/import 的 kindmap 保持一致）
QUICK_KEY_KINDS = {"ch_fader", "bus_fader", "dca_fader", "main_fader",
                   "auxin_fader", "usb_fader", "fxret_fader", "mtx_fader"}


def apply_key(key_id):
    key = next((k for k in QUICK_KEYS if k["id"] == key_id), None)
    if not key:
        return None
    step = float(KEY_CFG["step_db"])
    ramp = float(KEY_CFG["ramp"])
    cur_db = STATE.fader_to_db(get_value(key["kind"], key["idx"]))
    new_db = min(max(cur_db + key["sign"] * step, -90.0), 10.0)
    target = db_to_fader(new_db)
    if ramp > 0.01:
        ramp_to(key["kind"], key["idx"], target, ramp)
    else:
        set_value(key["kind"], key["idx"], target)
    log("KEY %s: %.1f dB → %.1f dB (%s)" %
        (key["name"], cur_db, new_db, "渐变 %.1f 秒" % ramp if ramp > 0.01 else "瞬间"))
    return {"id": key_id, "from_db": cur_db, "to_db": new_db}


# ==================================================================
# ==== x32sim/rider.py
# ==================================================================
# -*- coding: utf-8 -*-
"""自动增益 / 自动推子（Vocal Rider 式）。

控制目标：把选定通道的**电平**稳在设定的目标值（默认 -18 dBFS）。

控制律是"负反馈 + 三重平滑"，缺一条都会听起来像在抽气：

  1. **平均**：先把电平做线性功率的指数平均（窗口随速度 0.9 / 0.35 / 0.12 s）。
     直接用电平瞬时值 → 每个字都改一次推子，人耳听到的是颤动。
  2. **死区**：误差小于 0.6 / 0.4 / 0.3 dB 就不动。目标附近来回修正没有意义，
     只会让电动推子不停地"呼吸"。
  3. **速率**：每秒最多 1.5 / 5 / 15 dB。再大的偏差也慢慢爬过去，
     不会一帧从 -40 拉到 0（那一下就是明显的音量台阶）。

执行器二选一（`mode`）：
  - `fader` → `ch_fader`（推子，真台是电动推子，能看见它在动）
  - `gain`  → `ch_trim` （数字增益/前置放大，推子不动）

两者都走 `set_value(..., source="auto")` 这条既有写入管道，桥接模式下会真实下发给台子，
和卡片/手动操作共用同一个出口与限速。

安全边界（都是踩过或能想到的坑）：
  - **静音/无信号**（≤ -80 dB）冻结：绝不把静音往上推成噪声
  - **卡片正在渐变该通道**时让位（FADE_ZONE），不跟时间轴抢
  - **检测到不是自己写的改动**（有人手动拖了推子/拧了增益）→ 暂停 2 秒，
    让人优先；之后从新位置继续
  - **量程**默认 ±12 dB，到顶停手；推子到 0/1 两端也不硬顶
"""
import math
import threading
import time


# 三档速度：窗口（平均）/ 死区 / 每秒最大修正
SPEEDS = {
    "slow":   {"window": 0.90, "deadband": 0.60, "rate": 1.5},
    "medium": {"window": 0.35, "deadband": 0.40, "rate": 5.0},
    "fast":   {"window": 0.12, "deadband": 0.30, "rate": 15.0},
}
SPEED_LABELS = {"slow": "慢（平稳）", "medium": "中（默认）", "fast": "快（贴合）"}
MODES = ("fader", "gain")
TICK = 0.05                 # 20 Hz：比电平表推送快，足够跟上"快"档
SILENCE_DB = -80.0          # 低于此视为无信号（静音是 -32768）
MANUAL_PAUSE = 2.0          # 检测到人工干预后让位多久
MANUAL_EPS = 0.25           # 与上次写入相差多少 dB 判定为"别人动的"
MAX_CH = 32

# 配置（持久化到 user_config.json 的 "rider" 键）
RIDER = {"enabled": True, "ch": {}}
RIDER_LOCK = threading.Lock()
# 运行时（不落盘）：每通道的平滑状态与上次写入值
RIDER_RT = {}


def default_cfg():
    return {"on": False, "target": -18.0, "mode": "fader", "speed": "medium", "range": 12.0,
            # 表源: post = 推子后(默认, 与界面电平表同源); pre = 推子前(推子动不影响测量)
            "tap": "post",
            # 侧链: 0 = 用本通道电平; 1-32 = 用那一路的电平来判断, 但仍修正本通道
            "sidechain": 0,
            # 目标曲线: None = 固定目标; {"loop": 秒(0=不循环), "points": [[t, dB], ...]}
            "curve": None}


def _num(v, lo, hi, default):
    """配置值消毒：非数字/NaN 一律回默认，再钳到量程。"""
    try:
        f = float(v)
    except (TypeError, ValueError):
        return default
    if not math.isfinite(f):
        return default
    return max(lo, min(hi, f))


def _clean_curve(raw):
    """把界面传来的曲线消毒成 {"loop": 秒, "points": [[t, dB], ...]}；非法返回 None。"""
    if raw in (None, "", [], {}):
        return None
    if not isinstance(raw, dict):
        return None
    pts = raw.get("points")
    if not isinstance(pts, list) or len(pts) < 2:
        return None
    clean = []
    for pt in pts[:32]:
        try:
            t = float(pt[0])
            db = float(pt[1])
        except (TypeError, ValueError, IndexError):
            continue
        if not (math.isfinite(t) and math.isfinite(db)):
            continue
        clean.append([round(max(0.0, min(3600.0, t)), 2), round(max(-60.0, min(0.0, db)), 1)])
    clean.sort(key=lambda x: x[0])
    # 同一时刻只留一个（后者覆盖）
    dedup = []
    for t, db in clean:
        if dedup and abs(dedup[-1][0] - t) < 0.01:
            dedup[-1][1] = db
        else:
            dedup.append([t, db])
    if len(dedup) < 2:
        return None
    try:
        loop = float(raw.get("loop") or 0.0)
    except (TypeError, ValueError):
        loop = 0.0
    loop = max(0.0, min(3600.0, loop)) if math.isfinite(loop) else 0.0
    if 0 < loop < dedup[-1][0]:
        loop = dedup[-1][0]          # 循环长度不能短于最后一个点
    return {"loop": round(loop, 2), "points": dedup}


def target_at(curve, elapsed, fallback):
    """曲线在 elapsed 秒处的目标电平（线性插值，两端钳住，可循环）。"""
    if not curve:
        return fallback
    pts = curve.get("points") or []
    if len(pts) < 2:
        return fallback
    loop = float(curve.get("loop") or 0)
    t = max(0.0, elapsed if elapsed == elapsed else 0.0)
    if loop > 0:
        t = math.fmod(t, loop)
    if t <= pts[0][0]:
        return pts[0][1]
    if t >= pts[-1][0]:
        return pts[-1][1]
    for k in range(1, len(pts)):
        t0, v0 = pts[k - 1]
        t1, v1 = pts[k]
        if t <= t1:
            if t1 <= t0:
                return v1
            return v0 + (v1 - v0) * (t - t0) / (t1 - t0)
    return pts[-1][1]


def measure(ch, cfg, levels, now=None):
    """本拍用于判断的电平：侧链优先；tap=pre 用推子前(信号+增益)，post 用推子后(电平表)。"""
    try:
        src = int(cfg.get("sidechain") or 0)
    except (TypeError, ValueError):
        src = 0
    if not (1 <= src <= MAX_CH):
        src = ch
    if cfg.get("tap") == "pre":
        try:
            trim = float((STATE.ch[src] or {}).get("trim") or 0.0)
        except Exception:
            trim = 0.0
        return source_level_db(src, now) + trim
    try:
        return levels[src - 1]
    except (IndexError, TypeError, KeyError):
        return None


def _rt(key):
    rt = RIDER_RT.get(key)
    if rt is None:
        rt = {"rms": 0.0, "avg": None, "applied": None, "written": None,
              "pause_until": 0.0, "writes": 0, "base": None}
        RIDER_RT[key] = rt
    return rt


def reset_channel(key):
    """清掉某通道的平滑状态（重新开骑时从当前电平重新起算，量程基准也重取）。"""
    RIDER_RT.pop(key, None)


def rider_reset_all():
    RIDER_RT.clear()


# ---------------------------------------------------------------- 核心：单通道一拍
def tick_channel(i, cfg, rt, level_db, dt, now=None):
    """按一拍电平均值推进一次。返回写入的 dB 值；没写入返回 None。

    纯逻辑、无睡眠、无全局副作用（除了 set_value 落库），测试可以直接调它。
    """
    if now is None:
        now = time.time()
    if not cfg.get("on"):
        rt["avg"] = None
        rt["rms"] = 0.0
        return None
    if level_db is None or level_db <= SILENCE_DB or not math.isfinite(level_db):
        # 无信号：冻结，并清掉平均值 —— 否则恢复出声瞬间会用旧的平均值猛拉一下
        rt["avg"] = None
        rt["rms"] = 0.0
        return None

    sp = SPEEDS.get(cfg.get("speed"), SPEEDS["medium"])
    dt = max(0.005, min(0.5, dt))

    # ① 平均：线性功率的指数滑动平均（比直接平均 dB 更接近听感上的能量）
    power = 10.0 ** (level_db / 10.0)
    if rt["rms"] <= 0.0:
        rt["rms"] = power                      # 首拍直接取当前值，不从 0 慢慢爬
    else:
        alpha = 1.0 - math.exp(-dt / sp["window"])
        rt["rms"] += alpha * (power - rt["rms"])
    avg_db = 10.0 * math.log10(max(rt["rms"], 1e-12))
    rt["avg"] = round(avg_db, 2)

    # 目标: 配了曲线就按曲线走（以本次启用为 0 时刻，可循环），否则用固定目标
    if rt.get("start") is None:
        rt["start"] = now
    target = target_at(cfg.get("curve"), now - rt["start"], cfg["target"])
    rt["target"] = round(target, 2)
    rng = cfg["range"]
    err = max(-rng, min(rng, target - avg_db))

    # ② 死区：够近就别动
    if abs(err) < sp["deadband"]:
        return None

    actor = "ch_fader" if cfg["mode"] == "fader" else "ch_trim"
    cur = get_value(actor, i)
    if cur is None:
        return None
    cur_db = STATE.fader_to_db(cur) if actor == "ch_fader" else float(cur)

    # ③ 人工干预检测：当前值与"上次自己写的"差得多 → 一定是别人动的
    wrote = rt.get("written")
    if wrote is not None and abs(cur_db - wrote) > MANUAL_EPS:
        rt["pause_until"] = now + MANUAL_PAUSE
        rt["written"] = cur_db
        rt["base"] = cur_db              # 量程基准跟到人的新位置
        log("RIDER CH%02d 检测到人工干预，让位 %.1fs" % (i, MANUAL_PAUSE))
        return None
    if now < rt.get("pause_until", 0.0):
        rt["written"] = cur_db
        return None

    # 卡片正在渐变这一路 → 让位（否则两边互相拉扯）
    with FADE_LOCK:
        if (actor, i) in FADE_ZONE:
            return None

    # ④ 速率限制：每拍最多走 rate*dt 个 dB
    step = max(-sp["rate"] * dt, min(sp["rate"] * dt, err))
    # 量程按"启用时的位置"为基准累计，而不是限制单拍误差 ——
    # 否则范围形同虚设：每拍都从新位置重新算 12 dB，推子能一路爬到 +10。
    if rt.get("base") is None:
        rt["base"] = cur_db
    lo, hi = rt["base"] - rng, rt["base"] + rng
    want_db = max(lo, min(hi, cur_db + step))
    if abs(want_db - cur_db) < 1e-4:                 # 已到量程边界
        rt["written"] = cur_db
        rt["applied"] = cur_db
        return None
    if actor == "ch_fader":
        want_val = db_to_fader(want_db)
        if want_val <= 0.0 or want_val >= 1.0:      # 顶到两端就不硬推
            rt["written"] = cur_db
            rt["applied"] = cur_db
            return None
    else:
        want_val = want_db
        if abs(want_val) > 18.0:                     # 数字增益默认量程
            rt["written"] = cur_db
            rt["applied"] = cur_db
            return None

    set_value(actor, i, want_val, source="auto")
    got = get_value(actor, i)
    got_db = (STATE.fader_to_db(got) if actor == "ch_fader" else float(got)) if got is not None else want_db
    rt["written"] = got_db
    rt["applied"] = round(got_db, 2)
    rt["writes"] += 1
    return got_db


# ---------------------------------------------------------------- 线程
def rider_loop():
    """每 50 ms 一拍。电平取 /api/meters 同一份数据（推子后），执行器写回同一条管道。"""
    last = time.time()
    while True:
        time.sleep(TICK)
        now = time.time()
        dt = now - last
        last = now
        if not RIDER["enabled"]:
            continue
        try:
            levels = compute_levels()
            with RIDER_LOCK:
                items = [(k, dict(v)) for k, v in RIDER["ch"].items()]
            for key, cfg in items:
                if not cfg.get("on"):
                    continue
                i = int(key)
                if not (1 <= i <= MAX_CH):
                    continue
                tick_channel(i, cfg, _rt(key), measure(i, cfg, levels, now), dt, now)
        except Exception as e:              # 控制器绝不能把主进程带崩
            log("RIDER 循环异常: %r" % e)
            time.sleep(0.5)


# ---------------------------------------------------------------- 配置读写 / HTTP
def rider_config():
    """给界面看的全量配置 + 实时值。"""
    with RIDER_LOCK:
        chans = {}
        for k, cfg in sorted(RIDER["ch"].items(), key=lambda kv: int(kv[0])):
            rt = RIDER_RT.get(k, {})
            chans[k] = dict(cfg)
            chans[k].update({
                "level": rt.get("avg"),
                "applied": rt.get("applied"),
                "target_now": rt.get("target", cfg["target"]),
                "paused": time.time() < rt.get("pause_until", 0.0),
                "writes": rt.get("writes", 0),
            })
    return {"enabled": RIDER["enabled"], "speeds": SPEEDS, "modes": list(MODES),
            "channels": chans}


def rider_snapshot():
    """给 /api/state 的紧凑快照：只带启用的通道（不把 32 路塞进状态包）。"""
    out = []
    with RIDER_LOCK:
        for k, cfg in sorted(RIDER["ch"].items(), key=lambda kv: int(kv[0])):
            if not cfg.get("on"):
                continue
            rt = RIDER_RT.get(k, {})
            out.append({"ch": int(k), "target": rt.get("target", cfg["target"]),
                        "mode": cfg["mode"], "speed": cfg["speed"],
                        "tap": cfg.get("tap", "post"), "sidechain": cfg.get("sidechain", 0),
                        "level": rt.get("avg"), "applied": rt.get("applied"),
                        "curve": bool(cfg.get("curve")),
                        "paused": time.time() < rt.get("pause_until", 0.0)})
    return {"enabled": RIDER["enabled"], "on": out}


def rider_set(data):
    """处理 POST /api/rider。

    支持三种写法：
      {"channel": 3, "on": true, "target": -18, "mode": "fader", "speed": "fast"}
      {"channel": "all", "on": false}          # 批量
      {"action": "reset"}                      # 清平滑状态（重新起算）
    """
    if not isinstance(data, dict):
        raise ValueError("body 必须是对象")
    if "enabled" in data:
        RIDER["enabled"] = bool(data["enabled"])

    action = data.get("action")
    if action == "reset":
        rider_reset_all()
        return rider_config()

    if data.get("remove"):
        try:
            i = int(data.get("channel"))
        except (TypeError, ValueError):
            raise ValueError("channel 必须是 1-32")
        with RIDER_LOCK:
            RIDER["ch"].pop(str(i), None)
        reset_channel(str(i))
        return rider_config()

    patch_keys = ("on", "target", "mode", "speed", "range", "tap", "sidechain", "curve")
    if not any(k in data for k in patch_keys) and "channel" not in data:
        return rider_config()

    ch = data.get("channel")
    with RIDER_LOCK:
        if ch == "all":
            keys = list(RIDER["ch"])
        elif ch is None:
            raise ValueError("缺少 channel（1-32 或 \"all\"）")
        else:
            try:
                i = int(ch)
            except (TypeError, ValueError):
                raise ValueError("channel 必须是 1-32")
            if not (1 <= i <= MAX_CH):
                raise ValueError("channel 超出 1-32")
            cfg = RIDER["ch"].setdefault(str(i), default_cfg())
            keys = [str(i)]

        for key in keys:
            cfg = RIDER["ch"].setdefault(key, default_cfg())
            was_on = cfg.get("on")
            if "on" in data:
                cfg["on"] = bool(data["on"])
            if "target" in data:
                cfg["target"] = round(_num(data["target"], -60.0, 0.0, cfg["target"]), 1)
            if "mode" in data:
                if data["mode"] not in MODES:
                    raise ValueError("mode 只能是 fader / gain")
                cfg["mode"] = data["mode"]
            if "speed" in data:
                if data["speed"] not in SPEEDS:
                    raise ValueError("speed 只能是 slow / medium / fast")
                cfg["speed"] = data["speed"]
            if "range" in data:
                cfg["range"] = round(_num(data["range"], 3.0, 24.0, cfg["range"]), 1)
            if "tap" in data:
                if data["tap"] not in ("pre", "post"):
                    raise ValueError("tap 只能是 pre / post")
                cfg["tap"] = data["tap"]
            if "sidechain" in data:
                try:
                    sc = int(data["sidechain"] or 0)
                except (TypeError, ValueError):
                    raise ValueError("sidechain 必须是 0-32")
                if not (0 <= sc <= MAX_CH):
                    raise ValueError("sidechain 必须是 0-32")
                cfg["sidechain"] = sc
            if "curve" in data:
                cfg["curve"] = _clean_curve(data["curve"])
            if cfg.get("on") and not was_on:
                reset_channel(key)          # 重新开骑：从当前电平重新起算
            if not cfg.get("on"):
                reset_channel(key)
    return rider_config()


def rider_dump():
    """落盘用：只存配置（平滑状态是运行时量）。"""
    with RIDER_LOCK:
        return {"enabled": RIDER["enabled"],
                "ch": {k: dict(v) for k, v in RIDER["ch"].items()}}


def rider_load(d):
    """从配置文件恢复；坏条目逐条丢弃，不因一条脏数据让整个配置读不进来。"""
    if not isinstance(d, dict):
        return
    RIDER["enabled"] = bool(d.get("enabled", True))
    ch = d.get("ch")
    if not isinstance(ch, dict):
        return
    clean = {}
    for k, v in ch.items():
        try:
            i = int(k)
        except (TypeError, ValueError):
            continue
        if not (1 <= i <= MAX_CH) or not isinstance(v, dict):
            continue
        cfg = default_cfg()
        cfg["on"] = bool(v.get("on"))
        cfg["target"] = round(_num(v.get("target"), -60.0, 0.0, cfg["target"]), 1)
        if v.get("mode") in MODES:
            cfg["mode"] = v["mode"]
        if v.get("speed") in SPEEDS:
            cfg["speed"] = v["speed"]
        cfg["range"] = round(_num(v.get("range"), 3.0, 24.0, cfg["range"]), 1)
        if v.get("tap") in ("pre", "post"):
            cfg["tap"] = v["tap"]
        try:
            sc = int(v.get("sidechain") or 0)
            if 0 <= sc <= MAX_CH:
                cfg["sidechain"] = sc
        except (TypeError, ValueError):
            pass
        cfg["curve"] = _clean_curve(v.get("curve"))
        clean[str(i)] = cfg
    RIDER["ch"] = clean


# ==================================================================
# ==== x32sim/timeline.py
# ==================================================================
# -*- coding: utf-8 -*-
"""x32sim/timeline — 时间轴调度器 + ShowRun (代际化) + 定时 + 冲突事件"""

import math
import threading
import time



SHOW_STATE = {"running": None, "name": "", "progress": 0.0, "step": ""}

# 卡片运行控制: 每次启动都是一个独立"代"(gen) + 专属停止事件 + 卡片 id。
# ⚠️ 曾经用过一个全局 Event (SHOW_STOP): 新 worker 开头 clear() 会把"停止旧卡片"
#    刚 set 的信号吃掉 → 连点两次出两个 worker 同时驱动同一张卡; 停止 A 再开 B,
#    A 收不到停止信号继续把通道推往 A 的目标。现在停止信号按代发放, 旧 worker
#    只认自己那个 Event, 物理上不可能被新运行清掉; 共享状态(SHOW_STATE)的清理
#    也带 gen 校验, 旧代退场时不会把新代的状态擦掉。
SHOW_RUN = {"gen": 0, "stop": None, "card": None}
SHOW_RUN_LOCK = threading.Lock()


def _show_stop_current():
    """停止当前卡片运行 (幂等)。没有在跑就什么也不做。"""
    with SHOW_RUN_LOCK:
        ev = SHOW_RUN["stop"]
        SHOW_RUN["stop"] = None
        SHOW_RUN["card"] = None
        SHOW_RUN["gen"] += 1
    if ev is not None:
        ev.set()
    # 渐变就地冻结在当前值 → 把 FADE_ZONE 里各目标的当前值立即同步给真台。
    # ⚠️ 不同步的话: 最后一次插值可能已被合并器限速挡下或根本没写,
    #    真台停在中间值, 本地台面却是冻结值 —— 桥接模式下两边不一致。
    #    取快照要趁 worker 还没跑 finally (FADE_ZONE 还未注销), 所以在 ev.set() 后立刻做。
    with FADE_LOCK:
        zone_keys = list(FADE_ZONE.keys())
    if zone_keys:
        _bridge_force_sync(zone_keys, skip_interrupted=True)
    SHOW_STATE["running"] = None
    SHOW_STATE["progress"] = 1.0
    SHOW_STATE["step"] = ""

# ---- 卡片定时触发: 延时 N 秒后 / 定在 HH:MM 自动启动, 可取消 ----
SCHEDULES = []        # {"sid", "card_id", "card_name", "run_at"(epoch), "mode", "timer"}
SCHED_SEQ = [0]
SCHED_LOCK = threading.Lock()


def schedule_card(card, mode, delay=None, clock=None):
    """定时启动卡片。mode='delay' delay 秒后; mode='clock' 今天的 clock(HH:MM) 时刻。"""
    if mode == "delay":
        run_at = time.time() + max(float(delay), 0.5)
    else:
        h, m = [int(x) for x in str(clock).split(":")[:2]]
        t = time.localtime()
        run_at = time.mktime((t.tm_year, t.tm_mon, t.tm_mday, h, m, 0, 0, 0, -1))
        if run_at <= time.time():
            run_at += 86400          # 已过时刻 → 明天
    SCHED_SEQ[0] += 1
    sid = SCHED_SEQ[0]

    def fire():
        with SCHED_LOCK:
            SCHEDULES[:] = [s for s in SCHEDULES if s["sid"] != sid]
        cur = next((c for c in SHOW_CARDS if c["id"] == card["id"]), None)
        if not cur:
            log("SCHED 定时启动失败: 卡片已被删除")
            return
        EVT_SEQ[0] += 1
        EVENTS.append({"id": EVT_SEQ[0], "time": time.strftime("%H:%M:%S"),
                       "text": "⏰ 定时触发 — 卡片「%s」自动启动" % cur.get("name", "")})
        log("SCHED 定时启动卡片: %s" % cur.get("name"))
        run_show(cur)

    t = threading.Timer(max(run_at - time.time(), 0.1), fire)
    t.daemon = True
    t.start()
    with SCHED_LOCK:
        SCHEDULES.append({"sid": sid, "card_id": card["id"], "card_name": card.get("name", ""),
                          "run_at": run_at, "mode": mode, "timer": t})
    log("SCHED 定时任务 #%d: 「%s」 %s (%s)" %
        (sid, card.get("name", ""), time.strftime("%H:%M:%S", time.localtime(run_at)),
         "延时" if mode == "delay" else "定时"))


def cancel_schedule(sid):
    with SCHED_LOCK:
        s = next((x for x in SCHEDULES if x["sid"] == sid), None)
        if not s:
            return False
        s["timer"].cancel()
        SCHEDULES[:] = [x for x in SCHEDULES if x["sid"] != sid]
    log("SCHED 取消定时任务 #%d" % sid)
    return True


def run_show(card):
    """启动卡片 (时间轴调度器): 无 at 的动作顺序排布, 有 at 的按偏移并行;
    卡片 next 字段非空时执行完自动接续下一张 (防环, 链长上限 16)。

    同一张卡已在运行 → 直接忽略 (连点保护): 否则双击会起两个 worker 同时驱动
    同一张卡, 推子被写两遍、停止信号还会被后一个 worker 吃掉。
    返回 True=已启动, False=忽略 (该卡正在运行)。
    """
    with SHOW_RUN_LOCK:
        if SHOW_RUN["stop"] is not None and SHOW_RUN["card"] == card["id"]:
            return False
        old = SHOW_RUN["stop"]
        SHOW_RUN["gen"] += 1
        gen = SHOW_RUN["gen"]
        ev = threading.Event()
        SHOW_RUN["stop"] = ev
        SHOW_RUN["card"] = card["id"]
    if old is not None:
        old.set()      # 旧代立刻收到停止信号; 它清不掉新代的 Event
    threading.Thread(target=_show_worker, args=(card, ev, gen), daemon=True).start()
    return True


def _show_worker(first_card, run_ev, gen):
    snapshot_done = False
    seen = set()
    cur = first_card
    depth = 0
    while cur is not None and not run_ev.is_set() and depth < 16:
        if cur["id"] in seen:
            log("SHOW 卡片链检测到循环, 停止接续")
            break
        seen.add(cur["id"])
        depth += 1
        if not snapshot_done:
            # 一键撤销: 执行前自动保存台面快照 (整条链只存一个点, 撤销即回到链开始前)
            try:
                snap, _saved = save_snapshot("自动 · %s" % str(cur.get("name", "卡片"))[:20], auto=True)
                snapshot_done = True
            except Exception as e:
                log("SHOW 自动撤销点保存失败: %r" % e)
        _run_card_on_timeline(cur, run_ev, gen)
        if run_ev.is_set():
            break
        nid = str(cur.get("next") or "")
        nxt = next((c for c in SHOW_CARDS if c["id"] == nid), None) if nid else None
        if nxt:
            log("SHOW 卡片链: 「%s」完成 → 接续「%s」" % (cur.get("name"), nxt.get("name")))
            time.sleep(0.4)
        cur = nxt
    if depth >= 16:
        log("SHOW 卡片链超过 16 张, 停止接续")
    if SHOW_RUN["gen"] == gen:
        # 还是当前代才清理共享状态 —— 被新代顶掉的旧 worker 退场时不能擦新代的状态
        with SHOW_RUN_LOCK:
            if SHOW_RUN["gen"] == gen:
                SHOW_RUN["stop"] = None
                SHOW_RUN["card"] = None
        SHOW_STATE["running"] = None
        SHOW_STATE["progress"] = 1.0
        SHOW_STATE["step"] = ""


def _run_card_on_timeline(card, run_ev, gen):
    card_name = str(card.get("name", "卡片"))

    # All Live 自动混音演示: 推子随音乐节奏起伏 (电动推子玩具同款)
    if card["id"] == "alllive":
        duration = 12.0
        with STATE.lock:
            base = {i: STATE.ch[i]["fader"] for i in range(1, 9)}
        log("SHOW All Live 演示开始: 通道 01-08 推子自动起舞 %.0f 秒" % duration)
        demo_targets = [("ch_fader", i, 0, 0) for i in range(1, 9)]
        _register_fade(demo_targets, card_name)
        t0 = time.time()
        try:
            while not run_ev.is_set():
                t = time.time() - t0
                if t >= duration:
                    break
                time.sleep(0.08)
                for i in range(1, 9):
                    if _interrupted("ch_fader", i):
                        continue
                    v = base[i] + 0.20 * math.sin(t * 2.4 + i * 0.85) * math.sin(t * 0.7)
                    set_value("ch_fader", i, v, source="fade")
                SHOW_STATE["progress"] = t / duration
            for i in range(1, 9):
                if not _interrupted("ch_fader", i):
                    set_value("ch_fader", i, base[i], source="fade")
        finally:
            _unregister_fade(demo_targets)
        log("SHOW All Live 演示结束,推子已归位")
        return

    # 时间轴排布: 无 at 顺序排布, 有 at 并行
    actions = list(card.get("actions") or [])
    for lg in card.get("fades") or []:          # 旧 fades 结构兼容
        actions.append({"kind": "fade_from", "ch": lg["ch"], "frm": lg["from"],
                        "to": lg["to"], "duration": lg.get("duration", 3.0),
                        "curve": lg.get("curve", "linear")})
    timeline = []
    cursor = 0.0
    for n, act in enumerate(actions):
        at = act.get("at")
        try:
            start = float(at) if at is not None else cursor
        except (TypeError, ValueError):
            start = cursor
        dur = _act_duration(act)
        timeline.append({"n": n, "act": act, "start": start, "dur": dur})
        cursor = start + dur
    total = max([e["start"] + e["dur"] for e in timeline] + [0.001])

    SHOW_STATE["running"] = card["id"]
    SHOW_STATE["name"] = card.get("name", "")
    SHOW_STATE["progress"] = 0.0
    SHOW_STATE["step"] = ""
    log("SHOW 启动卡片: %s (%d 个动作, 时间轴 %.1f 秒)" % (card_name, len(actions), total))

    t0 = time.time()
    fired = set()
    active = {}            # n -> {"targets":..., "starts":...} 进行中的渐变
    TICK = 0.05
    try:
        while not run_ev.is_set():
            t = time.time() - t0
            for ev in timeline:
                n, act = ev["n"], ev["act"]
                if t < ev["start"]:
                    continue
                if n not in fired:
                    fired.add(n)
                    SHOW_STATE["step"] = "%d/%d · %s" % (n + 1, len(actions), _act_label(act))
                    if ev["dur"] <= 0.001:
                        _exec_instant(act)
                        continue
                    targets = _fade_targets_for(act)
                    if targets is None:
                        _exec_instant(act)
                        continue
                    if act["kind"] in ("fade_from", "fade_from_bus"):
                        fk, idx = targets[0][0], targets[0][1]
                        set_value(fk, idx, float(act.get("frm", 0.0)), source="action")
                    starts = [(k, i, get_value(k, i), b) for k, i, b in targets]
                    _register_fade([(k, i, 0, b) for k, i, b in targets], card_name)
                    active[n] = {"targets": [(k, i, 0, b) for k, i, b in targets],
                                 "starts": starts}
                    log("SHOW ▶ %s (%.1f 秒, 曲线 %s)" %
                        (_act_label(act), ev["dur"], act.get("curve", "linear")))
                if n in active:
                    if t >= ev["start"] + ev["dur"]:
                        _apply_fade(active[n], 1.0)
                        _unregister_fade(active[n]["targets"])
                        log("SHOW ✓ %s" % _act_label(act))
                        del active[n]
                    else:
                        ratio = curve_ratio((t - ev["start"]) / ev["dur"],
                                            act.get("curve", "linear"))
                        _apply_fade(active[n], ratio)
            if fired and not active and all(e["n"] in fired for e in timeline) \
                    and t >= total - TICK:
                break
            SHOW_STATE["progress"] = min(1.0, t / total)
            time.sleep(TICK)
        # 停止 (run_ev): 渐变就地冻结在当前值, 不写终值
    finally:
        for tg in active.values():
            _unregister_fade(tg["targets"])
        if SHOW_RUN["gen"] == gen and SHOW_STATE["running"] == card["id"]:
            SHOW_STATE["running"] = None
            SHOW_STATE["progress"] = 1.0
            SHOW_STATE["step"] = ""


# ==================================================================
# ==== x32sim/persist.py
# ==================================================================
# -*- coding: utf-8 -*-
"""x32sim/persist — 自定义配置持久化 (原子写 / 坏文件备份 / 消毒)"""

import json
import os
import tempfile
import threading
import time



# ---- 自定义配置持久化: 控制键/演出卡片/步长存 JSON, 重启不丢 ----
# ⚠️ 可变容器: main() 可用 --config 改写。默认值按**仓库根目录**推:
#    包形态(开发)下 __file__ 在 x32sim/ 里, 配置放上一级; 合成单文件形态下
#    __file__ 就是 x32_simulator.py 本身, 其目录即根目录 —— 两种形态一致。
_HERE = os.path.dirname(os.path.abspath(__file__))
_ROOT = os.path.dirname(_HERE) if os.path.basename(_HERE) == "x32sim" else _HERE
CONFIG_PATH = [os.path.join(_ROOT, "user_config.json")]
ID_SEQ = [1000]
CONFIG_SAVE_LOCK = threading.Lock()
CONFIG_BROKEN_BACKUP = [None]   # 上次加载时坏文件的备份路径 (None=上次加载正常)


def next_id(prefix):
    ID_SEQ[0] += 1
    return "%s%d" % (prefix, ID_SEQ[0])


def save_user_config():
    """把自定义配置**原子**写盘。返回 True=落盘成功, False=失败 (已记日志)。

    ⚠️ 曾经这里有三种"假成功", 全部堵上:
      1. 直接 open(目标, "w") 开写 → 写一半断电/磁盘满就是半个 JSON,
         下次启动 json.load 报错 → 预设/卡片静默全丢。
         现在: 同目录临时文件 + flush + fsync + os.replace 原子替换,
         任何时刻磁盘上都是一个完整文件。
      2. 失败只 log 一行, 接口照样返 ok:true → 用户以为存住了, 重启就没。
         现在返回 False, HTTP 层据此返 500 并说明"改动只在内存中"。
      3. 并发保存互相踩 (PermissionError 静默失败) → 全局保存锁 +
         每次独立临时文件名, 物理上不冲突。
    """
    with CONFIG_SAVE_LOCK:
        try:
            # list(...) 浅拷贝: 卡片/预设可能在别的线程里 append, 直接序列化原列表
            # 会抛 "dict changed size during iteration" (曾经偶发 PermissionError 的亲戚)
            text = json.dumps({"quickKeys": list(QUICK_KEYS), "cards": list(SHOW_CARDS),
                               "keyCfg": KEY_CFG, "idSeq": ID_SEQ[0],
                               "bridgeTarget": BRIDGE_TARGET[0],
                               "fxSync": dict(FX_SYNC),
                               "console": CTRL_PROFILE_ID[0],
                               "rider": rider_dump(),
                               "ports": {"udp": PORT_CFG["udp"], "web": PORT_CFG["web"]},
                               "fxSlots": {str(s): {"type": STATE.fx[s]["type"],
                                                    "name": STATE.fx[s]["name"],
                                                    "mix": STATE.fx[s]["mix"],
                                                    "par": {str(p): v for p, v in STATE.fx[s]["par"].items()}}
                                           for s in range(1, FX_COUNT + 1)},
                               "presets": list(SNAPSHOTS),
                               "names": {"%s|%d" % k: v for k, v in STATE.names.items()}},
                              ensure_ascii=False, indent=1, allow_nan=False)
        except Exception as e:
            # allow_nan=False: NaN 混进状态时在这里炸, 而不是写出一个 Python 专有
            # 字面量、别的工具还读不了的"假配置"
            log("配置序列化失败 (疑似 NaN 混进台面状态): %r" % e)
            return False
        folder = os.path.dirname(CONFIG_PATH[0]) or "."
        tmp = None
        try:
            fd, tmp = tempfile.mkstemp(prefix=".user_config-", suffix=".tmp", dir=folder)
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                f.write(text)
                f.flush()
                os.fsync(f.fileno())
            # Windows 上 replace 的目标可能被读进程占着 → 短暂重试, 别静默失败
            for attempt in range(4):
                try:
                    os.replace(tmp, CONFIG_PATH[0])
                    tmp = None
                    break
                except PermissionError:
                    if attempt == 3:
                        raise
                    time.sleep(0.05 * (attempt + 1))
            if CONFIG_BROKEN_BACKUP[0]:
                log("配置已用当前台面覆盖旧文件 (损坏的旧配置备份在 %s)"
                    % CONFIG_BROKEN_BACKUP[0])
                CONFIG_BROKEN_BACKUP[0] = None
            return True
        except Exception as e:
            log("配置保存失败: 无法写入 %s (%r) — 本次改动只在内存中, 重启后会丢失"
                % (CONFIG_PATH[0], e))
            if tmp:
                try:
                    os.remove(tmp)
                except OSError:
                    pass
            return False


def load_user_config():
    try:
        with open(CONFIG_PATH[0], "r", encoding="utf-8") as f:
            d = json.load(f)
        # 自定义端口（全 None 表示没设过, 走内置默认）
        p = d.get("ports")
        if isinstance(p, dict):
            PORT_CFG["udp"] = valid_port(p.get("udp"))
            PORT_CFG["web"] = valid_port(p.get("web"), allow_zero=True)
        rider_load(d.get("rider"))
        if isinstance(d.get("quickKeys"), list):
            # ⚠️ 控制键也要消毒：配置文件是用户可编辑的 JSON，一个 idx=99 的条目
            #    会让 /api/key 在 apply_key 里 KeyError（早年就是这么崩的）。
            #    kind 不在白名单、idx 不是数字 → 整条丢弃。
            clean_keys = []
            for k in d["quickKeys"]:
                if not isinstance(k, dict) or k.get("kind") not in QUICK_KEY_KINDS:
                    continue
                try:
                    k_idx = int(k.get("idx", 1) or 1)
                    k_sign = int(k.get("sign", 1) or 1)
                except (TypeError, ValueError):
                    continue
                if not target_exists(k["kind"], k_idx):
                    continue
                clean_keys.append({
                    "id": str(k.get("id") or next_id("k")),
                    "name": str(k.get("name", "")).strip() or "控制键",
                    "icon": str(k.get("icon", "⚡"))[:4] or "⚡",
                    "kind": k["kind"], "idx": k_idx,
                    "sign": -1 if k_sign < 0 else 1,
                })
            QUICK_KEYS[:] = clean_keys
            if len(clean_keys) != len(d["quickKeys"]):
                log("配置里的控制键有 %d 条不合法，已丢弃"
                    % (len(d["quickKeys"]) - len(clean_keys)))
        if isinstance(d.get("cards"), list):
            SHOW_CARDS[:] = d["cards"]
        # 预设（台面快照）: 以前只存在内存里重启即丢，现在跟配置一起落盘。
        # 配置文件可手改 → 必须逐条消毒，脏数据最多被丢弃，不能把回归变成乱写。
        # ⚠️ skipped_bad_scope 在条件块**外面**初始化: 缺 presets 键的配置
        #    (手写/旧版) 以前会在这里 UnboundLocalError → 被外层 except 当成
        #    "文件损坏"备份+重置, 用户数据静默全丢。出厂示例卡自带 legacy
        #    fades, 迁移段每次启动都会跑到这个变量, 撞上的概率并不低。
        skipped_bad_scope = 0
        if isinstance(d.get("presets"), list):
            loaded = []
            for s in d["presets"][:8]:
                if not isinstance(s, dict) or not isinstance(s.get("data"), dict):
                    continue
                # scope: 缺字段 = 旧格式全量预设 (合法); 有字段但清不出合法范围
                # = 脏数据 → **跳过这条预设**并记日志。曾经的写法是静默回落全量,
                # 一条坏 scope 就能让回归误改全台; 原文件我们不动, 用户修完能恢复。
                raw_scope = s.get("scope")
                if raw_scope is None:
                    sc = {"groups": list(PRESET_DEFAULT_SCOPE["groups"]),
                          "params": list(PRESET_DEFAULT_SCOPE["params"]), "indices": {}}
                else:
                    sc, ok, why = clean_preset_scope(raw_scope)
                    if not ok:
                        skipped_bad_scope += 1
                        log("预设「%s」的范围非法 (%s)，已跳过；原配置未改动，修复后可恢复"
                            % (s.get("name") or "?", why))
                        continue
                try:
                    sid = int(s.get("id") or 0)
                except (TypeError, ValueError):
                    sid = 0
                try:
                    scene_no = int(s.get("scene") or 1)
                except (TypeError, ValueError):
                    scene_no = 1
                try:
                    cnt = int(s.get("count") or 0)
                except (TypeError, ValueError):
                    cnt = 0
                loaded.append({"id": sid or (len(loaded) + 1),
                               "name": str(s.get("name") or "预设")[:20],
                               "time": str(s.get("time") or ""),
                               "scene": min(max(scene_no, 0), 99),
                               "scope": sc,
                               "data": s["data"], "count": max(0, cnt)})
            SNAPSHOTS[:] = loaded
            if SNAPSHOTS:
                SNAP_ID[0] = max([x["id"] for x in SNAPSHOTS] + [SNAP_ID[0]])
                log("已载入 %d 条预设%s" % (
                    len(SNAPSHOTS),
                    ("，%d 条因范围非法被跳过" % skipped_bad_scope) if skipped_bad_scope else ""))
        # 迁移旧结构: 内置/历史卡片用独立 fades 字段, 统一转成 fade_from 动作, 保证简介与动作一致
        migrated = False
        for c in SHOW_CARDS:
            if isinstance(c, dict) and c.get("fades"):
                for f in c["fades"]:
                    try:
                        c.setdefault("actions", []).append({
                            "kind": "fade_from", "ch": int(f.get("ch", 1)),
                            "frm": float(f.get("from", 0.0)), "to": float(f.get("to", 0.9)),
                            "duration": float(f.get("duration", 5.0)),
                            "curve": f.get("curve", "linear")})
                    except (TypeError, ValueError):
                        pass
                c["fades"] = []
                migrated = True
        if migrated:
            # ⚠️ 有预设因范围非法被跳过时**不做迁移保存**: 保存写的是内存状态,
            #     会把用户手改坏、还没来得及修的那条预设从文件里抹掉。
            #     旧结构留在内存里不影响运行, 用户修好配置后的下次启动再迁移。
            if skipped_bad_scope:
                log("检测到旧版 fades 结构; 因有预设被跳过, 本次不自动保存, "
                    "修复配置后的下次启动将自动迁移")
            else:
                save_user_config()
                log("已迁移旧版 fades 结构为 fade_from 动作")
        if isinstance(d.get("keyCfg"), dict):
            KEY_CFG.update(d["keyCfg"])
        if isinstance(d.get("names"), dict):
            for k, v in d["names"].items():
                try:
                    g, i = k.split("|")
                    STATE.names[(g, int(i))] = str(v)
                except (ValueError, TypeError):
                    pass
        if isinstance(d.get("idSeq"), int):
            ID_SEQ[0] = max(ID_SEQ[0], d["idSeq"])
        if isinstance(d.get("fxSync"), dict):
            with FX_SYNC_LOCK:
                for k in ("mode", "group", "followTap", "bpm", "note", "dotted"):
                    if k in d["fxSync"]:
                        FX_SYNC[k] = d["fxSync"][k]
        # ⚠️ 控台要先恢复: 下面恢复 fxSlots 时要用**该控台的效果库**做校验,
        #    否则会把别的台的算法当成合法的装进来。
        if isinstance(d.get("console"), str) and d["console"] in CONSOLE_PROFILES:
            CTRL_PROFILE_ID[0] = d["console"]
        if isinstance(d.get("fxSlots"), dict):
            with STATE.lock:
                for sk, sv in d["fxSlots"].items():
                    try:
                        s = int(sk)
                    except (TypeError, ValueError):
                        continue
                    if not (1 <= s <= FX_COUNT) or not isinstance(sv, dict):
                        continue
                    t = str(sv.get("type", "")).upper()
                    # 旧版配置存的是旧枚举名 (PLATE/CHAMBER/VINTAGE), v1.6 起
                    # 枚举名迁移为 PLAT/CHAM/VREV —— 按 par 号存的**数值**不用动,
                    # 只把 type 名过一道别名表, 否则合法数据会被判"未知算法"丢掉。
                    t = FX_TYPE_ALIAS.get(t, t)
                    if t and t not in fx_algos():
                        continue
                    # 手改/旧配置可能把 heavy 算法塞进 FX5-8 (API 层拦得住,
                    # 配置文件拦不住) —— 真台 DSP 装不下的状态不该被恢复出来。
                    if t and not slot_allows(s, t):
                        log("配置里的 FX%d 算法 %s 只能装入 FX %s, 已跳过该槽"
                            % (s, t, "/".join(map(str, FX_SLOTS_HEAVY))))
                        continue
                    STATE.fx[s]["type"] = t
                    STATE.fx[s]["name"] = str(sv.get("name", ""))[:12]
                    try:
                        STATE.fx[s]["mix"] = _clamp01(sv.get("mix", 0.25), 0.25)
                    except (TypeError, ValueError):
                        pass
                    par = sv.get("par")
                    if isinstance(par, dict):
                        STATE.fx[s]["par"] = {}
                        algo = fx_algos().get(t)
                        for pk, pv in par.items():
                            try:
                                pn = int(pk)
                            except (TypeError, ValueError):
                                continue
                            if algo is not None and not any(
                                    q["p"] == pn for q in algo["params"]):
                                continue   # 该算法没这个参数号 (旧数据/手改)
                            # ⚠️ _finite: 旧版配置可能已被 NaN 污染（Python 的
                            #    json.load 默认接受字面量 NaN），不清洗就带着毒进 STATE。
                            #    再按**新标定量程**钳一回: 旧表把阻尼当 0–1 存,
                            #    新标定是 1000–20000 Hz, 不钳就会有个越界值卡在
                            #    状态里 (界面滑杆直接飞到一端)。
                            v = _finite(pv, 0.0)
                            if algo is not None:
                                v = fx_par_clamp(s, pn, v)
                            STATE.fx[s]["par"][pn] = v
        if isinstance(d.get("bridgeTarget"), str) and d["bridgeTarget"].strip():
            BRIDGE_TARGET[0] = d["bridgeTarget"].strip()
        log("已加载自定义配置: %d 个控制键, %d 张演出卡片%s"
            % (len(QUICK_KEYS), len(SHOW_CARDS),
               (", 记住的真台地址 %s" % BRIDGE_TARGET[0]) if BRIDGE_TARGET[0] else ""))
        return True          # ⚠️ 别丢: 成功路径曾经直落结尾返 None, 调用方
        #                   `if not load_user_config()` 会把"加载成功"当失败
    except FileNotFoundError:
        return True          # 没有配置文件 = 全新装机, 正常
    except Exception as e:
        # 坏文件 (写一半被杀 / 手改坏): 曾经只是 log 一行, 然后内存里的默认值
        # 会在下次保存时把用户数据覆盖掉 → 预设/卡片"静默全丢"。
        # 现在先把坏文件备份出来 (数据可救), 再明确告知, 绝不明不明白覆盖。
        backup = None
        try:
            backup = "%s.corrupt-%s" % (CONFIG_PATH[0], time.strftime("%Y%m%d-%H%M%S"))
            os.replace(CONFIG_PATH[0], backup)
        except OSError:
            backup = None
        CONFIG_BROKEN_BACKUP[0] = backup
        if backup:
            log("配置加载失败: %r — 文件已损坏, 备份到 %s; 本次用默认配置启动, "
                "修复后可把备份内容并回 user_config.json" % (e, backup))
        else:
            log("配置加载失败: %r — 文件已损坏且无法备份, 已保留原文件不动; "
                "本次用默认配置启动" % e)
        return False


def clear_console():
    """空台子:全部推子 1 秒同步拉底 + 全部取消静音,得到干净的空台。"""
    RAMP_STOP.set()
    RECALL_STOP.set()
    _show_stop_current()

    def worker():
        RAMP_STOP.clear()
        kinds = ([("ch_fader", i) for i in range(1, 33)] +
                 [("bus_fader", i) for i in range(1, 17)] +
                 [("dca_fader", i) for i in range(1, 9)] +
                 [(g + "_fader", i) for g, n in (("auxin", 6), ("usb", 2), ("fxret", 8), ("mtx", 6))
                  for i in range(1, n + 1)] +
                 [("main_fader", 0)])
        starts = [(k, i, get_value(k, i)) for k, i in kinds]
        steps = 20
        try:
            for s in range(1, steps + 1):
                if RAMP_STOP.is_set():
                    return
                time.sleep(0.05)
                ratio = curve_ratio(s / steps, "ease_out")
                for (k, i, a) in starts:
                    set_value(k, i, a * (1.0 - ratio))
        except Exception:
            pass
        for i in range(1, 33):
            set_value("ch_on", i, 1)
        for i in range(1, 17):
            set_value("bus_on", i, 1)
        for i in range(1, 9):
            set_value("dca_on", i, 1)
        set_value("main_on", 0, 1)
        log("CONSOLE 空台子完成: 全部推子拉底,全部取消静音")
    threading.Thread(target=worker, daemon=True).start()


def recall_last():
    """回传数据:把最近保存的预设平滑写回台面(读取→空台→回传 流程的最后一步)。"""
    if not SNAPSHOTS:
        return None
    return recall_snapshot(SNAPSHOTS[0]["id"], 3.0)


