# ==== x32sim/snapshot.py
# ==================================================================
# -*- coding: utf-8 -*-
"""x32sim/snapshot — 状态聚合: /api/state 快照 + 条件轮询指纹"""

import hashlib
import json
import math
import time



# 非输入组的行只带"推子/静音/声像"三项进 /api/state。
# 为什么: Bus/Matrix/Main 加上均衡 6 段 + 动态 + 插入后, 每行 45~50 个字段,
# 全部塞进快照会多出约 26KB —— 而快照是**任何一处改动就整包重发**的,
# 拖一次推子就是 4 次/秒 × 26KB。详情页改用 /api/params 按需拉。
_LEAN_FIELDS = ("fader", "on", "pan")


def _lean(row):
    return {k: v for k, v in row.items() if k in _LEAN_FIELDS}


def snapshot_state(since_log=None):
    """聚合全量状态。since_log 给定时, log 字段只返回增量 (网页 250ms 轮询省带宽)。"""
    levels = compute_levels()
    with LOG_LOCK:
        ring = list(LOG_RING)
        seq = LOG_SEQ[0]
    if since_log is None or not isinstance(since_log, int):
        log_tail = ring[-40:]
    elif since_log >= seq:
        log_tail = []
    elif seq - since_log <= len(ring):
        log_tail = ring[len(ring) - (seq - since_log):]
    else:
        log_tail = ring[-40:]       # 落后太多, 直接给全量
    with STATE.lock:
        scene = STATE.scene
        names = {"main": STATE.names.get(("main", 0), "")}
        for g, cnt in NAME_COUNTS.items():
            names[g] = {str(i): STATE.names.get((g, i), "") for i in range(1, cnt + 1)}
    return {
        "ch": {str(i): STATE.ch[i] for i in range(1, 33)},
        "bus": {str(i): _lean(STATE.bus[i]) for i in range(1, 17)},
        "dca": {str(i): STATE.dca[i] for i in range(1, 9)},
        "auxin": {str(i): _lean(STATE.auxin[i]) for i in range(1, 7)},
        "usb": {str(i): STATE.usb[i] for i in range(1, 3)},
        "fxret": {str(i): _lean(STATE.fxret[i]) for i in range(1, 9)},
        "mtx": {str(i): _lean(STATE.mtx[i]) for i in range(1, 7)},
        "main": _lean(STATE.main),
        "meters": levels,
        "scene": scene,
        "fx": fx_state(),
        "console": {"id": profile().id, "label": profile().label,
                    "vendor": profile().vendor, "transport": profile().transport,
                    "ready": profile().ready, "verified": profile().verified,
                    "note": profile().note, "caps": list(profile().caps),
                    "counts": dict(profile().counts),
                    # ⚠️ pending 必须在这里下发：设置页在「控台未标定」时会读
                    #    c.pending.length 列出"还缺哪些地址映射"，少了它就会
                    #    抛 TypeError 把整个 render() 打断（表现为切到未标定控台后
                    #    界面卡在旧状态、不再刷新）。清单项里也有同一份。
                    "pending": profile().pending(),
                    "fxLib": len(profile().fx_algos),
                    "all": console_listing()},
        "ports": {"udp": UDP_PORT[0], "web": WEB_PORT[0],        # 当前**实际生效**的端口
                  "savedUdp": PORT_CFG["udp"], "savedWeb": PORT_CFG["web"],
                  "defUdp": DEF_UDP_PORT, "defWeb": DEF_WEB_PORT,
                  "envLocked": ENV_WEB_PORT[0] is not None,   # 线上部署: 网页端口由平台指定
                  "pending": ports_pending_restart()},
        "cards": SHOW_CARDS,
        "show": dict(SHOW_STATE),
        "events": list(EVENTS)[-6:],
        "snapshots": [{"id": s["id"], "name": s["name"], "time": s["time"],
                       "count": s.get("count", 0),
                       "scopeText": preset_scope_text(s.get("scope") or {})}
                      for s in SNAPSHOTS],
        "recall": dict(RECALL_STATE),
        # 自动增益/推子: 只带启用中的通道（通常 1-4 路），不把 32 路塞进状态包
        "rider": rider_snapshot(),
        "quickKeys": QUICK_KEYS,
        "keyCfg": dict(KEY_CFG),
        "names": names,
        "canUndo": len(AUTO_SNAPS) > 0,
        "subscribers": len(METER_SUBSCRIBERS),
        "log": log_tail,
        "logseq": seq,
        "bridge": {"on": BRIDGE["addr"] is not None,
                   "addr": ("%s:%d" % (BRIDGE["ip"], BRIDGE["port"])) if BRIDGE["addr"] else "",
                   "target": BRIDGE_TARGET[0],
                   "synced": BRIDGE["synced"],
                   "live": bool(BRIDGE["addr"] and time.time() - BRIDGE.get("last_recv", 0) < 8.0)},
        "schedules": [{"sid": s["sid"], "card": s["card_id"], "name": s["card_name"],
                       "runAt": s["run_at"], "mode": s["mode"]}
                      for s in list(SCHEDULES)],
    }


def _sanitize_snapshot(obj):
    """快照输出前的兜底消毒: 把任何残留的 NaN/inf 换成 None。

    入口层已经用 _finite 挡住了 NaN，这里是**第二道闸** —— 万一将来有新的
    写入路径漏了 _finite，宁可下发 null（前端显示 0/空），也不能让
    json.dumps 产出字面量 NaN 把前端 JSON.parse 崩掉（整个界面永久卡死）。
    """
    if isinstance(obj, float):
        return obj if math.isfinite(obj) else None
    if isinstance(obj, dict):
        return {k: _sanitize_snapshot(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [_sanitize_snapshot(v) for v in obj]
    return obj


def _state_version(head):
    """状态内容指纹 (调用方已剔除 meters/log/logseq/ver)。

    用途: /api/state?v=N 条件轮询。网页 250ms 全量轮询在空台也要 15-21KB,
    实测 271-300MB/h (4G 场景不可接受)。命中"没变"时服务端只回 ~30 字节。
    哈希失败 (含不可序列化对象) 时返回 None —— 调用方必须恒返全量,
    **绝不能**把 None 当合法版本号 (否则下次 v=None 也匹配, 界面被冻结)。
    """
    try:
        raw = json.dumps(head, sort_keys=True, ensure_ascii=False,
                         separators=(",", ":"), allow_nan=False)
    except (TypeError, ValueError):
        return None
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:16]


def snapshot_state_safe(since_log=None, ver=None):
    """snapshot_state + NaN 消毒（HTTP 层只走这个入口）。

    ver 给定时进入**条件快照**模式 (网页专用, 旧客户端不传):
      - 剔除 meters (改由 /api/meters 单独取, 它每 tick 都变, 不能进指纹);
      - 按内容指纹比对, 未变更 → {"unchanged":true, log, logseq};
      - 有变更 → 全量 + ver 字段 (下次轮询带上)。
    """
    snap = _sanitize_snapshot(snapshot_state(since_log))
    if ver is None:
        return snap
    snap.pop("meters", None)
    head = {k: v for k, v in snap.items() if k not in ("log", "logseq", "ver")}
    cur = _state_version(head)
    if cur is not None and cur == ver:
        return {"unchanged": True, "log": snap.get("log") or [],
                "logseq": snap.get("logseq", 0)}
    if cur is None:
        return snap                  # 放弃条件模式, 恒返全量 (客户端会看到无 ver)
    snap["ver"] = cur
    return snap


# ==================================================================
# ==== x32sim/httpapi.py
# ==================================================================
# -*- coding: utf-8 -*-
"""x32sim/httpapi — HTTP API (WebHandler: 全部路由)"""

import base64
import json
import time
import urllib.parse
from http.server import BaseHTTPRequestHandler

qr_svg = svg


class WebHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *args):
        pass  # 静默 HTTP 访问日志

    def _cfg_saved(self, what):
        """落盘自定义配置; 失败就发 500 说清楚"改动只在内存里", 返回 False。

        曾经的写法是失败只 log 一行、接口照样 ok:true —— 用户以为存住了,
        重启就没, 而且没有任何提示 (持久化"假成功")。
        """
        if save_user_config():
            return True
        self._send(500, "application/json", json.dumps(
            {"ok": False,
             "error": "%s失败: 无法写入配置文件 (%s) — 改动只在内存中, 重启后会丢失。"
                      "请检查所在目录是否可写、磁盘是否已满。" % (what, CONFIG_PATH[0])},
            ensure_ascii=False).encode("utf-8"))
        return False

    def _send(self, code, ctype, body):
        # 协商 gzip: 全量快照 43 KB, 压缩后约 5 KB —— 4G 上这是最直接的一笔。
        # 只对 >512B 的响应压 (小包压了反而更大, 还多一次 CPU), 且尊重客户端声明。
        enc = ""
        if len(body) > 512 and "gzip" in (self.headers.get("Accept-Encoding") or ""):
            try:
                import gzip as _gzip
                body = _gzip.compress(body, 6)
                enc = "gzip"
            except Exception:
                enc = ""
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        if enc:
            self.send_header("Content-Encoding", enc)
            # 同一 URL 对不支持的客户端要发明文, 缓存必须按这个头分桶
            self.send_header("Vary", "Accept-Encoding")
        # CSP 只对**文档**有意义。挂在每个 JSON 响应上纯属白背字节:
        # 网页 250ms 轮询两个端点 → 8 次/秒 × 250 B ≈ 7 MB/h, 比响应体还贵。
        # ⚠️ 本项目的 HTML 是内联 <script> + 内联 <style>, 所以必须开
        #    'unsafe-inline'（换成外部文件就能收得更紧）。加上 frame-ancestors /
        #    object-src / base-uri 堵住"外链页面 iframe 套本页"和"改 base 标签
        #    劫持相对路径"这两类常见利用。它与前端 esc() 是两道独立的闸。
        if ctype.startswith("text/html"):
            self.send_header("Content-Security-Policy",
                             "default-src 'self'; script-src 'self' 'unsafe-inline'; "
                             "style-src 'self' 'unsafe-inline'; img-src 'self' data:; "
                             "connect-src 'self'; frame-ancestors 'self'; "
                             "object-src 'none'; base-uri 'self'")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.end_headers()
        try:
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError):
            pass

    def do_GET(self):
        path = urllib.parse.urlparse(self.path).path
        if path == "/":
            self._send(200, "text/html; charset=utf-8", WEB_PAGE.encode("utf-8"))
        elif path == "/api/state":
            since = None
            ver = None
            try:
                qs = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query,
                                           keep_blank_values=True)
                if "logseq" in qs:
                    since = int(qs["logseq"][0])
                if "v" in qs:
                    ver = str(qs["v"][0])[:32]     # 空串 = 首轮: 返全量并带上 ver
            except (TypeError, ValueError):
                since = None
            # allow_nan=False 是**测试阶段就该炸**的开关：万一哪条新写入路径漏了
            # _finite，让它在服务端抛出来，而不是等线上前端 JSON.parse 崩、界面卡死
            try:
                body = json.dumps(snapshot_state_safe(since, ver),
                                  allow_nan=False).encode("utf-8")
            except ValueError as e:
                log("STATE 快照含非有限数 (%s)，已降级为空快照" % e)
                body = b"{}"
            self._send(200, "application/json; charset=utf-8", body)
        elif path == "/api/sends":
            # 发送 (源 → 目标) 单独取: 五组共 838 个目标 × 3 字段放不进 /api/state,
            # 那会把刚结清的 4G 流量账又借回来。界面点开"发送"页时才拉一次。
            #   group=ch|auxin|fxret|bus|main (默认 ch)
            try:
                qs = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
                grp = qs.get("group", ["ch"])[0]
                # 旧参数名 ch= 继续认, 等价于 src=
                src = int(qs.get("src", qs.get("ch", ["1"]))[0])
            except (TypeError, ValueError):
                grp, src = "ch", 1
            grp = grp if grp in SEND_BUSES else "ch"
            src = min(max(src, 1), SEND_SRC_MAX[grp])
            row = {}
            for bus in range(1, SEND_BUSES[grp] + 1):
                i = send_pack(src, bus, grp)
                row[str(bus)] = {
                    "level": get_value("send_level" if grp == "ch" else grp + "_send_level", i),
                    "on": int(get_value("send_on" if grp == "ch" else grp + "_send_on", i) or 0),
                }
                if grp not in ("bus", "main"):
                    row[str(bus)]["tap"] = int(get_value(
                        "send_tap" if grp == "ch" else grp + "_send_tap", i) or 0)
            self._send(200, "application/json; charset=utf-8",
                       json.dumps({"group": grp, "src": src, "buses": SEND_BUSES[grp],
                                   "sends": row}, allow_nan=False).encode("utf-8"))

        elif path == "/api/params":
            # 某一路的全部处理参数 (均衡/门/动态/插入/声像…)。
            # 为什么不进 /api/state: 全组参数约 1.3K 个值, 每次推子一动就全量重发
            # 会把流量治理的账还回去。界面点开某一路时才拉一次, 之后靠写入回执与
            # 轮询里的行内字段 (fader/on/pan) 保持同步。
            try:
                qs = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
                grp = qs.get("group", ["ch"])[0]
                idx = int(qs.get("idx", ["1"])[0])
            except (TypeError, ValueError):
                grp, idx = "ch", 1
            if grp not in GROUP_PARAM_SPECS:
                self._send(400, "application/json",
                           b'{"ok":false,"error":"no such group"}')
                return
            idx = min(max(idx, 1 if grp != "main" else 0), GROUP_SIZE.get(grp, 1))
            vals = {sp.field: get_value(sp.kind, idx)
                    for sp in GROUP_PARAM_SPECS[grp]}
            self._send(200, "application/json; charset=utf-8",
                       json.dumps({"group": grp, "idx": idx, "params": vals},
                                  allow_nan=False).encode("utf-8"))

        elif path == "/api/paramspecs":
            # 各组参数的**元数据** (名称/量程/单位/枚举/默认值)。
            # 前端不再维护一份手抄的控件表: 抄一份就必然有一天与后端漂移,
            # 而漂移的症状是"滑块能拖到后端不认的区间"——只能靠回归抓。
            # 传 profile: WING 下不下发它没有地址的参数(aux 的 EQ / EQ 段类型 /
            # 插入 / 门模型), 否则界面上会多出一排永远拖不动的滑杆。
            self._send(200, "application/json; charset=utf-8",
                       json.dumps({"specs": {g: ui_specs(g, profile())
                                             for g in GROUP_PARAM_SPECS}},
                                  allow_nan=False).encode("utf-8"))
        elif path == "/api/fxcaps":
            # 效果参数的**可写性表** —— 给 App 用。
            # 网页走 /api/state.fx.slots[].params[].w（每参数一个布尔），
            # 但 App 是 OSC 直连，拿不到 HTTP 状态里的字段；它只在进 FX 页时
            # 拉这一个轻量接口就够。返回 null 表示"全部可写"（X32）。
            _p = profile()
            caps = _p.fx_param_caps()
            body = {"console": _p.id,
                    "all": caps is None,
                    "slots": caps or {}}
            self._send(200, "application/json; charset=utf-8",
                       json.dumps(body, allow_nan=False).encode("utf-8"))
        elif path == "/api/meters":
            # 电平单独取: 它每 tick 都变, 不能进 /api/state 的内容指纹,
            # 否则"没变更"永远命中不了。旧 /api/state 仍带 meters (App 兼容)。
            self._send(200, "application/json; charset=utf-8",
                       json.dumps({"meters": compute_levels()},
                                  allow_nan=False).encode("utf-8"))
        elif path == "/api/rider":
            self._send(200, "application/json; charset=utf-8",
                       json.dumps(rider_config(), allow_nan=False).encode("utf-8"))
        elif path == "/api/info":
            # trimRange: 控台实际接受的数字增益量程 (12=旧固件 / 18=新固件)。
            # 界面用它设滑块范围 —— 不让用户拖到 18 再被服务端弹回 12。
            _lim = active_limits("ch_trim")
            # calibration.unverified: 出厂值是**推断值**的参数清单。
            # 不把假设当事实 —— 界面可以据此显示"未标定"角标, 核对工具据此逐条比对。
            # 只回 kind 列表 (不回 note), 否则 /api/info 会被 26 条注释撑到 5KB。
            _unv = [sp.kind for sp in unverified_kinds()]
            # App 配对码：探测不到局域网地址（离线/只剩回环）时留空 —— 手机扫到
            # 127.0.0.1 只会连到它自己，前端据此隐藏那张码并说明原因。
            try:
                _pair = pair_text(LAN_IP[0], UDP_PORT[0], WEB_PORT[0])
            except ValueError:
                _pair = ""
            self._send(200, "application/json; charset=utf-8", json.dumps({
                "lanIp": LAN_IP[0], "udpPort": UDP_PORT[0], "webPort": WEB_PORT[0],
                "lanUrl": "http://%s:%d" % (LAN_IP[0], WEB_PORT[0]),
                "pairCode": _pair, "pairQr": "/pair.svg",
                "trimRange": abs(_lim[1]) if _lim else 18,
                "xremoteSnapshot": bool(XREMOTE_SNAPSHOT[0]),
                "tapWire": PARAM_SPECS["send_tap"].enum_wire,
                "calibration": {"count": len(_unv), "unverified": _unv},
            }).encode("utf-8"))
        elif path == "/api/scan":
            # 局域网发现: 广播 /xinfo 找真台 (X32 官方发现指令), 无需手填 IP
            found = scan_consoles()
            log("SCAN 扫描完成: 发现 %d 台设备" % len(found))
            self._send(200, "application/json; charset=utf-8",
                       json.dumps({"ok": True, "found": found}).encode("utf-8"))
        elif path == "/api/export":
            # 配置导出: 卡片/控制键/命名/设置 一个 JSON 文件
            cfg = {"version": 1, "exportedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
                   "quickKeys": QUICK_KEYS, "cards": SHOW_CARDS, "keyCfg": KEY_CFG,
                   "idSeq": ID_SEQ[0],
                   "names": {"%s|%d" % k: v for k, v in STATE.names.items()}}
            body = json.dumps(cfg, ensure_ascii=False, indent=1).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Disposition",
                             "attachment; filename=\"x32_config_%s.json\""
                             % time.strftime("%Y%m%d_%H%M"))
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Security-Policy",
                             "default-src 'none'; sandbox")
            self.end_headers()
            try:
                self.wfile.write(body)
            except (BrokenPipeError, ConnectionResetError):
                pass
        elif path == "/manifest.webmanifest":
            self._send(200, "application/manifest+json; charset=utf-8",
                       PWA_MANIFEST.encode("utf-8"))
        elif path == "/icon.svg":
            self._send(200, "image/svg+xml; charset=utf-8",
                       PWA_ICON.encode("utf-8"))
        elif path.startswith("/fx/"):
            # 效果器面板图 / 图鉴元数据。图片是内嵌的 base64（发行形态是单文件，
            # 读不了外部目录），所以这里解一次再发，不落磁盘。
            # 缓存放长：文件名带算法代码，内容不会变（换图就是换代码版本）。
            key = path[4:]
            blob = FX_ASSETS.get(key)
            if blob is None:
                self._send(404, "text/plain; charset=utf-8", b"not found")
                return
            raw = base64.b64decode(blob)
            ctype = ("image/webp" if key.endswith(".webp") else
                     "application/json; charset=utf-8")
            self.send_response(200)
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Length", str(len(raw)))
            self.send_header("Cache-Control", "public, max-age=604800")
            self.end_headers()
            try:
                self.wfile.write(raw)
            except (BrokenPipeError, ConnectionResetError):
                pass
        elif path == "/sw.js":
            self._send(200, "application/javascript; charset=utf-8",
                       PWA_SERVICE_WORKER.encode("utf-8"))
        elif path == "/qr.svg":
            # 手机扫码入口。地址优先用 ?u= 传进来的（页面显示的就是它，所见即所得），
            # 否则退回请求的 Host（从手机访问时天然是对的），最后才用探测到的局域网 IP。
            qs = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            target = (qs.get("u") or [""])[0].strip()
            if not target:
                host = (self.headers.get("Host") or "").strip()
                if host and host.split(":")[0] not in ("localhost", "127.0.0.1", "::1"):
                    target = "http://%s/" % host
                else:
                    target = "http://%s:%d/" % (LAN_IP[0], WEB_PORT[0])
            # 只做形状校验：本端点只渲染图片，不会去请求这个地址
            if not target.startswith(("http://", "https://")) or len(target) > 200:
                self._send(400, "text/plain; charset=utf-8", b"bad url")
                return
            try:
                body = qr_svg(target).encode("utf-8")
            except ValueError as e:
                self._send(400, "text/plain; charset=utf-8", str(e).encode("utf-8"))
                return
            self._send(200, "image/svg+xml; charset=utf-8", body)
        elif path == "/pair.svg":
            # 手机 App 的配对码：与 /qr.svg 的区别是**带 OSC 端口**。
            # 网页码里的端口是 HTTP 的；用户改过 UDP 端口后 App 按 10023 猜就会连错，
            # 所以 App 码把 host / osc / web 三个都写进去（格式见 x32sim/pair.py）。
            qs = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            host = (qs.get("h") or [LAN_IP[0]])[0].strip() or LAN_IP[0]
            try:
                osc = int((qs.get("o") or [UDP_PORT[0]])[0])
                web = int((qs.get("w") or [WEB_PORT[0]])[0])
            except (TypeError, ValueError):
                self._send(400, "text/plain; charset=utf-8", b"bad port")
                return
            try:
                code = pair_text(host, osc, web)
            except ValueError as e:
                self._send(400, "text/plain; charset=utf-8", str(e).encode("utf-8"))
                return
            try:
                body = qr_svg(code).encode("utf-8")
            except ValueError as e:
                self._send(400, "text/plain; charset=utf-8", str(e).encode("utf-8"))
                return
            self._send(200, "image/svg+xml; charset=utf-8", body)
        else:
            self._send(404, "text/plain; charset=utf-8", "not found".encode())

    # 请求体上限: 没有它, 一个 Content-Length: 10GB 的请求就能让 read() 吃到爆内存。
    # 8 MB 对"一份配置导入"绰绰有余 (卡片/控制键/命名全在里面)。
    MAX_BODY = 8 * 1024 * 1024

    def do_POST(self):
        path = urllib.parse.urlparse(self.path).path
        try:
            n = int(self.headers.get("Content-Length", 0))
        except (TypeError, ValueError):
            n = 0
        if n < 0 or n > self.MAX_BODY:
            self._send(413, "text/plain; charset=utf-8", b"body too large")
            return
        try:
            raw = self.rfile.read(n) if n else b""
            data = json.loads(raw.decode("utf-8")) if raw else {}
            if not isinstance(data, dict):
                raise ValueError("body must be a JSON object")
        except Exception:
            self._send(400, "text/plain; charset=utf-8", b"bad json")
            return

        # ⚠️ 全局兜底: 任何一个端点里漏掉的 TypeError/KeyError/ValueError 都会
        #    顺着 BaseHTTPRequestHandler 冒出去 → 连接被重置（curl 退出码 52），
        #    用户看到的是"点了没反应"，服务端日志里什么都没有。
        #    宁可返回 400 让人看见, 也不要静默断链。
        try:
            self._dispatch(path, data)
        except (KeyError, IndexError, TypeError, ValueError, AttributeError) as e:
            log("API %s 参数异常: %r" % (path, e))
            try:
                self._send(400, "application/json",
                           json.dumps({"ok": False,
                                       "error": "bad request: %s" % e}).encode("utf-8"))
            except Exception:
                pass

    def _dispatch(self, path, data):
        if path == "/api/rider":
            # 自动增益/推子的配置入口（实时生效，下一拍就按新参数跑）
            self._send(200, "application/json; charset=utf-8",
                       json.dumps({"ok": True, "rider": rider_set(data)},
                                  allow_nan=False).encode("utf-8"))
        elif path == "/api/set":
            # kind 是**组名**（ch/bus/dca/main/auxin/usb/fxret/mtx），param 是 fader/on。
            # idx 用 target_exists 预检：越界时给明确的 400，而不是 KeyError 撞全局兜底。
            grp = data.get("kind")
            if not isinstance(grp, str):
                self._send(400, "application/json",
                           b'{"ok":false,"error":"bad kind"}')
                return
            k = SET_KINDMAP.get(grp, {}).get(data.get("param"))
            if not k:
                self._send(400, "application/json", b'{"ok":false,"error":"bad kind"}')
                return
            try:
                idx = int(data.get("idx", 0))
            except (TypeError, ValueError):
                self._send(400, "application/json",
                           b'{"ok":false,"error":"bad idx"}')
                return
            if grp == "send":
                # 发送是二维目标: idx=源, bus=目标, 落库键 = send_pack。
                # 不接受"直接传打包值"—— 512 这种数字对用户没有意义, 也容易越界。
                sg = data.get("sgroup") or "ch"      # 源组: ch/auxin/fxret/bus/main
                if sg not in SEND_BUSES:
                    sg = "ch"
                try:
                    bus = int(data.get("bus", 0))
                except (TypeError, ValueError):
                    bus = 0
                if not (1 <= bus <= SEND_BUSES[sg]
                        and 1 <= idx <= SEND_SRC_MAX[sg]):
                    self._send(400, "application/json", json.dumps(
                        {"ok": False,
                         "error": "发送目标应为 源 1-%d + 目标 1-%d"
                                  % (SEND_SRC_MAX[sg], SEND_BUSES[sg])}
                    ).encode("utf-8"))
                    return
                # param 本身就是该组的 kind (send_level / auxin_send_level …),
                # 由 SET_KINDMAP 解析, 这里只负责打包目标。
                idx = send_pack(idx, bus, sg)
            if not target_exists(k, idx):
                self._send(400, "application/json",
                           json.dumps({"ok": False,
                                       "error": "idx %d 超出「%s」的范围" % (
                                           idx, profile().label)}).encode("utf-8"))
                return
            v = data.get("value")
            # 浮点类参数必须是数字：'abc'/null 会被收敛成默认值，
            # 于是"发了个垃圾值"表现成"参数归零"—— 比报错难查得多。
            # 判定走登记表 (vtype)：推子/增益/延时/低切频率/门限都是 float；
            # 越界不报 400 而是按 spec 钳制，与推子一贯的行为保持一致。
            sp = PARAM_SPECS.get(k)
            if (sp is not None and sp.vtype == "float") or k == "fx_mix":
                try:
                    float(v)
                except (TypeError, ValueError):
                    self._send(400, "application/json", json.dumps(
                        {"ok": False, "error": "该参数必须是数字"}).encode("utf-8"))
                    return
            set_value(k, idx, v)
            self._send(200, "application/json", b'{"ok":true}')

        elif path == "/api/setbatch":
            # 批量写入 (网页拖动 50ms 合并发送, 省请求数)
            sets = data.get("sets")
            if not isinstance(sets, list) or not sets or len(sets) > 128:
                self._send(400, "text/plain; charset=utf-8", b"bad sets")
                return
            n = 0
            for it in sets:
                if not isinstance(it, dict):
                    continue
                k = SET_KINDMAP.get(it.get("kind"), {}).get(it.get("param"))
                if not k:
                    continue
                try:
                    idx = int(it.get("idx", 0))
                except (TypeError, ValueError):
                    continue
                if it.get("kind") == "send":
                    sg = it.get("sgroup") or "ch"
                    if sg not in SEND_BUSES:
                        sg = "ch"
                    try:
                        bus = int(it.get("bus", 0))
                    except (TypeError, ValueError):
                        continue
                    if not (1 <= bus <= SEND_BUSES[sg]
                            and 1 <= idx <= SEND_SRC_MAX[sg]):
                        continue
                    idx = send_pack(idx, bus, sg)
                if not target_exists(k, idx):
                    continue      # 越界条目直接跳过，applied 计数会反映出来
                set_value(k, idx, it.get("value"))
                n += 1
            self._send(200, "application/json",
                       json.dumps({"ok": True, "applied": n}).encode())

        elif path == "/api/key":
            # 自定义控制键: 按步长调整目标推子
            r = apply_key(str(data.get("id", "")))
            if not r:
                self._send(404, "text/plain; charset=utf-8", b"no such key")
                return
            self._send(200, "application/json",
                       json.dumps({"ok": True, **r}).encode())

        elif path == "/api/keycfg":
            # 步长 / 渐变速度设置
            if "step_db" in data:
                KEY_CFG["step_db"] = min(max(_finite(data["step_db"], KEY_CFG["step_db"]), 0.5), 12.0)
            if "ramp" in data:
                KEY_CFG["ramp"] = min(max(_finite(data["ramp"], KEY_CFG["ramp"]), 0.0), 5.0)
            log("KEYCFG 步长 %.1f dB, 渐变 %.1f 秒" % (KEY_CFG["step_db"], KEY_CFG["ramp"]))
            if not self._cfg_saved("控制键设置"):
                return
            self._send(200, "application/json", b'{"ok":true}')

        elif path == "/api/fx":
            # 混响槽写入: {slot, field, value}  field ∈ type/on/mix/name/time/predelay/damp
            # 或 {action:"pull"} —— 从桥接的真台主动同步效果槽
            if str(data.get("action", "")) == "pull":
                ok, msg = fx_pull_from_console()
                if not ok:
                    self._send(400, "application/json",
                               json.dumps({"ok": False, "error": msg}).encode("utf-8"))
                    return
                self._send(200, "application/json",
                           json.dumps({"ok": True, "message": msg}).encode("utf-8"))
                return
            v, err = fx_set_param(data.get("slot"), data.get("field"), data.get("value"),
                                  source="manual")
            if err:
                self._send(400, "application/json",
                           json.dumps({"ok": False, "error": err}).encode("utf-8"))
                return
            if not self._cfg_saved("效果槽保存"):
                return
            self._send(200, "application/json",
                       json.dumps({"ok": True, "value": v}).encode("utf-8"))

        elif path == "/api/tap":
            # Tap 定拍: action='tap' 记一次点击 / 'reset' 清空 / 'apply' 按当前时值换算并写入
            act = str(data.get("action", "tap"))
            if act == "reset":
                tap_reset()
                self._send(200, "application/json", b'{"ok":true,"reset":true}')
                return
            if act == "tap":
                bpm, count, locked = tap_register()
                self._send(200, "application/json",
                           json.dumps({"ok": True, "bpm": round(bpm, 1), "count": count,
                                       "locked": locked}).encode("utf-8"))
                return
            if act == "apply":
                secs, written = fx_tap_apply()
                if isinstance(written, str):
                    self._send(400, "application/json",
                               json.dumps({"ok": False, "error": written}).encode("utf-8"))
                    return
                self._send(200, "application/json",
                           json.dumps({"ok": True, "seconds": round(secs, 3),
                                       "written": written}).encode("utf-8"))
                return
            self._send(400, "application/json", b'{"ok":false,"error":"bad action"}')

        elif path == "/api/fxsync":
            # 混响同步设置: {mode, group, followTap, note, dotted}
            with FX_SYNC_LOCK:
                mode = str(data.get("mode", FX_SYNC["mode"]))
                if mode in FX_MODE_LABEL:
                    FX_SYNC["mode"] = mode
                if isinstance(data.get("group"), list):
                    FX_SYNC["group"] = sorted({int(s) for s in data["group"]
                                               if isinstance(s, (int, float))
                                               and 1 <= int(s) <= FX_COUNT})
                if "followTap" in data:
                    FX_SYNC["followTap"] = bool(data["followTap"])
                if "note" in data and str(data["note"]) in NOTE_BEATS:
                    FX_SYNC["note"] = str(data["note"])
                if "dotted" in data:
                    FX_SYNC["dotted"] = bool(data["dotted"])
                snapshot = dict(FX_SYNC)
            if not self._cfg_saved("混响同步设置"):
                return
            log("REVERB 同步设置: %s · 联动组 %s · 跟随Tap %s · 时值 %s%s" % (
                FX_MODE_LABEL.get(snapshot["mode"], snapshot["mode"]),
                "/".join("FX%d" % s for s in snapshot["group"]) or "(空·全部混响槽)",
                "开" if snapshot["followTap"] else "关",
                snapshot["note"], "(附点)" if snapshot["dotted"] else ""))
            self._send(200, "application/json",
                       json.dumps({"ok": True, "sync": snapshot}).encode("utf-8"))

        elif path == "/api/ports":
            # 自由设置网络端口: {udp: 1-65535|null, web: 0-65535|null}
            # 传 null / "" = 清除该项自定义, 回到内置默认。端口是启动时绑定的 → 保存后需重启。
            errs = []
            new_udp, new_web = PORT_CFG["udp"], PORT_CFG["web"]
            if "udp" in data:
                raw = data.get("udp")
                if raw in (None, ""):
                    new_udp = None
                else:
                    new_udp = valid_port(raw)
                    if new_udp is None:
                        errs.append("OSC/UDP 端口必须是 1–65535 的整数")
            if "web" in data:
                raw = data.get("web")
                if raw in (None, ""):
                    new_web = None
                else:
                    new_web = valid_port(raw, allow_zero=True)
                    if new_web is None:
                        errs.append("网页端口必须是 0–65535 的整数（0 = 关闭网页）")
            eff_udp = new_udp if new_udp is not None else DEF_UDP_PORT
            eff_web = new_web if new_web is not None else DEF_WEB_PORT
            if ENV_WEB_PORT[0] is not None and "web" in data and new_web is not None:
                errs.append("本实例的网页端口由平台环境变量指定（线上部署），不能在此修改")
            if eff_web > 0 and eff_web == eff_udp:
                errs.append("OSC/UDP 端口与网页端口不能相同（当前都是 %d）" % eff_udp)
            if errs:
                self._send(400, "application/json",
                           json.dumps({"ok": False, "error": "；".join(errs)}).encode("utf-8"))
                return
            PORT_CFG["udp"], PORT_CFG["web"] = new_udp, new_web
            if not self._cfg_saved("端口设置"):
                return
            pending = ports_pending_restart()
            log("PORT 端口设置: OSC/UDP %s · 网页 %s → %s"
                % (eff_udp, (eff_web if eff_web > 0 else "已关闭"),
                   "重启后生效" if pending else "与当前一致, 无需重启"))
            self._send(200, "application/json", json.dumps({
                "ok": True, "restart": pending,
                "udp": eff_udp, "web": eff_web,
                "active": {"udp": UDP_PORT[0], "web": WEB_PORT[0]},
                "message": ("已保存, 重启模拟器后生效" if pending
                            else "已保存, 与当前生效端口一致"),
            }).encode("utf-8"))

        elif path == "/api/ctrlprofile":
            # 切换控台驱动: {id: "x32" | "m32" | "wing" | "yamaha" | "ah"}
            ok, msg, extra = set_profile(data.get("id"))
            if not ok:
                self._send(400, "application/json",
                           json.dumps({"ok": False, "error": msg}).encode("utf-8"))
                return
            p = profile()
            cleared = extra.get("fxCleared") or []
            fxn = "混响页已同步为「%s」的效果库（%d 种算法）" % (p.label, len(p.fx_algos))
            if cleared:
                fxn += "；FX%s 的算法不在新库中，已置空" % "/".join(str(x) for x in cleared)
            self._send(200, "application/json", json.dumps({
                "ok": True, "id": p.id, "label": p.label, "vendor": p.vendor,
                "ready": p.ready, "verified": p.verified,
                "fxCleared": cleared, "fxLib": extra.get("fxLib", 0),
                "fxSlots": extra.get("fxSlots", 0),
                "libCount": len(p.fx_algos),
                "fxLocked": (not p.ready) or ("fx" not in p.caps),
                "warning": "" if p.ready else
                "该控台驱动尚未标定：所有写入会被拒绝并记日志，卡片不会真正控制到台子",
                "fxNote": fxn,
            }).encode("utf-8"))

        elif path == "/api/console":
            # 数据读取与调用流程: 空台子 / 回传数据
            act = data.get("action")
            if act == "clear":
                clear_console()
                self._send(200, "application/json", b'{"ok":true}')
            elif act == "recall_last":
                snap = recall_last()
                if not snap:
                    self._send(404, "text/plain; charset=utf-8", b"no snapshot")
                    return
                self._send(200, "application/json",
                           json.dumps({"ok": True, "id": snap["id"]}).encode())
            else:
                self._send(400, "text/plain; charset=utf-8", b"bad action")

        elif path == "/api/name":
            # 网页上改通道/输出名称 (与 OSC /ch/01/config/name 等价, 重启不丢)
            g = str(data.get("group", ""))
            try:
                idx = int(data.get("idx", 0))
            except (TypeError, ValueError):
                idx = 0
            cnt = NAME_COUNTS.get(g)
            ok = (g == "main" and idx == 0) or (cnt and 1 <= idx <= cnt)
            if not ok:
                self._send(400, "text/plain; charset=utf-8", b"bad target")
                return
            set_name(g, idx, str(data.get("name", "")))
            if not self._cfg_saved("名称保存"):
                return
            self._send(200, "application/json", b'{"ok":true}')

        elif path == "/api/undo":
            # 一键撤销: 回滚到最近一次卡片执行前的台面 (静音立即恢复, 推子 2 秒滑回)
            if not AUTO_SNAPS:
                self._send(404, "application/json", b'{"ok":false,"error":"no undo point"}')
                return
            snap = AUTO_SNAPS.pop()
            _show_stop_current()      # 正在跑的卡片先停
            start_recall(snap, 2.0)
            log("SHOW 撤销上一次执行: 回滚到 %s" % snap["name"])
            self._send(200, "application/json",
                       json.dumps({"ok": True, "name": snap["name"]}).encode())

        elif path == "/api/show":
            sid = data.get("id")
            if sid is None:
                _show_stop_current()
                log("SHOW 手动停止")
                self._send(200, "application/json", b'{"ok":true,"stopped":true}')
                return
            card = next((c for c in SHOW_CARDS if c["id"] == sid), None)
            if not card:
                self._send(404, "text/plain; charset=utf-8", b"no such card")
                return
            started = run_show(card)     # 内部带"停旧代 + 连点同一张卡忽略"
            if started:
                log("SHOW 启动卡片: %s" % card["name"])
            else:
                log("SHOW 忽略重复点击 — 「%s」已在运行" % card["name"])
            self._send(200, "application/json",
                       json.dumps({"ok": True, "already": not started}).encode("utf-8"))

        elif path == "/api/schedule":
            # 卡片定时触发: mode='delay' delay 秒后; mode='clock' time=HH:MM
            card = next((c for c in SHOW_CARDS if c["id"] == data.get("id")), None)
            if not card:
                self._send(404, "application/json", b'{"ok":false,"error":"no such card"}')
                return
            mode = data.get("mode", "delay")
            try:
                if mode == "clock":
                    hh, mm = [int(x) for x in str(data.get("time", "20:00")).split(":")[:2]]
                    if not (0 <= hh < 24 and 0 <= mm < 60):
                        raise ValueError
                    schedule_card(card, "clock", clock=data.get("time"))
                else:
                    mode = "delay"
                    schedule_card(card, "delay", delay=float(data.get("delay", 10)))
            except (TypeError, ValueError):
                self._send(400, "application/json", b'{"ok":false,"error":"bad time"}')
                return
            self._send(200, "application/json", b'{"ok":true}')

        elif path == "/api/schedcancel":
            try:
                sid = int(data.get("sid", 0))
            except (TypeError, ValueError):
                self._send(400, "application/json",
                           b'{"ok":false,"error":"bad sid"}')
                return
            ok = cancel_schedule(sid)
            self._send(200, "application/json",
                       json.dumps({"ok": ok}).encode())

        elif path == "/api/bridge":
            # 桥接真台开关: addr='IP:PORT' 启动; addr='' 断开
            addr = str(data.get("addr", "")).strip()
            if not addr:
                bridge_stop()
                if BRIDGE_TARGET[0]:       # 用户主动断开 → 不再自动重连
                    BRIDGE_TARGET[0] = ""
                    if not self._cfg_saved("断开记忆"):
                        return
                self._send(200, "application/json", b'{"ok":true,"stopped":true}')
                return
            ok, msg = bridge_start(addr)
            if ok:
                ip, p = addr.rsplit(":", 1)
                BRIDGE_TARGET[0] = "%s:%d" % (ip, int(p))
                if not self._cfg_saved("记住真台地址"):
                    return
                log("BRIDGE 已记住真台地址 %s (下次启动自动重连)" % BRIDGE_TARGET[0])
            self._send(200 if ok else 400, "application/json",
                       json.dumps({"ok": ok, "msg": msg}).encode("utf-8"))

        elif path == "/api/import":
            # 配置导入: 覆盖卡片/控制键/命名/设置 (动作逐条清洗, 防脏数据)
            cfg = data.get("config")
            if not isinstance(cfg, dict):
                self._send(400, "application/json", b'{"ok":false,"error":"bad config"}')
                return
            cards = cfg.get("cards")
            keys = cfg.get("quickKeys")
            if not isinstance(cards, list) or not isinstance(keys, list):
                self._send(400, "application/json",
                           b'{"ok":false,"error":"config missing cards/quickKeys"}')
                return
            clean_cards = []
            import_dropped = 0
            for c in cards:
                if not isinstance(c, dict) or not str(c.get("name", "")).strip():
                    continue
                acts, why = _clean_actions(c.get("actions"))
                if acts is None:
                    acts = []
                import_dropped += len(why)
                clean_cards.append({"id": str(c.get("id") or next_id("c")),
                                    "name": str(c.get("name")).strip(),
                                    "desc": str(c.get("desc", "")).strip() or "导入的演出卡片",
                                    "actions": acts, "fades": [],
                                    "pin": 1 if c.get("pin") else 0,
                                    "next": str(c.get("next") or "")})
            clean_keys = []
            kindmap = {"ch_fader", "bus_fader", "dca_fader", "main_fader",
                       "auxin_fader", "usb_fader", "fxret_fader", "mtx_fader"}
            for k in keys:
                if (isinstance(k, dict) and k.get("kind") in kindmap
                        and str(k.get("name", "")).strip()):
                    try:
                        k_idx = int(k.get("idx", 1) or 1)
                        k_sign = int(k.get("sign", 1) or 1)
                    except (TypeError, ValueError):
                        continue          # 编号/方向不是数字 → 整条跳过, 不猜
                    clean_keys.append({"id": str(k.get("id") or next_id("k")),
                                       "name": str(k["name"]).strip(),
                                       "icon": str(k.get("icon", "⚡"))[:4] or "⚡",
                                       "kind": k["kind"],
                                       "idx": min(max(k_idx,
                                                      1 if k["kind"] != "main_fader" else 0), 32),
                                       "sign": -1 if k_sign < 0 else 1})
            keycfg = cfg.get("keyCfg") if isinstance(cfg.get("keyCfg"), dict) else {}
            # ⚠️ 先把所有可能抛异常的计算做完，**再**动内存。
            #    曾经的顺序是 QUICK_KEYS[:] = ... 在前、float(keycfg[...]) 在后，
            #    于是一个非法步长就会抛在中间：内存已是新配置但 save_user_config()
            #    没执行 → 重启后旧配置复活，内存与磁盘分叉，用户看到"导入成功但丢了"。
            new_step = _finite(keycfg.get("step_db"), KEY_CFG["step_db"])
            new_ramp = _finite(keycfg.get("ramp"), KEY_CFG["ramp"])
            new_step = min(max(new_step, 0.5), 12.0)
            new_ramp = min(max(new_ramp, 0.0), 5.0)
            QUICK_KEYS[:] = clean_keys
            SHOW_CARDS[:] = clean_cards
            KEY_CFG.update({"step_db": new_step, "ramp": new_ramp})
            if isinstance(cfg.get("idSeq"), int):
                ID_SEQ[0] = max(ID_SEQ[0], cfg["idSeq"])
            if isinstance(cfg.get("names"), dict):
                for kk, v in cfg["names"].items():
                    try:
                        g, i = kk.split("|")
                        STATE.names[(g, int(i))] = str(v)
                    except (ValueError, TypeError):
                        pass
            if not self._cfg_saved("配置导入"):
                return
            log("CONFIG 导入完成: %d 张卡片, %d 个控制键%s"
                % (len(clean_cards), len(clean_keys),
                   ("，丢弃 %d 个非法动作" % import_dropped) if import_dropped else ""))
            EVT_SEQ[0] += 1
            EVENTS.append({"id": EVT_SEQ[0], "time": time.strftime("%H:%M:%S"),
                           "text": "📦 配置导入完成 — %d 张卡片 / %d 个控制键%s" % (
                               len(clean_cards), len(clean_keys),
                               ("（丢弃 %d 个非法动作）" % import_dropped) if import_dropped else "")})
            self._send(200, "application/json",
                       json.dumps({"ok": True, "cards": len(clean_cards),
                                   "keys": len(clean_keys),
                                   "droppedActions": import_dropped}).encode())

        elif path == "/api/keyadd":
            # 网页上新增自定义控制键
            kindmap = {"ch": "ch_fader", "bus": "bus_fader", "dca": "dca_fader",
                       "main": "main_fader", "auxin": "auxin_fader", "usb": "usb_fader",
                       "fxret": "fxret_fader", "mtx": "mtx_fader"}
            kind = kindmap.get(data.get("kind"))
            if not kind:
                self._send(400, "text/plain; charset=utf-8", "bad kind".encode())
                return
            try:
                idx = int(data.get("idx", 1))
            except (TypeError, ValueError):
                idx = 1
            idx = min(max(idx, 1 if kind != "main_fader" else 0), 32)
            QUICK_KEYS.append({
                "id": next_id("k"),
                "name": str(data.get("name", "")).strip() or "新按键",
                "icon": str(data.get("icon", "")).strip() or "⚡",
                "kind": kind, "idx": idx,
                "sign": -1 if int(data.get("sign", 1)) < 0 else 1,
            })
            if not self._cfg_saved("新增控制键"):
                return
            log("KEY 新增控制键: %s" % QUICK_KEYS[-1]["name"])
            self._send(200, "application/json", b'{"ok":true}')

        elif path == "/api/keydel":
            QUICK_KEYS[:] = [k for k in QUICK_KEYS if k["id"] != data.get("id")]
            if not self._cfg_saved("删除控制键"):
                return
            log("KEY 删除控制键: %s" % data.get("id"))
            self._send(200, "application/json", b'{"ok":true}')

        elif path == "/api/keyedit":
            # 网页上编辑已有控制键
            target = next((k for k in QUICK_KEYS if k["id"] == data.get("id")), None)
            if not target:
                self._send(404, "application/json", b'{"ok":false,"error":"key not found"}')
                return
            kindmap = {"ch": "ch_fader", "bus": "bus_fader", "dca": "dca_fader",
                       "main": "main_fader", "auxin": "auxin_fader", "usb": "usb_fader",
                       "fxret": "fxret_fader", "mtx": "mtx_fader"}
            kind = kindmap.get(data.get("kind"))
            if kind:
                target["kind"] = kind
            try:
                idx = int(data.get("idx", target["idx"]))
            except (TypeError, ValueError):
                idx = target["idx"]
            target["idx"] = min(max(idx, 1 if target["kind"] != "main_fader" else 0), 32)
            name = str(data.get("name", "")).strip()
            if name:
                target["name"] = name
            icon = str(data.get("icon", "")).strip()
            if icon:
                target["icon"] = icon
            try:
                sign = int(data.get("sign", target["sign"]))
            except (TypeError, ValueError):
                sign = target["sign"]
            target["sign"] = -1 if sign < 0 else 1
            if not self._cfg_saved("编辑控制键"):
                return
            log("KEY 编辑控制键: %s" % target["name"])
            self._send(200, "application/json", b'{"ok":true}')

        elif path == "/api/cardedit":
            # 网页上编辑已有演出卡片
            target = next((c for c in SHOW_CARDS if c["id"] == data.get("id")), None)
            if not target:
                self._send(404, "application/json", b'{"ok":false,"error":"card not found"}')
                return
            card = data.get("card")
            if not isinstance(card, dict):
                # 少了 card 包裹 → 曾经会静默 {"ok":true} 而一个字段都没改 (假成功);
                # 平铺 payload 也会落到这里, 报错要指向真正的原因。
                self._send(400, "application/json", json.dumps(
                    {"ok": False,
                     "error": '卡片字段要包在 {"id":..., "card": {...}} 里'
                              ' ( received keys: %s )' % ",".join(sorted(data.keys())[:6])
                     }).encode("utf-8"))
                return
            new_name = str(card.get("name", "")).strip()
            if new_name:
                target["name"] = new_name
            if "desc" in card:
                target["desc"] = str(card.get("desc", "")).strip() or "自定义演出卡片"
            # ⚠️ actions 是**显式三元**：字段存在就整体替换（空数组 = 清空），
            #    字段不存在才不动。曾经的 `and card["actions"]` + `if actions:` 两道闸
            #    会造成两种假成功：混入非法动作时静默少存、传空数组时静默不删。
            dropped = []
            if "actions" in card:
                acts, dropped = _clean_actions(card.get("actions"))
                if acts is None:
                    self._send(400, "application/json", json.dumps(
                        {"ok": False, "error": "；".join(dropped)}).encode("utf-8"))
                    return
                target["actions"] = acts
                if dropped:
                    log("SHOW 编辑卡片 %s: 丢弃 %d 个动作 (%s)"
                        % (target["name"], len(dropped), "; ".join(dropped)))
            if "pin" in card:
                target["pin"] = 1 if card.get("pin") else 0
            if "next" in card:      # 执行完自动接续的下一张卡片 (空=不接续)
                nid = str(card.get("next") or "").strip()
                target["next"] = nid if nid and any(c["id"] == nid for c in SHOW_CARDS) else ""
            if not self._cfg_saved("编辑卡片"):
                return
            log("SHOW 编辑卡片: %s" % target["name"])
            self._send(200, "application/json", json.dumps(
                {"ok": True, "dropped": dropped}).encode("utf-8"))

        elif path == "/api/cardpin":
            # 置顶/取消置顶
            target = next((c for c in SHOW_CARDS if c["id"] == data.get("id")), None)
            if not target:
                self._send(404, "application/json", b'{"ok":false,"error":"card not found"}')
                return
            target["pin"] = 0 if target.get("pin") else 1
            if not self._cfg_saved("卡片置顶"):
                return
            log("SHOW %s: %s" % ("置顶卡片" if target.get("pin") else "取消置顶", target["name"]))
            self._send(200, "application/json", b'{"ok":true}')

        elif path == "/api/cardadd":
            # 网页上新建演出卡片
            card = data.get("card")
            if not isinstance(card, dict):
                # 常见手误: 把字段平铺在顶层 (少了 card 包裹)。曾经的报错是
                # "actions 不是数组" —— 文不对题, 看着像动作格式错, 实际是包错了层。
                self._send(400, "application/json", json.dumps(
                    {"ok": False,
                     "error": '卡片字段要包在 {"card": {...}} 里 ( received keys: %s )'
                              % ",".join(sorted(data.keys())[:6])}).encode("utf-8"))
                return
            actions, dropped = _clean_actions(card.get("actions"))
            if actions is None:
                self._send(400, "application/json", json.dumps(
                    {"ok": False, "error": "；".join(dropped)}).encode("utf-8"))
                return
            if not actions:
                # 空动作的卡片跑起来什么都不做, 只会让人以为"卡片坏了"
                self._send(400, "application/json", json.dumps(
                    {"ok": False,
                     "error": "卡片至少要有一个有效动作"}).encode("utf-8"))
                return
            SHOW_CARDS.append({
                "id": next_id("c"),
                "name": str(card.get("name", "")).strip() or "🎬 新卡片",
                "desc": str(card.get("desc", "")).strip() or "自定义演出卡片",
                "actions": actions, "fades": [],
                "pin": 1 if card.get("pin") else 0,
                "next": "",
            })
            if not self._cfg_saved("新建卡片"):
                return
            log("SHOW 新建卡片: %s (%d 个动作%s)"
                % (SHOW_CARDS[-1]["name"], len(actions),
                   "，丢弃 %d 个: %s" % (len(dropped), "; ".join(dropped)) if dropped else ""))
            self._send(200, "application/json", json.dumps(
                {"ok": True, "id": SHOW_CARDS[-1]["id"],
                 "dropped": dropped}).encode())

        elif path == "/api/carddel":
            SHOW_CARDS[:] = [c for c in SHOW_CARDS if c["id"] != data.get("id")]
            for s in [x for x in list(SCHEDULES) if x["card_id"] == data.get("id")]:
                cancel_schedule(s["sid"])
            if not self._cfg_saved("删除卡片"):
                return
            log("SHOW 删除卡片: %s" % data.get("id"))
            self._send(200, "application/json", b'{"ok":true}')

        elif path == "/api/snapshot":
            act = data.get("action")
            if act == "save":
                try:
                    snap, saved = save_snapshot(data.get("name"), scope=data.get("scope"))
                except ValueError as e:
                    # 非法范围 (一个组/一个参数都不合法, 编号全越界...) → 明确拒。
                    # 曾经的写法是静默回落全量: "只想存 ch1-2" 变成存了 158 个值,
                    # 回归时整台被换掉 —— 比报难查得多。
                    self._send(400, "application/json", json.dumps(
                        {"ok": False, "error": str(e)}, ensure_ascii=False).encode("utf-8"))
                    return
                if snap["count"] <= 0:
                    # 空范围 = 一条永远不会生效的预设，属于"假成功"，直接拒
                    SNAPSHOTS[:] = [s for s in SNAPSHOTS if s["id"] != snap["id"]]
                    self._send(400, "application/json",
                               json.dumps({"ok": False, "error": "范围里没有可保存的参数"},
                                          ensure_ascii=False).encode("utf-8"))
                    return
                if not saved:
                    self._send(500, "application/json", json.dumps(
                        {"ok": False,
                         "error": "预设保存失败: 无法写入配置文件 (%s) — 预设只在内存中, "
                                  "重启后会丢失。请检查所在目录是否可写、磁盘是否已满。"
                                  % CONFIG_PATH[0]},
                        ensure_ascii=False).encode("utf-8"))
                    return
                self._send(200, "application/json",
                           json.dumps({"ok": True, "id": snap["id"],
                                       "count": snap["count"],
                                       "scopeText": preset_scope_text(snap["scope"])}).encode())
            elif act == "recall":
                try:
                    sid = int(data.get("id", 0))
                except (TypeError, ValueError):
                    self._send(400, "application/json",
                               b'{"ok":false,"error":"bad id"}')
                    return
                snap = recall_snapshot(sid, data.get("seconds", 3.0))
                if not snap:
                    self._send(404, "text/plain; charset=utf-8", b"no such snapshot")
                    return
                self._send(200, "application/json", b'{"ok":true}')
            elif act == "delete":
                try:
                    did = int(data.get("id", 0))
                except (TypeError, ValueError):
                    self._send(400, "application/json",
                               b'{"ok":false,"error":"bad id"}')
                    return
                SNAPSHOTS[:] = [s for s in SNAPSHOTS if s["id"] != did]
                # ⚠️ 删除也必须落盘: 曾经只改内存 → 接口返 ok 但重启后预设复活,
                #    又是一次"假成功"。
                if not self._cfg_saved("删除预设"):
                    return
                self._send(200, "application/json", b'{"ok":true}')
            elif act == "stop":
                _recall_stop_current()
                self._send(200, "application/json", b'{"ok":true}')
            else:
                self._send(400, "text/plain; charset=utf-8", b"bad action")
        else:
            self._send(404, "text/plain; charset=utf-8", b"not found")


# ==================================================================
# ==== x32sim/app.py
# ==================================================================
# -*- coding: utf-8 -*-
"""x32sim/app — 装配: main() / WebServer / sink 注册"""

import argparse
import os
import socket
import socketserver
import sys
import threading
import time
from http.server import ThreadingHTTPServer

qr_block = block_lines


class WebServer(ThreadingHTTPServer):
    """跳过 HTTPServer 默认 server_bind() 里的 socket.getfqdn() 反向 DNS 解析。

    本机装了 ZeroTier/多个虚拟网卡时, 这一步会卡十几秒, 期间 OSC 主循环还没开始 —
    表现为"服务刚起时连不上", 也是之前 Web 启动慢的真正原因。"""

    def server_bind(self):
        socketserver.TCPServer.server_bind(self)
        host, port = self.server_address[:2]
        self.server_name = host
        self.server_port = port


def _register_sinks():
    """装配写出口。state 只认 SINKS, 不认识 bridge (依赖方向: app → 两者)。"""
    if BRIDGE_SINK not in SINKS:
        SINKS.append(BRIDGE_SINK)


def main():
    parser = argparse.ArgumentParser(description="X32 虚拟调音台模拟器")
    # 端口默认值留空(None), 解析完配置文件后再定 —— 优先级见 resolve_ports()
    parser.add_argument("--port", type=int, default=None,
                        help="OSC/UDP 端口 (默认 10023, 或在网页设置页里自定义)")
    parser.add_argument("--bind", default="0.0.0.0", help="监听地址,默认所有网卡")
    # 发布为在线应用时,沙箱通过 PORT 环境变量注入唯一的 HTTP 端口
    _env_port = os.environ.get("PORT")
    if _env_port and _env_port.isdigit():
        ENV_WEB_PORT[0] = int(_env_port)
    parser.add_argument("--web-port", type=int, default=None,
                        help="网页控制台端口,0=关闭 (默认 8080, 或在网页设置页里自定义)")
    parser.add_argument("--bridge", default="", metavar="IP:PORT",
                        help="桥接真台: 写入转发+保活+回读 (联调可指向另一模拟器实例)")
    parser.add_argument("--config", default="", help="配置文件路径 (多实例联调时各自独立)")
    # 数字增益量程: 手册写 [-12,12] (旧固件), 实测 1.15+ 是 [-18,18]。
    # 默认 18 —— 若你的台子是老固件, 用 --trim-range 12 启动, 本地量程会同步
    # 收到 ±12: 界面显示多少, 台子上就是多少, 不会出现"本地 15 / 真台 12"的静默差。
    parser.add_argument("--trim-range", type=float, default=None, metavar="DB",
                        help="数字增益量程 ±db (12=旧固件, 18=新固件; 默认按控台能力)")
    # 真台 /xremote 只推变化, 不推初始全量；需要初始值的客户端应自己 GET 或 /subscribe。
    # 这个开关是**非标准增强**, 默认关: 打开后新订阅者第一轮能收到当前全台快照,
    # 便于自研客户端联调, 但不要依赖它 —— 上真台没有这个行为。
    parser.add_argument("--xremote-snapshot", action="store_true",
                        help="新订阅者首帧补一次全量 (非真台行为, 默认关)")
    # 启动时在终端打印扫码二维码 (手机扫一下就能进网页控制台, 不用手输 IP)。
    # 默认开, 但只在真正的终端里打印: 输出重定向到日志文件/在线沙箱时不打。
    parser.add_argument("--no-qr", action="store_true",
                        help="启动时不打印扫码二维码 (手机仍可手输 IP 访问)")
    # 发送取点 (enum) 的线上形式。协议规定枚举可以用整数索引或名字符串发送,
    # 真台两种都收; 回包形式随固件而异。默认索引; 若真台回字符串读不回来, 用 label。
    parser.add_argument("--tap-wire", choices=("index", "label"), default="index",
                        help="发送取点线上形式: index=整数(默认) / label=字符串")
    args = parser.parse_args()

    if args.xremote_snapshot:
        XREMOTE_SNAPSHOT[0] = True
        log("订阅: 新订阅者首帧补全量 (非真台行为, 仅调试用)")
    if args.tap_wire != "index":
        _chg = set_enum_wire({"send_tap": args.tap_wire})
        log("枚举线上形式: %s (真台若回字符串, 用这个对齐)" % (", ".join(_chg) or "无"))

    _register_sinks()          # 写出口就位后, 任何 set_value 都能被桥接看到
    # 量程覆盖必须在 load_user_config 之前装好: 否则配置文件里的旧值会按宽量程
    # 读进来, 之后第一次写入才收窄, 中间那段时间界面和台子是对不上的。
    _lims = dict(getattr(profile(), "param_limits", {}) or {})
    if args.trim_range:
        _r = abs(float(args.trim_range))
        _lims["ch_trim"] = (-_r, _r)
        log("量程: 数字增益 ±%g dB (按固件能力收窄; 旧固件请用 12)" % _r)
    set_param_limits(_lims)
    if args.config:
        CONFIG_PATH[0] = args.config
    load_user_config()

    # 配置文件读完之后再定端口（命令行 > PORT 环境变量 > 配置文件 > 内置默认）
    args.port, args.web_port = resolve_ports(args.port, args.web_port)
    if args.port == args.web_port and args.web_port > 0:
        log("端口冲突: OSC/UDP 与网页端口不能相同 (%d), 网页端口回退为默认 %d"
            % (args.port, DEF_WEB_PORT))
        args.web_port = DEF_WEB_PORT
        if args.web_port == args.port:
            log("仍与 OSC 端口相同, 关闭网页控制台")
            args.web_port = 0
    if PORT_CFG["udp"] is not None or PORT_CFG["web"] is not None:
        log("使用自定义端口: OSC/UDP %d · 网页 %s"
            % (args.port, (args.web_port if args.web_port > 0 else "已关闭")))

    if args.bridge:
        ok, msg = bridge_start(args.bridge)
        log(("BRIDGE " + msg) if ok else ("BRIDGE 参数无效: " + msg))
    elif BRIDGE_TARGET[0]:
        # 上次连过的真台 → 启动后自动重连: 手机打开网页时就已经连上台子了
        def _auto_reconnect():
            time.sleep(3.0)
            ok, msg = bridge_start(BRIDGE_TARGET[0])
            log(("BRIDGE 自动重连: " + msg) if ok else ("BRIDGE 自动重连失败: " + msg))
        threading.Thread(target=_auto_reconnect, daemon=True).start()

    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        sock.bind((args.bind, args.port))
    except OSError as e:
        log("绑定端口失败: %s" % e)
        sys.exit(1)
    MAIN_SOCK[0] = sock

    ip = get_lan_ip()
    log("X32 虚拟调音台已启动  UDP %s:%d" % (ip, args.port))
    LAN_IP[0], UDP_PORT[0], WEB_PORT[0] = ip, args.port, args.web_port

    if args.web_port > 0:
        try:
            web = WebServer(("0.0.0.0", args.web_port), WebHandler)
            threading.Thread(target=web.serve_forever, daemon=True).start()
            log("网页控制台已启动  http://localhost:%d  (手机/电脑浏览器均可打开)" % args.web_port)
            # 手机扫码入口: 比让用户在手机上敲 192.168.x.x:8080 省事得多。
            # 只在交互式终端里打 —— 重定向到日志、或被平台托管时没有意义。
            if not args.no_qr and sys.stdout.isatty() and not ip.startswith("127."):
                url = "http://%s:%d/" % (ip, args.web_port)
                log("手机扫码直达 (同一 WiFi): %s  [--no-qr 可关闭]" % url)
                try:
                    for line in qr_block(url, border=2):
                        print(line)
                    print()
                except Exception as e:      # 二维码只是便利功能, 失败不能挡住启动
                    log("二维码生成失败: %r" % e)
                try:
                    # App 扫码用：带 OSC 端口，改过端口也不会连错（见 x32sim/pair.py）
                    log("App 扫码配对码: %s" % pair_text(ip, args.port, args.web_port))
                except ValueError:
                    pass
        except OSError as e:
            log("网页控制台启动失败(端口 %d 被占用?): %s" % (args.web_port, e))

    log("iOS App 中把调音台 IP 填为: %s  (若为 0.0.0.0 请用本机局域网 IP)" % ip)
    log("等待指令... Ctrl+C 退出\n")

    threading.Thread(target=meter_streamer, args=(sock,), daemon=True).start()
    # 自动增益/推子: 50ms 一拍, 默认总开关开但单通道都要显式启用
    threading.Thread(target=rider_loop, daemon=True).start()

    try:
        while True:
            # Windows 特性: 客户端退出后端口不可达,下一次 recvfrom 会抛
            # ConnectionResetError (10054),必须捕获并继续,否则主循环崩掉
            try:
                data, addr = sock.recvfrom(4096)
            except ConnectionResetError:
                continue
            # 任何畸形包都不允许杀死主循环 (OSC 是 UDP, 什么包都可能飞进来)
            try:
                msgs = decode_packet(data)
            except Exception as e:
                log("收到无法解析的 UDP 包 (%d 字节), 已忽略: %r" % (len(data), e))
                continue
            for msg in msgs:
                try:
                    handle(msg, addr, sock)
                except Exception as e:
                    log("处理 %s 出错: %r" % (msg.address, e))
    except KeyboardInterrupt:
        log("\n已退出")


if __name__ == "__main__":
    main()
